/* Câu hỏi các đề Ngữ văn lớp 6 có sẵn. Danh mục (tên, khối, môn, số phút, số câu): data/banks/index.js.
   App chỉ tải file này khi mở một đề trong đó. Dạng câu hỏi: xem đầu data/banks/index.js. */
window.ONTAP_SEED_QUESTIONS = Object.assign(window.ONTAP_SEED_QUESTIONS || {}, {
  /* ---------- Ngữ văn 6 · Kiểm tra cuối học kì I (Kết nối tri thức, Bài 1–5) ----------
     Hai đề cùng phạm vi: Bài 1 Tôi và các bạn, Bài 2 Gõ cửa trái tim, Bài 3 Yêu thương và chia sẻ,
     Bài 4 Quê hương yêu dấu, Bài 5 Những nẻo đường xứ sở; phần Tiếng Việt của năm bài.
     Văn bản trong sách theo bản in năm 2026 (Ngữ văn 6 tập một, mã G1HH6V001h26): văn bản 3 của Bài 1 là «Tia nắng hạt mưa»
     (Lệ Bình, tr. 27), của Bài 2 là «Hương và Phai» (trích, Nguyễn Minh Châu, tr. 48), thay hai văn bản của bản in trước
     (L37 ở docs/SUA-LOI-CHAY-THU.md); văn bản của Bài 4, Bài 5 mà các câu nhắc tới vẫn có trong mục lục bản in năm 2026 (tr. 6–7).
     Đoạn văn, đoạn thơ đọc hiểu do người soạn tự viết (trừ ca dao, tục ngữ dân gian).
     Mức độ lv ghi ở Phiên N4b (nội dung, chủ đề giữ nguyên); hai đề cùng các câu riêng của "van6-ck1-ngau-nhien" bên dưới
     là kho của đề ngẫu nhiên. Cách xếp mức: nhớ tác giả, thể loại, khái niệm, nhận ra từ láy, cụm từ, biện pháp tu từ (đề bài
     đã chỉ ra dấu hiệu) là Biết; nghĩa của từ, công dụng dấu câu, từ đồng âm và từ đa nghĩa, ngôi kể và thể thơ của một đoạn
     chưa học, ý nghĩa của chi tiết là Hiểu; đếm từ trong câu, tìm vần trong hai dòng lục bát chưa học là Vận dụng. */
  "van6-ck1-de1": {
    note: "Phần đọc hiểu và tiếng Việt của học kì I (Bài 1–5), sách Kết nối tri thức. Đề thật còn có phần viết bài văn.",
    questions: [
      { topic: "Tôi và các bạn", type: "mc", q: "Truyện đồng thoại là truyện viết cho trẻ em. Nhân vật trong truyện đồng thoại thường là:", o: ["Loài vật hoặc đồ vật được nhân hoá", "Các vị thần trên trời", "Những người anh hùng có thật trong lịch sử", "Chỉ có con người trong đời sống hằng ngày"], x: "Nhân vật của truyện đồng thoại thường là loài vật, đồ vật được nhân hoá: biết nói, biết nghĩ như người nhưng vẫn giữ đặc điểm của loài, của vật.", lv: 1 },
      { topic: "Tôi và các bạn", type: "mc", q: "Văn bản “Bài học đường đời đầu tiên” (Tô Hoài) được kể bằng lời của nhân vật nào?", o: ["Dế Mèn", "Dế Choắt", "Chị Cốc", "Một người kể giấu mặt, không có trong truyện"], x: "Dế Mèn xưng “tôi”, tự kể lại câu chuyện của mình. Truyện được kể theo ngôi thứ nhất.", lv: 1 },
      { topic: "Dấu câu", type: "mc", q: "Trong câu «Vịnh Hạ Long – di sản thiên nhiên thế giới – thu hút rất nhiều du khách.», hai dấu gạch ngang dùng để làm gì?", o: ["Đánh dấu phần giải thích", "Đánh dấu lời đối thoại của nhân vật", "Đánh dấu các ý được liệt kê", "Nối các từ ngữ trong một liên danh"], x: "Phần nằm giữa hai dấu gạch ngang (“di sản thiên nhiên thế giới”) giải thích thêm cho “Vịnh Hạ Long”. Câu không có lời nhân vật, không liệt kê ý, cũng không nối hai tên riêng.", lv: 2 },
      { topic: "Tôi và các bạn", type: "mc", q: "Đọc đoạn văn: «Tôi là Sẻ Nâu, nhà ở bụi tre đầu làng. Sáng nào tôi cũng dậy sớm, chải lại bộ lông cho thật mượt rồi bay đi chào các bạn. Hôm ấy, thấy Chích Bông bị đau cánh nằm dưới gốc tre, tôi vội tha từng hạt thóc về cho bạn.» Đoạn văn được kể theo ngôi thứ mấy?", o: ["Ngôi thứ nhất", "Ngôi thứ hai", "Ngôi thứ ba", "Chích Bông là người kể chuyện"], x: "Người kể là Sẻ Nâu, xưng “tôi” và tham gia vào câu chuyện, nên đoạn văn kể theo ngôi thứ nhất.", lv: 2 },
      { topic: "Từ đơn và từ phức", type: "mc", q: "Từ nào dưới đây là từ láy?", o: ["lấp lánh", "bàn ghế", "quần áo", "xe đạp"], x: "“Lấp lánh” có hai tiếng lặp lại âm đầu “l”, là từ láy. “Bàn ghế”, “quần áo”, “xe đạp” là từ ghép vì các tiếng đều có nghĩa và quan hệ với nhau về nghĩa.", lv: 1 },
      { topic: "Từ đơn và từ phức", type: "tf", q: "Từ “xanh xanh” là từ ghép.", a: false, x: "“Xanh xanh” lặp lại toàn bộ tiếng “xanh”, là từ láy (láy toàn bộ), không phải từ ghép.", lv: 1 },
      { topic: "Từ đơn và từ phức", type: "fill", q: "Câu “Mẹ mua cho em một chiếc cặp.” gồm ___ từ đơn.", ans: ["7", "bảy", "bảy từ"], x: "Câu có 7 từ: Mẹ / mua / cho / em / một / chiếc / cặp. Mỗi từ chỉ có một tiếng nên đều là từ đơn.", lv: 3 },
      { topic: "Nghĩa của từ", type: "mc", q: "Từ “hiền lành” trong câu “Bác nông dân rất hiền lành.” có nghĩa là:", o: ["Tốt bụng, không gây hại cho ai", "Thông minh, nhanh trí", "Nóng nảy, dễ nổi giận", "Giàu có, sung túc"], x: "“Hiền lành” chỉ tính nết tốt, dễ gần, không làm hại ai.", lv: 2 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Câu “Đôi mắt em bé sáng như sao.” sử dụng biện pháp tu từ nào?", o: ["So sánh", "Nhân hoá", "Ẩn dụ", "Hoán dụ"], x: "Câu đối chiếu đôi mắt với ngôi sao, có từ so sánh “như”: đó là biện pháp so sánh.", lv: 1 },
      { topic: "Gõ cửa trái tim", type: "mc", q: "Bài thơ “Chuyện cổ tích về loài người” là của nhà thơ nào?", o: ["Xuân Quỳnh", "Tô Hoài", "Lâm Thị Mỹ Dạ", "Thép Mới"], x: "“Chuyện cổ tích về loài người” là bài thơ của Xuân Quỳnh, học ở Bài 2 Gõ cửa trái tim. Tô Hoài viết truyện, Thép Mới viết “Cây tre Việt Nam”, Lâm Thị Mỹ Dạ viết “Chuyện cổ nước mình”.", lv: 1 },
      { topic: "Gõ cửa trái tim", type: "mc", q: "Đọc đoạn thơ: «Sáng nay mẹ đi chợ / Con đứng đợi đầu ngõ / Mẹ về, quang gánh nhỏ / Có cả nắng trong đó.» Đoạn thơ được viết theo thể thơ nào?", o: ["Thơ năm chữ", "Thơ bốn chữ", "Thơ lục bát", "Thơ bảy chữ"], x: "Mỗi dòng có 5 tiếng, ví dụ: Sáng / nay / mẹ / đi / chợ. Đó là thơ năm chữ.", lv: 2 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Ca dao: «Thuyền về có nhớ bến chăng / Bến thì một dạ khăng khăng đợi thuyền.» Tác giả dân gian dùng hình ảnh “thuyền” để chỉ người ra đi, “bến” để chỉ người ở lại. Đó là biện pháp tu từ nào?", o: ["Ẩn dụ", "So sánh", "Điệp ngữ", "Hoán dụ"], x: "“Thuyền” chỉ người ra đi, “bến” chỉ người ở lại chờ đợi, dựa trên nét giống nhau (thuyền đi rồi về, bến đứng yên một chỗ). Gọi tên sự vật này bằng tên sự vật khác có nét tương đồng là ẩn dụ.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "tf", q: "Trong đoạn thơ «Nhớ con sông quê / Nhớ hàng tre xanh / Nhớ lời mẹ ru», từ “nhớ” được lặp lại là biện pháp điệp ngữ.", a: true, x: "Từ “nhớ” được lặp lại ở đầu ba dòng thơ để nhấn mạnh nỗi nhớ quê. Đó là điệp ngữ.", lv: 1 },
      { topic: "Yêu thương và chia sẻ", type: "mc", q: "Truyện “Cô bé bán diêm” là của nhà văn nào?", o: ["An-đéc-xen", "Ta-go", "Thạch Lam", "Tô Hoài"], x: "“Cô bé bán diêm” là truyện của nhà văn Đan Mạch An-đéc-xen, học ở Bài 3 Yêu thương và chia sẻ.", lv: 1 },
      { topic: "Yêu thương và chia sẻ", type: "tf", q: "Trong truyện “Gió lạnh đầu mùa” của Thạch Lam, nhân vật Sơn là người kể chuyện, xưng “tôi”.", a: false, x: "Truyện được kể theo ngôi thứ ba: người kể giấu mình, gọi nhân vật là Sơn, Lan, Hiên. Sơn không xưng “tôi” kể chuyện.", lv: 1 },
      { topic: "Yêu thương và chia sẻ", type: "mc", q: "Đọc đoạn văn: «Chiều mưa, Lan thấy Hoà đứng nép dưới mái hiên, áo ướt sũng. Lan chạy lại, nghiêng chiếc ô của mình che cho bạn, còn một bên vai mình thì ướt.» Chi tiết Lan nghiêng ô che cho bạn cho thấy Lan là người thế nào?", o: ["Biết quan tâm, chia sẻ với bạn", "Thích khoe đồ dùng mới", "Vụng về, hay quên", "Nhút nhát, sợ mưa"], x: "Lan chịu ướt một bên vai để che cho Hoà: Lan biết quan tâm, nhường nhịn và chia sẻ với bạn.", lv: 2 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "mc", q: "Cụm từ nào dưới đây là cụm danh từ?", o: ["những bông hoa đỏ thắm", "đang chạy rất nhanh", "rất xanh tươi", "sẽ đi học sớm"], x: "“Những bông hoa đỏ thắm” có danh từ “hoa” làm trung tâm. “Đang chạy rất nhanh”, “sẽ đi học sớm” là cụm động từ; “rất xanh tươi” là cụm tính từ.", lv: 1 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "mc", q: "Trong cụm động từ “đang đọc sách trong thư viện”, động từ trung tâm là:", o: ["đọc", "đang", "sách", "thư viện"], x: "“Đọc” là động từ chỉ hoạt động, làm trung tâm. “Đang” bổ sung ý thời gian; “sách”, “trong thư viện” bổ sung ý đối tượng và nơi chốn.", lv: 1 },
      { topic: "Quê hương yêu dấu", type: "mc", q: "Thể thơ lục bát gồm các cặp câu thơ. Mỗi cặp có:", o: ["Một dòng sáu tiếng và một dòng tám tiếng", "Hai dòng bảy tiếng", "Một dòng năm tiếng và một dòng bảy tiếng", "Hai dòng tám tiếng"], x: "“Lục” là sáu, “bát” là tám: dòng trên sáu tiếng (dòng lục), dòng dưới tám tiếng (dòng bát).", lv: 1 },
      { topic: "Quê hương yêu dấu", type: "fill", q: "Trong thơ lục bát, tiếng thứ sáu của dòng sáu vần với tiếng thứ ___ của dòng tám.", ans: ["6", "sáu", "thứ sáu", "thứ 6"], x: "Tiếng thứ sáu dòng lục vần với tiếng thứ sáu dòng bát; tiếng thứ tám dòng bát lại vần với tiếng thứ sáu của dòng lục tiếp theo.", lv: 1 },
      { topic: "Từ đồng âm và từ đa nghĩa", type: "mc", q: "Từ “chân” trong “chân bàn”, “chân núi”, “chân tường” là:", o: ["Từ đa nghĩa", "Từ đồng âm", "Từ láy", "Từ trái nghĩa"], x: "Các nghĩa đều chỉ phần dưới cùng của sự vật, có liên hệ với nghĩa gốc “chân” của người, con vật. Một từ có nhiều nghĩa liên quan với nhau là từ đa nghĩa.", lv: 2 },
      { topic: "Từ đồng âm và từ đa nghĩa", type: "tf", q: "Từ “đường” trong “con đường làng” và “bát chè có nhiều đường” là hai từ đồng âm.", a: true, x: "“Đường” để đi lại và “đường” để ăn (vị ngọt) có âm giống nhau nhưng nghĩa không liên quan gì đến nhau, nên là từ đồng âm.", lv: 2 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Trong câu “Cả lớp vỗ tay khen bạn Minh.”, từ “lớp” được dùng để chỉ các bạn học sinh trong lớp. Đây là biện pháp tu từ nào?", o: ["Hoán dụ", "Ẩn dụ", "So sánh", "Điệp ngữ"], x: "Lấy “lớp” (nơi chứa đựng) để chỉ những người ở trong lớp: gọi tên sự vật bằng tên sự vật có quan hệ gần gũi với nó là hoán dụ.", lv: 1 },
      { topic: "Những nẻo đường xứ sở", type: "mc", q: "Du kí là thể loại ghi chép về:", o: ["Những chuyến đi, những điều người viết tận mắt thấy, tai nghe", "Những câu chuyện tưởng tượng về loài vật", "Những sự tích giải thích nguồn gốc sự vật", "Những kinh nghiệm về thời tiết"], x: "Du kí ghi lại chuyến đi đến một vùng đất, kể và tả những điều người viết trực tiếp trải qua, thường kể theo ngôi thứ nhất.", lv: 1 },
      { topic: "Những nẻo đường xứ sở", type: "tf", q: "Văn bản “Cô Tô” là của nhà văn Thạch Lam.", a: false, x: "“Cô Tô” là bài kí của nhà văn Nguyễn Tuân, học ở Bài 5 Những nẻo đường xứ sở. Thạch Lam viết “Gió lạnh đầu mùa”.", lv: 1 }
    ]
  },
  "van6-ck1-de2": {
    note: "Phần đọc hiểu và tiếng Việt của học kì I (Bài 1–5), sách Kết nối tri thức. Đề thật còn có phần viết bài văn.",
    questions: [
      { topic: "Tôi và các bạn", type: "mc", q: "Văn bản “Tia nắng hạt mưa” của Lệ Bình thuộc thể loại nào?", o: ["Thơ", "Truyện đồng thoại", "Du kí", "Ca dao"], x: "“Tia nắng hạt mưa” là một bài thơ, học ở Bài 1 Tôi và các bạn: bài chia thành các khổ, mỗi dòng sáu tiếng, nói về tình bạn tuổi học trò. Ca dao là thơ dân gian, không ghi tên tác giả.", lv: 1 },
      { topic: "Tôi và các bạn", type: "mc", q: "Trong “Bài học đường đời đầu tiên”, vì sao Dế Choắt chết?", o: ["Bị chị Cốc mổ vì Dế Mèn trêu chị Cốc", "Bị ốm vì trời rét", "Bị Dế Mèn đánh", "Bị ngã xuống hố sâu"], x: "Dế Mèn hát trêu chị Cốc rồi chui vào hang. Chị Cốc tưởng Dế Choắt trêu mình nên mổ Dế Choắt. Dế Mèn rút ra bài học về thói hung hăng, xốc nổi.", lv: 1 },
      { topic: "Tôi và các bạn", type: "mc", q: "Đọc đoạn văn: «Mèo Mướp nằm sưởi nắng trên hiên. Thấy Chuột Nhắt chạy qua, nó chỉ khẽ mở một mắt rồi lại lim dim ngủ. Nó nghĩ bụng: “Hôm nay no rồi, để mai tính.”» Đoạn văn được kể theo ngôi thứ mấy?", o: ["Ngôi thứ ba", "Ngôi thứ nhất", "Ngôi thứ hai", "Do Chuột Nhắt xưng “tôi” kể lại"], x: "Người kể giấu mình, gọi nhân vật bằng tên (Mèo Mướp) và “nó”, không xưng “tôi”: đoạn văn kể theo ngôi thứ ba.", lv: 2 },
      { topic: "Từ đơn và từ phức", type: "mc", q: "Nhóm từ nào dưới đây gồm toàn từ láy?", o: ["lom khom, thoăn thoắt, rì rào", "nhà cửa, lom khom, sông núi", "bàn ghế, xinh xắn, sách vở", "học hành, chăm chỉ, đi đứng"], x: "“Lom khom”, “thoăn thoắt”, “rì rào” đều có các tiếng lặp lại âm hoặc vần. Các nhóm khác có lẫn từ ghép như “nhà cửa”, “sông núi”, “bàn ghế”, “sách vở”, “học hành”, “đi đứng”.", lv: 1 },
      { topic: "Từ đơn và từ phức", type: "tf", q: "Từ “hoa hồng” là từ láy.", a: false, x: "“Hoa hồng” gồm hai tiếng đều có nghĩa: “hoa” chỉ chung, “hồng” nói rõ đó là loại hoa nào. Hai tiếng ghép với nhau về nghĩa nên là từ ghép, không phải từ láy.", lv: 1 },
      { topic: "Nghĩa của từ", type: "mc", q: "Từ “thoăn thoắt” trong câu “Đôi tay bà thoăn thoắt đan len.” có nghĩa là:", o: ["Nhanh và liên tục", "Chậm chạp, nặng nề", "Run run, yếu ớt", "Nhẹ nhàng, êm ái"], x: "“Thoăn thoắt” tả động tác (thường của tay, chân) nhanh, nhẹ và liên tục.", lv: 2 },
      { topic: "Biện pháp tu từ", type: "tf", q: "Câu “Ông mặt trời thức dậy, vươn vai chào buổi sáng.” sử dụng biện pháp tu từ nhân hoá.", a: true, x: "Mặt trời được gọi là “ông” và có hoạt động như người (thức dậy, vươn vai, chào): đó là nhân hoá.", lv: 1 },
      { topic: "Gõ cửa trái tim", type: "mc", q: "Bài thơ “Mây và sóng” là của nhà thơ nào?", o: ["Ta-go", "Xuân Quỳnh", "An-đéc-xen", "Nguyễn Tuân"], x: "“Mây và sóng” là bài thơ của nhà thơ Ấn Độ Ta-go, học ở Bài 2 Gõ cửa trái tim.", lv: 1 },
      { topic: "Gõ cửa trái tim", type: "tf", q: "Trong truyện “Hương và Phai” (Nguyễn Minh Châu), vào ngày cưới của chị Phấn, Phai đã mua một bát riêu cua mang về cho chị.", a: true, x: "Chị Phấn bận rộn từ sáng sớm, đến giờ đón dâu vẫn chưa ăn uống gì. Phai chạy ra phố mua bát riêu cua, món chị thích, rồi cùng Hương bưng về mời chị ăn. Chi tiết cho thấy tình thương của em dành cho chị.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Đọc đoạn thơ: «Con yêu cánh đồng xanh / Con yêu dòng sông nhỏ / Con yêu tiếng chim ca / Con yêu mẹ nhất nhà.» Cụm từ “Con yêu” được lặp lại ở đầu mỗi dòng là biện pháp tu từ nào?", o: ["Điệp ngữ", "Ẩn dụ", "Hoán dụ", "So sánh"], x: "Lặp lại một từ ngữ để nhấn mạnh ý, tạo nhịp cho câu thơ là điệp ngữ. Ở đây “Con yêu” nhấn mạnh tình yêu của con.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "fill", q: "Ẩn dụ là gọi tên sự vật, hiện tượng này bằng tên sự vật, hiện tượng khác có nét ___ với nó.", ans: ["tương đồng", "giống nhau", "tương tự", "giống", "tương tự nhau"], x: "Ẩn dụ dựa trên nét tương đồng (giống nhau). Còn hoán dụ dựa trên quan hệ gần gũi giữa hai sự vật.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Tục ngữ: «Ăn quả nhớ kẻ trồng cây.» Hình ảnh “kẻ trồng cây” chỉ những người đã làm ra thành quả cho mình hưởng. Câu tục ngữ dùng biện pháp tu từ nào?", o: ["Ẩn dụ", "Hoán dụ", "Điệp ngữ", "Nhân hoá"], x: "Người làm ra thành quả giống người trồng cây cho ta có quả ăn. Gọi tên dựa trên nét tương đồng là ẩn dụ.", lv: 1 },
      { topic: "Yêu thương và chia sẻ", type: "mc", q: "Bài thơ “Con chào mào” là của nhà thơ nào?", o: ["Mai Văn Phấn", "Thạch Lam", "Nguyễn Minh Châu", "Tô Hoài"], x: "“Con chào mào” là bài thơ của Mai Văn Phấn, học ở Bài 3 Yêu thương và chia sẻ.", lv: 1 },
      { topic: "Yêu thương và chia sẻ", type: "mc", q: "Lời nhân vật trong truyện là:", o: ["Lời nói trực tiếp của nhân vật (đối thoại, độc thoại)", "Lời người kể chuyện dùng để kể, tả về nhân vật", "Lời người kể chuyện giới thiệu nơi, lúc xảy ra câu chuyện", "Lời nhận xét của người đọc sau khi đọc truyện"], x: "Lời nhân vật là lời nói trực tiếp của nhân vật (đối thoại, độc thoại), thường được đánh dấu bằng dấu gạch ngang đầu dòng hoặc dấu ngoặc kép. Lời người kể chuyện là phần kể, tả còn lại.", lv: 1 },
      { topic: "Yêu thương và chia sẻ", type: "tf", q: "Trong truyện “Cô bé bán diêm”, mỗi lần quẹt que diêm, em bé lại thấy một mộng tưởng như lò sưởi, bàn ăn có ngỗng quay, cây thông Nô-en và người bà.", a: true, x: "Mỗi que diêm sáng lên, em bé thấy một điều mình mong ước: được sưởi ấm, được ăn no, được vui đón Nô-en và được ở bên bà.", lv: 1 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "mc", q: "Trong câu “Gió đang thổi rất mạnh.”, cụm từ “đang thổi rất mạnh” là:", o: ["Cụm động từ", "Cụm danh từ", "Cụm tính từ", "Một từ ghép"], x: "Trung tâm là động từ “thổi”; “đang” và “rất mạnh” bổ sung ý cho “thổi”. Đó là cụm động từ.", lv: 1 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "tf", q: "“Những ngôi nhà mới” là cụm động từ.", a: false, x: "Trung tâm của cụm là danh từ “nhà” (“những”, “ngôi”, “mới” đi kèm), nên đây là cụm danh từ.", lv: 1 },
      { topic: "Quê hương yêu dấu", type: "mc", q: "Văn bản “Cây tre Việt Nam” là của tác giả nào?", o: ["Thép Mới", "Nguyễn Tuân", "Xuân Quỳnh", "Tô Hoài"], x: "“Cây tre Việt Nam” là văn bản của Thép Mới, học ở Bài 4 Quê hương yêu dấu.", lv: 1 },
      { topic: "Quê hương yêu dấu", type: "mc", q: "Đọc hai dòng thơ: «Quê em có dải sông xanh / Có hàng cau thẳng, có cành mai tươi.» Tiếng “xanh” ở dòng sáu vần với tiếng nào ở dòng tám?", o: ["cành", "cau", "tươi", "hàng"], x: "Trong lục bát, tiếng thứ sáu dòng sáu vần với tiếng thứ sáu dòng tám. Dòng tám: Có (1) hàng (2) cau (3) thẳng (4), có (5) cành (6)… “Xanh” vần với “cành” (vần “anh”).", lv: 3 },
      { topic: "Quê hương yêu dấu", type: "fill", q: "Trong thơ lục bát, tiếng thứ tám của dòng tám vần với tiếng thứ ___ của dòng sáu tiếp theo.", ans: ["6", "sáu", "thứ sáu", "thứ 6"], x: "Tiếng cuối dòng tám (tiếng thứ tám) vần với tiếng cuối dòng sáu tiếp theo (tiếng thứ sáu). Nhờ vậy các cặp lục bát nối với nhau thành bài.", lv: 1 },
      { topic: "Từ đồng âm và từ đa nghĩa", type: "mc", q: "Trong câu nào dưới đây, từ “ăn” được dùng với nghĩa gốc?", o: ["Em ăn cơm cùng gia đình.", "Tàu vào cảng ăn hàng.", "Da bạn ấy dễ ăn nắng.", "Hai màu áo này rất ăn với nhau."], x: "Nghĩa gốc của “ăn” là đưa thức ăn vào miệng để nuôi cơ thể. Các câu còn lại dùng nghĩa chuyển: nhận hàng, bị nắng làm đen da, hợp với nhau.", lv: 2 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Câu “Nhà có năm miệng ăn.” dùng “miệng ăn” để chỉ người trong nhà. Đây là biện pháp tu từ nào?", o: ["Hoán dụ", "Ẩn dụ", "So sánh", "Điệp ngữ"], x: "Lấy một bộ phận (cái miệng) để chỉ cả con người: đó là hoán dụ.", lv: 1 },
      { topic: "Những nẻo đường xứ sở", type: "mc", q: "Văn bản “Hang Én” (Hà My) thuộc thể loại nào?", o: ["Du kí", "Truyện đồng thoại", "Thơ lục bát", "Truyện cổ tích"], x: "“Hang Én” ghi lại chuyến đi khám phá hang động của người viết, thuộc thể loại du kí, học ở Bài 5 Những nẻo đường xứ sở.", lv: 1 },
      { topic: "Những nẻo đường xứ sở", type: "mc", q: "Đọc đoạn văn: «Sáng sớm, chúng tôi lên thuyền ra đảo. Mặt biển phẳng lặng như một tấm gương lớn. Tôi đứng ở mũi thuyền, nhìn đàn hải âu chao lượn mà lòng háo hức lạ thường.» Dấu hiệu nào cho thấy đây là một đoạn du kí?", o: ["Người viết kể lại chuyến đi do chính mình trải qua", "Nhân vật là loài vật biết nói", "Đoạn văn có vần như thơ lục bát", "Đoạn văn kể chuyện xảy ra từ thời xa xưa"], x: "Người viết xưng “tôi”, “chúng tôi”, kể và tả những điều tận mắt thấy trong chuyến ra đảo: đó là đặc điểm của du kí.", lv: 2 },
      { topic: "Dấu câu", type: "mc", q: "Dấu ngoặc kép trong câu sau dùng để làm gì? Các bạn gọi ngôi trường là “ngôi nhà thứ hai”.", o: ["Đánh dấu từ ngữ được dùng với ý nghĩa đặc biệt", "Đánh dấu lời đối thoại của nhân vật", "Ngăn cách các bộ phận trong câu", "Kết thúc một câu hỏi"], x: "Ngôi trường không phải ngôi nhà thật. Cụm “ngôi nhà thứ hai” được dùng với ý nghĩa đặc biệt (nơi thân thuộc như nhà), nên đặt trong dấu ngoặc kép.", lv: 2 }
    ]
  },

  /* ---------- Ngữ văn 6 · Đề ngẫu nhiên cuối học kì I: câu riêng của ngân hàng (Phiên N4b) ----------
     Kho câu của đề ngẫu nhiên = 33 câu dưới đây + 50 câu của hai đề cố định ở trên (mọi câu có lv). Ma trận trong
     data/banks/index.js: mỗi lần rút 25 câu, 10 Biết, 8 Hiểu, 7 Vận dụng: mỗi bài (Bài 1–5) một câu mỗi mức, 9 câu Tiếng Việt,
     1 câu Viết (đoạn văn tự chấm).
     Đọc hiểu viết một lần ở passages: 5 văn bản tự viết, mỗi văn bản cùng thể loại với văn bản của một bài (truyện đồng thoại
     kể theo ngôi thứ nhất; thơ năm chữ có yếu tố tự sự, miêu tả; truyện kể theo ngôi thứ ba; thơ lục bát; du kí), 4 câu đủ ba
     mức, chủ đề là tên bài; câu nào cũng làm được khi chỉ rút riêng câu đó cùng đoạn. Câu đọc hiểu không hỏi lại điều các câu
     của hai đề cố định đã hỏi (tác giả, thể loại, ngôi kể, luật lục bát), vì các câu đó có thể được rút cùng một đề.
     Tiếng Việt: mỗi ô Tiếng Việt có thêm câu mới (các ô này trước chỉ có câu của hai đề cố định).
     Viết: 5 câu đoạn văn khoảng 150–200 chữ theo các kiểu bài học kì I (kể lại một trải nghiệm, hai câu; cảm xúc về một bài
     thơ có yếu tố tự sự và miêu tả; cảm xúc về một bài thơ lục bát; tả cảnh sinh hoạt), thang tự chấm 4 điểm, đoạn văn tham
     khảo; hai câu viết về bài thơ ở phần đọc hiểu (p) nên tự đủ, không cần nhớ bài trong sách. Câu tự soạn. */
  "van6-ck1-ngau-nhien": {
    note: "Học kì I (Bài 1–5), sách Kết nối tri thức. Mỗi đề có 10 câu mức Biết, 8 câu mức Hiểu, 7 câu mức Vận dụng, trong đó có một câu Viết đoạn văn tự chấm theo gợi ý. Đoạn văn, bài thơ tự soạn. Có lời giải từng câu.",
    passages: {
      "soc-do": {
        title: "Sóc Đỏ và Nhím Con",
        text: "Tôi là Sóc Đỏ, nhà ở trên cây dẻ cao nhất khu rừng. Cả rừng chẳng ai leo trèo nhanh bằng tôi, nên tôi hay vênh mặt lên với mọi người. Một hôm, thấy Nhím Con lạch bạch đi nhặt quả rụng, tôi buông lời chế giễu:\n– Đi chậm như rùa, người lại toàn gai, ai mà thèm chơi với cậu!\nNhím Con không nói gì, lặng lẽ đi tiếp.\nChiều ấy, trời đổ mưa to. Mải nhảy chuyền trên những cành cây trơn ướt, tôi trượt chân, rơi xuống một cái hố sâu. Tôi kêu cứu mãi mà chẳng ai nghe thấy. Bỗng Nhím Con xuất hiện trên miệng hố. Cậu thả xuống một sợi dây leo rồi gồng mình kéo tôi lên.\nNhìn bộ lông gai ướt sũng của bạn, tôi xấu hổ quá, lí nhí:\n– Tớ xin lỗi cậu…\nNhím Con cười hiền:\n– Bạn bè thì phải giúp nhau chứ!\nTừ hôm ấy, chiều nào tôi cũng sang rủ Nhím Con đi nhặt quả dẻ."
      },
      "tha-dieu": {
        title: "Thả diều cùng bố",
        text: "Chiều nay bố về sớm,\nChẻ tre vót nan diều.\nCon ngồi bên ngắm mãi,\nTay bố khéo bao nhiêu!\n\nBố dán giấy làm cánh,\nCon buộc chỉ làm dây.\nHai bố con ra đồng,\nGió chiều thổi hây hây.\n\nBố tung diều lên cao,\nCon chạy theo hụt hơi.\nDiều chao nghiêng rồi lượn\nNhư cánh chim giữa trời.\n\nSáo diều vi vu hát,\nRu cánh đồng lúa xanh.\nCon ngước nhìn bố cười,\nMắt bố sáng long lanh.\n\nMai con lớn, đi xa\nNhư cánh diều lộng gió,\nVẫn nhớ đồng quê nhỏ,\nNhớ bố ngày thả diều."
      },
      "nam-xoi": {
        title: "Hai nắm xôi",
        text: "Sáng nào mẹ cũng gói cho Tùng một nắm xôi lạc thơm phức mang đến lớp. Mấy hôm nay, Tùng để ý thấy giờ ra chơi, Quân thường ngồi lặng lẽ một mình ở góc lớp. Có lần, Tùng nghe bụng bạn sôi lên ùng ục. Tùng biết bố Quân ốm đã lâu, mẹ Quân phải đi chợ bán rau từ lúc trời còn tối.\nTối ấy, Tùng thủ thỉ với mẹ:\n– Mẹ ơi, từ mai mẹ gói cho con hai nắm xôi được không ạ?\nNghe con kể chuyện, mẹ xoa đầu Tùng, gật đầu.\nSáng hôm sau, Tùng đặt một nắm xôi còn ấm lên bàn Quân:\n– Mẹ tớ gói nhiều quá, tớ ăn không hết. Cậu ăn giúp tớ nhé!\nQuân ngập ngừng một lúc rồi đỡ lấy nắm xôi. Hai bạn ngồi ăn bên nhau, nói cười rôm rả. Ngoài cửa sổ, nắng sớm rải vàng khắp sân trường."
      },
      "lang-em": {
        title: "Làng em",
        text: "Làng em bên một dòng sông,\nNước xanh uốn khúc giữa đồng lúa thơm.\nChiều chiều khói bếp mùi rơm,\nMẹ ngồi nhóm lửa thổi cơm đợi chờ.\nLũy tre xanh mát đôi bờ,\nĐàn cò trắng lượn lơ thơ giữa trời.\nDù cho đi khắp mọi nơi,\nVẫn nghe tiếng mẹ à ơi thuở nào."
      },
      "cho-noi": {
        title: "Chợ nổi Cái Răng",
        text: "Năm giờ sáng, chúng tôi đã ngồi trên chiếc xuồng máy nhỏ, xuôi dòng sông tới chợ nổi Cái Răng. Trời còn mờ sương. Mặt sông loang loáng ánh đèn của những chiếc ghe đang nối nhau về chợ.\nCàng đi, ghe xuồng càng đông. Ghe nào cũng dựng một cây sào cao, trên đầu sào treo lủng lẳng mấy quả bí, chùm chôm chôm hay mấy củ khoai lang. Chú lái xuồng bảo đó là “cây bẹo”: ghe bán thứ gì thì treo thứ ấy lên để khách nhìn từ xa đã biết. Tiếng rao hàng, tiếng cười nói, tiếng máy nổ hoà vào nhau rộn rã cả khúc sông.\nTôi gọi một bát hủ tiếu từ chiếc xuồng nhỏ của một cô bán hàng. Cô vừa giữ cho xuồng khỏi chòng chành, vừa chuyền bát hủ tiếu nóng hổi sang cho tôi mà không sánh ra ngoài một giọt. Lúc mặt trời nhô lên, cả dòng sông sáng rực như dát vàng.\nRời chợ nổi, tôi cứ ngoái lại nhìn mãi và thầm hứa sẽ có ngày trở lại miền Tây sông nước hiền hoà này."
      }
    },
    questions: [
      { topic: "Tôi và các bạn", type: "mc", q: "Vì sao Sóc Đỏ bị rơi xuống hố sâu?", o: ["Vì mải nhảy chuyền cành nên trượt chân", "Vì bị Nhím Con đẩy từ trên cây xuống", "Vì đi tìm quả dẻ lúc trời tối mịt", "Vì gió to thổi bay khỏi chiếc tổ"], x: "Văn bản viết: “Mải nhảy chuyền trên những cành cây trơn ướt, tôi trượt chân, rơi xuống một cái hố sâu.”", lv: 1, p: "soc-do" },
      { topic: "Tôi và các bạn", type: "mc", q: "Vì sao Sóc Đỏ thấy xấu hổ khi nhìn bộ lông gai ướt sũng của Nhím Con?", o: ["Vì từng chê bai Nhím Con mà bạn vẫn đội mưa đến cứu mình", "Vì bộ lông của Nhím Con đẹp hơn bộ lông của mình", "Vì Sóc Đỏ đã làm ướt bộ lông gai của Nhím Con", "Vì Nhím Con mắng Sóc Đỏ trước mặt cả khu rừng"], x: "Sóc Đỏ từng chế giễu Nhím Con “đi chậm như rùa, người lại toàn gai”. Vậy mà khi Sóc Đỏ gặp nạn, chính Nhím Con đội mưa đến kéo Sóc Đỏ lên. Sóc Đỏ hiểu mình đã cư xử sai với bạn nên thấy xấu hổ.", lv: 2, p: "soc-do" },
      { topic: "Tôi và các bạn", type: "mc", q: "Nếu được nói một câu với Sóc Đỏ lúc Sóc Đỏ đang chế giễu Nhím Con, câu nào phù hợp nhất?", o: ["Mỗi bạn có điểm mạnh riêng, đừng chê bạn chỉ vì bạn khác mình.", "Cậu nói đúng đấy, nhưng đừng nói to kẻo Nhím Con buồn.", "Kệ Nhím Con, bạn ấy có nói lại gì đâu mà lo.", "Cậu leo cây giỏi nhất rừng nên chê ai cũng được."], x: "Sóc Đỏ chê Nhím Con chỉ vì bạn đi chậm, người nhiều gai, trong khi Nhím Con là người tốt bụng. Lời nói phù hợp là nhắc Sóc Đỏ tôn trọng nét riêng của bạn. Câu “Cậu nói đúng đấy…” nghe nhẹ nhàng nhưng vẫn đồng tình với lời chê bai; hai câu còn lại để mặc hoặc khuyến khích Sóc Đỏ coi thường bạn.", lv: 3, p: "soc-do" },
      { topic: "Tôi và các bạn", type: "tf4", q: "Từ câu chuyện của Sóc Đỏ, một bạn rút ra bốn điều dưới đây. Mỗi điều đúng hay sai?", o: ["Không nên chế giễu bạn chỉ vì vẻ bề ngoài hay vì bạn làm chậm.", "Ai giỏi hơn thì được quyền coi thường người khác.", "Khi làm sai, cần biết nhận lỗi và sửa lỗi bằng việc làm.", "Chỉ nên giúp những bạn đã từng tốt với mình."], a: [true, false, true, false], x: "a) Đúng: Sóc Đỏ chê Nhím Con đi chậm, nhiều gai, rồi lại được chính Nhím Con cứu. b) Sai: tài leo trèo không cho Sóc Đỏ quyền vênh mặt với ai; cuối cùng Sóc Đỏ thấy xấu hổ vì đã coi thường bạn. c) Đúng: Sóc Đỏ xin lỗi, rồi chiều nào cũng sang rủ Nhím Con đi nhặt quả. d) Sai: Nhím Con từng bị chê mà vẫn đến cứu Sóc Đỏ, vì “bạn bè thì phải giúp nhau”.", lv: 3, p: "soc-do" },
      { topic: "Gõ cửa trái tim", type: "tf", q: "Chiếc diều trong bài thơ «Thả diều cùng bố» được bố mua sẵn ở chợ.", a: false, x: "Sai. Bài thơ viết: “Chiều nay bố về sớm, / Chẻ tre vót nan diều.” Bố tự tay chẻ tre, vót nan, dán giấy làm cánh diều.", lv: 1, p: "tha-dieu" },
      { topic: "Gõ cửa trái tim", type: "tf4", q: "Đọc lại bài thơ «Thả diều cùng bố». Mỗi ý sau đúng hay sai?", o: ["Bài thơ kể lại việc hai bố con làm diều rồi cùng nhau thả diều.", "Bài thơ có những câu tả cánh diều và cảnh cánh đồng.", "Người kể trong bài thơ là người bố.", "Bố mải làm việc nên con phải thả diều một mình."], a: [true, true, false, false], x: "a) Đúng: bố chẻ tre, vót nan, dán giấy; con buộc chỉ làm dây; hai bố con ra đồng, bố tung diều, con chạy theo. Đó là yếu tố tự sự (kể việc). b) Đúng: diều “chao nghiêng rồi lượn”, sáo diều “vi vu”, “cánh đồng lúa xanh”. Đó là yếu tố miêu tả. c) Sai: người kể xưng “con” và gọi “bố”, nên người kể là người con. d) Sai: bố tung diều lên cao, con chạy theo; hai bố con cùng thả diều.", lv: 2, p: "tha-dieu" },
      { topic: "Gõ cửa trái tim", type: "mc", q: "Bài thơ «Thả diều cùng bố» gợi cho bạn suy nghĩ gì về những giờ phút bên bố mẹ?", o: ["Việc nhỏ làm cùng bố mẹ cũng có thể thành kỉ niệm theo ta suốt đời", "Chỉ những chuyến đi xa, tốn kém mới để lại kỉ niệm đáng nhớ", "Lớn lên rồi thì không cần nhớ về những ngày thơ bé nữa", "Thả diều là trò chơi chỉ dành cho người lớn, không cho trẻ em"], x: "Bài thơ kể một buổi chiều bình dị: bố làm diều, hai bố con ra đồng thả diều. Vậy mà người con nhớ mãi, kể cả khi lớn lên, đi xa (“Vẫn nhớ đồng quê nhỏ, / Nhớ bố ngày thả diều.”). Những việc nhỏ làm cùng bố mẹ có thể trở thành kỉ niệm đẹp theo ta suốt đời.", lv: 3, p: "tha-dieu" },
      { topic: "Gõ cửa trái tim", type: "mc", q: "Bạn muốn viết thêm vào bài thơ «Thả diều cùng bố» một khổ kể về một việc khác bạn từng làm cùng bố hoặc mẹ. Để khổ thơ mới hợp với cả bài, bạn nên viết thế nào?", o: ["Mỗi dòng có số tiếng bằng các dòng trong bài, vừa kể việc vừa tả cảnh", "Viết thành một đoạn văn dài, không chia dòng, không chia khổ", "Mỗi dòng dài ngắn tuỳ ý, chỉ cần dùng thật nhiều từ ngữ đẹp", "Chỉ kể tên các đồ vật trong nhà, không kể việc, không tả cảnh"], x: "Các dòng trong bài dài bằng nhau (cùng số tiếng), bài chia thành các khổ bốn dòng; mỗi khổ vừa kể việc (làm diều, thả diều) vừa tả cảnh (cánh diều, cánh đồng). Khổ thơ viết thêm cần giữ những đặc điểm ấy thì mới hợp với cả bài.", lv: 3, p: "tha-dieu" },
      { topic: "Yêu thương và chia sẻ", type: "mc", q: "Giờ ra chơi, Tùng để ý thấy Quân thường làm gì?", o: ["Ngồi lặng lẽ một mình ở góc lớp", "Chạy ra sân chơi đá cầu với các bạn", "Ăn sáng cùng các bạn trong lớp", "Lên thư viện đọc truyện một mình"], x: "Văn bản viết: “Mấy hôm nay, Tùng để ý thấy giờ ra chơi, Quân thường ngồi lặng lẽ một mình ở góc lớp.”", lv: 1, p: "nam-xoi" },
      { topic: "Yêu thương và chia sẻ", type: "mc", q: "Vì sao Tùng nói với Quân: «Mẹ tớ gói nhiều quá, tớ ăn không hết.»?", o: ["Để Quân nhận nắm xôi mà không thấy ngại", "Vì Tùng không thích ăn xôi lạc của mẹ", "Vì mẹ bắt Tùng phải mang xôi cho bạn", "Để khoe với Quân rằng mẹ mình nấu ngon"], x: "Chính Tùng đã xin mẹ gói thêm một nắm xôi cho Quân. Tùng nói như vậy để Quân nghĩ mình chỉ “ăn giúp” bạn, không phải nhận quà vì nhà khó khăn, nên Quân bớt ngại. Đó là cách giúp đỡ khéo léo, tế nhị.", lv: 2, p: "nam-xoi" },
      { topic: "Yêu thương và chia sẻ", type: "mc", q: "Ngoài nhan đề «Hai nắm xôi», nhan đề nào dưới đây cũng phù hợp với câu chuyện?", o: ["Nắm xôi sẻ chia", "Phiên chợ lúc trời còn tối", "Giờ ra chơi ở sân trường", "Món xôi lạc của mẹ"], x: "Câu chuyện kể việc Tùng xin mẹ gói thêm xôi để chia cho bạn đang đói. “Nắm xôi sẻ chia” nói được cả sự việc chính và ý nghĩa của câu chuyện. “Món xôi lạc của mẹ” chỉ nói về món ăn; hai nhan đề còn lại nói về những chi tiết phụ.", lv: 3, p: "nam-xoi" },
      { topic: "Yêu thương và chia sẻ", type: "mc", q: "Trong giờ kiểm tra, bạn ngồi cạnh phát hiện mình quên mang bút. Học theo cách của Tùng, bạn sẽ làm gì?", o: ["Lặng lẽ đưa bạn một chiếc bút của mình", "Nói thật to cho cả lớp biết bạn quên bút", "Mặc kệ, vì đó là lỗi của bạn ấy", "Cho bạn mượn bút nhưng bắt bạn trả công"], x: "Tùng giúp Quân một cách lặng lẽ, khéo léo, để bạn không thấy ngại. Học theo Tùng, ta lặng lẽ cho bạn mượn bút, không làm bạn xấu hổ trước lớp và không đòi bạn trả công.", lv: 3, p: "nam-xoi" },
      { topic: "Quê hương yêu dấu", type: "match", q: "Nối mỗi sự vật với hình ảnh tả nó trong bài thơ «Làng em».", l: ["Dòng sông", "Lũy tre", "Đàn cò trắng"], r: ["Uốn khúc giữa đồng lúa thơm", "Xanh mát đôi bờ", "Lượn lơ thơ giữa trời", "Ngồi nhóm lửa thổi cơm"], x: "Bài thơ viết: nước sông xanh “uốn khúc giữa đồng lúa thơm”; “Lũy tre xanh mát đôi bờ”; “Đàn cò trắng lượn lơ thơ giữa trời”. “Ngồi nhóm lửa thổi cơm” là hình ảnh người mẹ.", lv: 1, p: "lang-em" },
      { topic: "Quê hương yêu dấu", type: "mc", q: "Câu thơ «Vẫn nghe tiếng mẹ à ơi thuở nào» thể hiện điều gì?", o: ["Đi đâu, người con vẫn nhớ lời ru của mẹ, nhớ quê", "Người mẹ vẫn đang ngồi hát ru bên cạnh người con", "Người con không còn thích nghe mẹ hát ru nữa", "Người con đã quên hết những gì ở làng quê"], x: "“À ơi” là tiếng ru của mẹ. Hai dòng cuối nói: dù đi khắp mọi nơi, người con vẫn như nghe thấy tiếng ru ngày nào. Câu thơ thể hiện nỗi nhớ mẹ, nhớ quê luôn ở trong lòng người con.", lv: 2, p: "lang-em" },
      { topic: "Quê hương yêu dấu", type: "tf4", q: "Đọc lại bài thơ «Làng em». Mỗi ý sau đúng hay sai?", o: ["Bài thơ nhắc đến những hình ảnh quen thuộc của làng quê: dòng sông, đồng lúa, lũy tre, cánh cò.", "Hình ảnh khói bếp chiều và mẹ thổi cơm “đợi chờ” gợi cảm giác ấm áp, thân thương.", "Bài thơ tả cảnh phố phường đông đúc, nhộn nhịp.", "Hai dòng cuối cho thấy người con sẽ quên làng khi đi xa."], a: [true, true, false, false], x: "a) Đúng: bài thơ có dòng sông, đồng lúa thơm, lũy tre, đàn cò trắng. b) Đúng: khói bếp chiều và mẹ nhóm lửa thổi cơm “đợi chờ” gợi cảnh gia đình ấm cúng, có mẹ chờ con về. c) Sai: bài thơ tả cảnh làng quê yên bình, không có phố phường. d) Sai: “Dù cho đi khắp mọi nơi / Vẫn nghe tiếng mẹ à ơi thuở nào”: người con luôn nhớ làng, nhớ mẹ.", lv: 2, p: "lang-em" },
      { topic: "Quê hương yêu dấu", type: "mc", q: "Bạn viết đoạn văn thể hiện cảm xúc về bài thơ «Làng em». Câu mở đoạn nào phù hợp nhất?", o: ["Đọc bài thơ «Làng em», em thấy thương biết mấy cảnh làng quê bình dị và tình mẹ ấm áp.", "Bài thơ «Làng em» có tám dòng, nói về một dòng sông, một lũy tre và một đàn cò.", "Hôm qua, em được bố đưa về thăm quê nội, ở đó có rất nhiều cây xanh và ao cá.", "Làng quê nào cũng có cánh đồng lúa, có lũy tre xanh và những dòng sông hiền hoà."], x: "Câu mở đoạn của đoạn văn thể hiện cảm xúc về một bài thơ cần giới thiệu bài thơ và nêu cảm xúc chung của người viết. Câu “Đọc bài thơ «Làng em», em thấy thương biết mấy…” làm được cả hai việc. Câu “Bài thơ «Làng em» có tám dòng…” chỉ kể lại nội dung, chưa có cảm xúc; câu kể chuyện về quê nội không nói về bài thơ; câu “Làng quê nào cũng…” chưa nhắc đến bài thơ.", lv: 3, p: "lang-em" },
      { topic: "Những nẻo đường xứ sở", type: "fill", q: "Theo văn bản, cây sào cao dựng trên ghe, treo thứ hàng mà ghe đang bán để khách nhìn từ xa đã biết, được gọi là “cây ___”.", ans: ["bẹo", "cây bẹo"], x: "Văn bản viết: Chú lái xuồng bảo đó là “cây bẹo”: ghe bán thứ gì thì treo thứ ấy lên để khách nhìn từ xa đã biết.", lv: 1, p: "cho-noi" },
      { topic: "Những nẻo đường xứ sở", type: "order", q: "Sắp xếp các sự việc theo đúng trình tự người viết đã trải qua.", o: ["Ngồi xuồng máy xuôi dòng sông khi trời còn mờ sương", "Thấy ghe xuồng mỗi lúc một đông, ghe nào cũng treo hàng trên sào cao", "Ăn bát hủ tiếu nóng hổi mua từ xuồng của một cô bán hàng", "Rời chợ, ngoái lại nhìn và thầm hứa sẽ có ngày trở lại"], x: "Người viết kể theo trình tự thời gian của chuyến đi: năm giờ sáng ngồi xuồng xuôi dòng; càng đi ghe xuồng càng đông; ở chợ, gọi một bát hủ tiếu; cuối cùng rời chợ, hứa sẽ trở lại.", lv: 2, p: "cho-noi" },
      { topic: "Những nẻo đường xứ sở", type: "mc", q: "Chi tiết nào trong văn bản cho thấy rõ nhất nét riêng của chợ nổi, khác với các chợ trên đất liền?", o: ["Chợ họp ngay trên sông, mua bán từ ghe sang ghe", "Chợ rất đông người, tiếng cười nói rộn rã cả khúc sông", "Chợ bán đủ loại rau, củ, quả tươi ngon từ sáng sớm", "Ở chợ có những món ăn sáng nóng hổi, thơm ngon"], x: "Chợ trên đất liền cũng đông vui, cũng bán rau, củ, quả và đồ ăn sáng. Chỉ chợ nổi mới họp ngay trên sông: người bán, người mua đều ở trên ghe xuồng, chuyền hàng từ ghe này sang ghe khác.", lv: 3, p: "cho-noi" },
      { topic: "Những nẻo đường xứ sở", type: "mc", q: "Nếu được đi tham quan chợ nổi như người viết, việc làm nào cho thấy bạn là một du khách có ý thức?", o: ["Bỏ rác vào túi mang theo, không xả xuống sông", "Ném vỏ trái cây xuống sông cho nhanh, gọn", "Đứng lên nhảy nhót trên xuồng để chụp ảnh đẹp", "Tự ý cầm hàng trên ghe của người khác để xem"], x: "Dòng sông là nơi người dân sinh sống, buôn bán. Giữ sông sạch, không xả rác là cách ứng xử văn minh khi tham quan. Nhảy nhót trên xuồng rất nguy hiểm; tự ý cầm hàng của người khác là thiếu lịch sự.", lv: 3, p: "cho-noi" },
      { topic: "Dấu câu", type: "mc", q: "Dấu ngoặc kép trong câu sau dùng để làm gì? Bà dặn em: “Đi học về nhớ ghé qua nhà bà nhé!”", o: ["Đánh dấu lời dẫn trực tiếp", "Đánh dấu tên một tác phẩm", "Đánh dấu từ ngữ được dùng với ý nghĩa đặc biệt", "Đánh dấu phần giải thích, chú thích"], x: "Phần trong ngoặc kép là nguyên văn lời bà nói, đứng sau dấu hai chấm. Dấu ngoặc kép ở đây đánh dấu lời dẫn trực tiếp.", lv: 2 },
      { topic: "Từ đơn và từ phức", type: "match", q: "Nối mỗi từ với loại từ phù hợp.", l: ["mưa", "mưa phùn", "lất phất"], r: ["Từ đơn", "Từ ghép", "Từ láy"], x: "“Mưa” chỉ có một tiếng: từ đơn. “Mưa phùn” gồm hai tiếng đều có nghĩa, ghép lại để chỉ một loại mưa: từ ghép. “Lất phất” gồm hai tiếng cùng vần “ât”: từ láy.", lv: 1 },
      { topic: "Từ đơn và từ phức", type: "mc", q: "Chọn từ láy thích hợp nhất để điền vào chỗ trống: «Gió thổi nhè nhẹ, mặt hồ … gợn sóng.»", o: ["lăn tăn", "khúc khích", "lách cách", "chót vót"], x: "“Lăn tăn” tả những gợn sóng nhỏ, đều, nối tiếp nhau trên mặt nước, hợp với câu văn. “Khúc khích” tả tiếng cười, “lách cách” tả tiếng đồ vật va vào nhau, “chót vót” tả độ cao.", lv: 3 },
      { topic: "Nghĩa của từ", type: "match", q: "Nối mỗi từ với nghĩa của nó.", l: ["kiên trì", "khiêm tốn", "chân thành"], r: ["Bền bỉ, không nản lòng trước khó khăn", "Không tự đề cao mình, biết nhún nhường", "Thật lòng, không giả dối", "Nhanh nhẹn, hoạt bát"], x: "Kiên trì: bền bỉ làm đến cùng, không nản. Khiêm tốn: không khoe khoang, không cho mình hơn người. Chân thành: thật lòng, không giả dối. “Nhanh nhẹn, hoạt bát” không phải nghĩa của từ nào trong ba từ trên.", lv: 2 },
      { topic: "Từ đồng âm và từ đa nghĩa", type: "tf4", q: "Mỗi nhận xét sau về nghĩa của từ đúng hay sai?", o: ["Từ “mắt” trong “mắt na” được dùng với nghĩa chuyển.", "Từ “bò” trong “con bò” và trong “em bé đang tập bò” là hai từ đồng âm.", "Từ “cổ” trong “cổ áo” và trong “cổ tay” là hai từ đồng âm.", "Từ “lá” trong “lá cây” được dùng với nghĩa gốc."], a: [true, true, false, true], x: "a) Đúng: “mắt” vốn chỉ bộ phận để nhìn của người, con vật; “mắt na” là những ô nhỏ trên vỏ quả na, là nghĩa chuyển. b) Đúng: “bò” chỉ con vật và “bò” chỉ hoạt động trườn bằng tay, chân đọc lên trùng nhau nhưng nghĩa không liên quan gì đến nhau, nên là hai từ đồng âm. c) Sai: “cổ áo”, “cổ tay” đều là nghĩa chuyển của “cổ” (bộ phận nối đầu với thân), nên đây là một từ nhiều nghĩa (từ đa nghĩa). d) Đúng: “lá cây” là nghĩa gốc; “lá thư”, “lá cờ” là nghĩa chuyển.", lv: 2 },
      { topic: "Biện pháp tu từ", type: "tf4", q: "Mỗi nhận xét sau về biện pháp tu từ trong câu đúng hay sai?", o: ["«Mặt hồ phẳng lặng như một tấm gương.» dùng biện pháp so sánh.", "«Hàng phi lao đứng nghiêm chào đón khách đến thăm đảo.» dùng biện pháp nhân hoá.", "«Bầu trời hôm nay trong xanh, không một gợn mây.» dùng biện pháp so sánh.", "«Những giọt mưa rơi lộp độp trên mái tôn.» dùng biện pháp nhân hoá."], a: [true, true, false, false], x: "a) Đúng: mặt hồ được đối chiếu với tấm gương, có từ so sánh “như”. b) Đúng: hàng phi lao được tả bằng hoạt động của người (đứng nghiêm, chào đón khách). c) Sai: câu chỉ tả bầu trời, không đối chiếu với sự vật nào khác. d) Sai: “lộp độp” chỉ tả tiếng mưa rơi; giọt mưa không được gán hoạt động hay tính nết của người.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Trong câu «Mùa xuân, trên cây gạo đầu làng bừng lên muôn ngàn ngọn lửa hồng.», “ngọn lửa hồng” là để chỉ những bông hoa gạo đỏ rực. Câu văn dùng biện pháp tu từ nào?", o: ["Ẩn dụ", "So sánh", "Nhân hoá", "Điệp ngữ"], x: "Câu văn không gọi tên hoa gạo mà gọi những bông hoa ấy là “ngọn lửa hồng”, vì hoa gạo đỏ rực như lửa: đó là ẩn dụ. Câu không có từ so sánh (như, là…), không tả cây gạo bằng hoạt động của người và không lặp lại từ ngữ nào.", lv: 1 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "match", q: "Nối mỗi cụm từ với loại cụm từ phù hợp.", l: ["mấy chú chim sẻ nhỏ", "đang hót líu lo", "rất trong trẻo"], r: ["Cụm danh từ", "Cụm động từ", "Cụm tính từ"], x: "“Mấy chú chim sẻ nhỏ” có danh từ “chim sẻ” làm trung tâm: cụm danh từ. “Đang hót líu lo” có động từ “hót” làm trung tâm: cụm động từ. “Rất trong trẻo” có tính từ “trong trẻo” làm trung tâm: cụm tính từ.", lv: 1 },
      { topic: "Viết", type: "essay", q: "Viết đoạn văn (khoảng 150–200 chữ) kể lại một trải nghiệm đáng nhớ của bạn với một người bạn (ví dụ: một lần được bạn giúp đỡ, một lần hai bạn giận nhau rồi làm lành).", rubric: [{ c: "Câu mở đoạn giới thiệu được trải nghiệm: chuyện gì, với bạn nào, xảy ra khi nào", p: 0.5 }, { c: "Kể các sự việc chính theo trình tự hợp lí, có chi tiết cụ thể (lời nói, việc làm của hai bạn)", p: 1.5 }, { c: "Người kể xưng “tôi” hoặc “em”, kể chuyện của chính mình; nêu được cảm xúc của bạn trong trải nghiệm", p: 1 }, { c: "Câu kết nêu điều bạn rút ra hoặc ý nghĩa của trải nghiệm", p: 0.5 }, { c: "Đúng hình thức đoạn văn (khoảng 150–200 chữ); dùng từ đúng, viết đúng chính tả", p: 0.5 }], x: "Đoạn văn cần: câu mở đoạn giới thiệu trải nghiệm; các câu tiếp theo kể lần lượt các sự việc, có lời nói, việc làm cụ thể; câu kết nêu cảm xúc và điều rút ra.\nĐoạn văn tham khảo:\nEm không bao giờ quên lần cùng Hoa làm lành sau một lần giận nhau hồi đầu năm học. Hôm ấy, Hoa lỡ tay làm đổ lọ mực lên cuốn vở em vừa trình bày cẩn thận. Em tức quá, gắt lên với Hoa rồi suốt buổi không thèm nói chuyện. Về nhà, nhìn trang vở lem nhem, em vẫn còn giận. Sáng hôm sau, vừa vào lớp, em đã thấy trên bàn mình một cuốn vở mới, kèm mảnh giấy nhỏ: “Tớ xin lỗi. Tớ chép lại bài giúp cậu rồi.” Từng dòng chữ của Hoa nắn nót, cẩn thận. Em quay sang, thấy Hoa đang nhìn mình, mắt rưng rưng. Em chợt thấy mình thật nóng nảy. Em nắm tay bạn: “Tớ cũng xin lỗi vì hôm qua đã gắt với cậu.” Hai đứa nhìn nhau rồi cùng bật cười. Từ đó, chúng em càng thân nhau hơn. Trải nghiệm ấy giúp em hiểu rằng bạn bè cần biết bao dung và biết nói lời xin lỗi đúng lúc.", lv: 3 },
      { topic: "Viết", type: "essay", q: "Viết đoạn văn (khoảng 150–200 chữ) kể lại lần đầu tiên bạn tự làm một việc (ví dụ: lần đầu tự nấu cơm, lần đầu tự đạp xe đến trường, lần đầu một mình đi mua đồ giúp mẹ).", rubric: [{ c: "Câu mở đoạn giới thiệu được việc bạn lần đầu tự làm, diễn ra khi nào", p: 0.5 }, { c: "Kể diễn biến theo trình tự: chuẩn bị, lúc lúng túng hay khó khăn, cách bạn vượt qua, kết quả", p: 1.5 }, { c: "Người kể xưng “tôi” hoặc “em”, kể chuyện của chính mình; nêu được cảm xúc của bạn trước, trong và sau khi làm", p: 1 }, { c: "Câu kết nêu điều bạn học được từ trải nghiệm", p: 0.5 }, { c: "Đúng hình thức đoạn văn (khoảng 150–200 chữ); dùng từ đúng, viết đúng chính tả", p: 0.5 }], x: "Đoạn văn cần: câu mở đoạn giới thiệu việc lần đầu tự làm; các câu tiếp theo kể lần lượt từ lúc chuẩn bị đến khi xong việc, có lúc lúng túng và cách xử lí; câu kết nêu cảm xúc, điều học được.\nĐoạn văn tham khảo:\nMùa hè năm ngoái, em lần đầu tự tay nấu một nồi cơm cho cả nhà. Hôm ấy, bố mẹ đi làm về muộn, em muốn nấu cơm để bố mẹ đỡ vất vả. Em đong ba cốc gạo, vo hai lần cho đến khi nước trong. Đến lúc đổ nước, em lúng túng không biết bao nhiêu là vừa. Em nhớ lời bà dặn: nước ngập gạo khoảng một đốt ngón tay. Em làm đúng như thế rồi cắm điện nồi cơm. Ngồi chờ mà lòng em cứ thấp thỏm, chốc chốc lại chạy vào xem. Khi nồi cơm chuyển sang chế độ ủ, em mở nắp: hơi nóng bốc lên thơm phức, hạt cơm trắng, dẻo. Tối ấy, bố vừa ăn vừa khen: “Con nấu cơm ngon quá!” Mẹ thì xoa đầu em, mỉm cười. Em vui lắm, thấy mình như vừa lớn thêm một chút. Từ lần ấy, em hiểu rằng tự làm việc nhà không chỉ giúp đỡ bố mẹ mà còn giúp mình tự tin hơn.", lv: 3 },
      { topic: "Viết", type: "essay", q: "Viết đoạn văn (khoảng 150–200 chữ) ghi lại cảm xúc của bạn về bài thơ «Thả diều cùng bố».", rubric: [{ c: "Câu mở đoạn nêu được tên bài thơ và cảm xúc chung của bạn", p: 0.5 }, { c: "Nêu cảm xúc về câu chuyện trong bài thơ (hai bố con làm diều, thả diều) và tình cảm của hai bố con", p: 1 }, { c: "Nêu cảm xúc về ít nhất hai hình ảnh, từ ngữ hoặc biện pháp tu từ hay trong bài, có dẫn câu thơ", p: 1.5 }, { c: "Câu kết khẳng định lại cảm xúc hoặc nêu điều bài thơ gợi cho bạn", p: 0.5 }, { c: "Đúng hình thức đoạn văn (khoảng 150–200 chữ); dùng từ đúng, viết đúng chính tả", p: 0.5 }], x: "Đoạn văn cần: câu mở đoạn giới thiệu bài thơ và cảm xúc chung; các câu tiếp theo nêu cảm xúc về câu chuyện, về những hình ảnh, câu thơ hay (dẫn câu thơ); câu kết khẳng định lại cảm xúc.\nĐoạn văn tham khảo:\nĐọc bài thơ «Thả diều cùng bố», em thấy lòng mình ấm áp như vừa được cùng bố ra đồng thả diều. Bài thơ kể một buổi chiều giản dị: bố về sớm, chẻ tre, vót nan, dán giấy làm diều cho con. Em thích hình ảnh người con ngồi bên “ngắm mãi” đôi tay khéo léo của bố. Khi diều lên cao, hai câu thơ “Diều chao nghiêng rồi lượn / Như cánh chim giữa trời” giúp em như thấy cánh diều đang chao lượn giữa bầu trời lộng gió. Tiếng sáo diều “vi vu hát” ru cánh đồng lúa xanh khiến cảnh vật thật yên bình. Em còn thấy được niềm vui của bố qua đôi mắt “sáng long lanh” khi nhìn con cười. Em xúc động nhất ở khổ thơ cuối: con lớn lên sẽ đi xa như cánh diều, nhưng vẫn nhớ đồng quê, nhớ bố. Bài thơ làm em thêm yêu bố và muốn được ở bên bố nhiều hơn.", lv: 3, p: "tha-dieu" },
      { topic: "Viết", type: "essay", q: "Viết đoạn văn (khoảng 150–200 chữ) thể hiện cảm xúc của bạn về bài thơ lục bát «Làng em».", rubric: [{ c: "Câu mở đoạn giới thiệu bài thơ và nêu cảm xúc chung của bạn", p: 0.5 }, { c: "Nêu cảm xúc về bức tranh làng quê trong bài thơ (dòng sông, đồng lúa, khói bếp, lũy tre, cánh cò…), có dẫn câu thơ", p: 1 }, { c: "Nêu cảm xúc về hình ảnh người mẹ và nỗi nhớ quê của người con ở hai dòng cuối", p: 1 }, { c: "Nhận xét được cái hay của thể thơ lục bát (nhịp nhàng, êm như lời ru) hoặc của một từ ngữ, hình ảnh trong bài", p: 0.5 }, { c: "Câu kết khẳng định lại cảm xúc; đúng hình thức đoạn văn (khoảng 150–200 chữ), dùng từ đúng, viết đúng chính tả", p: 1 }], x: "Đoạn văn cần: câu mở đoạn giới thiệu bài thơ và cảm xúc chung; các câu tiếp theo nêu cảm xúc về cảnh làng quê, về hình ảnh người mẹ và nỗi nhớ quê (dẫn câu thơ), nhận xét cái hay của thể thơ lục bát; câu kết khẳng định lại cảm xúc.\nĐoạn văn tham khảo:\nBài thơ lục bát «Làng em» đã đưa em về với một làng quê thật bình yên và thân thương. Chỉ với tám dòng thơ, tác giả vẽ ra cả một bức tranh: dòng sông nước xanh uốn khúc giữa đồng lúa thơm, lũy tre xanh mát đôi bờ, đàn cò trắng lượn lơ thơ giữa trời. Đọc câu “Chiều chiều khói bếp mùi rơm”, em như ngửi thấy mùi rơm rạ quen thuộc mỗi lần về quê nội. Hình ảnh mẹ ngồi nhóm lửa thổi cơm “đợi chờ” khiến em xúc động, vì đó là hình ảnh của tình yêu thương. Em thích nhất hai dòng cuối: dù đi khắp mọi nơi, người con vẫn nghe tiếng mẹ “à ơi”. Nhịp thơ lục bát nhẹ nhàng, êm ả như lời ru, rất hợp với tình cảm tha thiết ấy. Bài thơ nhắc em luôn yêu quý quê hương, nơi có mẹ và những kỉ niệm tuổi thơ.", lv: 3, p: "lang-em" },
      { topic: "Viết", type: "essay", q: "Viết đoạn văn (khoảng 150–200 chữ) tả một cảnh sinh hoạt mà bạn đã chứng kiến (ví dụ: sân trường giờ ra chơi, phiên chợ quê buổi sáng, gia đình bạn chuẩn bị đón Tết).", rubric: [{ c: "Câu mở đoạn giới thiệu được cảnh sinh hoạt: cảnh gì, ở đâu, vào lúc nào", p: 0.5 }, { c: "Tả được quang cảnh chung và hoạt động của con người theo một trình tự hợp lí (từ bao quát đến cụ thể, hoặc theo thời gian)", p: 1.5 }, { c: "Có chi tiết cụ thể và từ ngữ gợi tả âm thanh, màu sắc, hoạt động (từ láy, so sánh, nhân hoá…)", p: 1 }, { c: "Nêu được cảm xúc, suy nghĩ của bạn về cảnh", p: 0.5 }, { c: "Đúng hình thức đoạn văn (khoảng 150–200 chữ); dùng từ đúng, viết đúng chính tả", p: 0.5 }], x: "Đoạn văn cần: câu mở đoạn giới thiệu cảnh sinh hoạt; các câu tiếp theo tả quang cảnh chung rồi tả các hoạt động cụ thể của con người, dùng từ ngữ gợi âm thanh, màu sắc; câu kết nêu cảm xúc.\nĐoạn văn tham khảo:\nTiếng trống ra chơi vừa vang lên, sân trường em bỗng chốc trở nên rộn rã. Từ các lớp học, học sinh ùa ra như đàn chim vỡ tổ. Dưới gốc bàng già, mấy bạn nữ nhảy dây, những bím tóc tung lên theo từng nhịp chân. Góc sân bên kia, các bạn nam chia thành hai đội đá cầu, quả cầu xanh đỏ bay vun vút qua lại. Tiếng hò reo, tiếng cười nói, tiếng vỗ tay hoà vào nhau náo nhiệt. Trên ghế đá, vài bạn chụm đầu đọc chung một cuốn truyện tranh, thỉnh thoảng lại cười khúc khích. Bác bảo vệ đứng bên cổng, mỉm cười nhìn đám học trò. Những tia nắng xuyên qua tán lá, nhảy nhót trên sân như cũng muốn chơi cùng chúng em. Chẳng mấy chốc, tiếng trống vào lớp lại vang lên. Em yêu biết bao những giờ ra chơi vui tươi, đầy ắp tiếng cười ấy.", lv: 3 }
    ]
  },

  /* ---------- Ngữ văn 6 · Kiểm tra giữa học kì I (Kết nối tri thức, Bài 1–3) (Phiên N24b) ----------
     Phạm vi như lịch gk1-l6 và bài ôn l6-giua-ki-1: Bài 1 Tôi và các bạn, Bài 2 Gõ cửa trái tim, Bài 3 Yêu thương và chia sẻ; phần
     Thực hành tiếng Việt của ba bài (từ đơn và từ phức; nghĩa của từ; biện pháp tu từ so sánh, nhân hoá, điệp ngữ, ẩn dụ; cụm danh
     từ, cụm động từ, cụm tính từ) và dấu câu đánh dấu lời nói trực tiếp (Bài 2, tr. 47; đối chiếu sách in năm 2026).
     Hai đề cố định cùng các câu riêng của "van6-gk1-ngau-nhien" bên dưới là kho của đề ngẫu nhiên; đề nào cũng đúng ma trận của đề
     ngẫu nhiên (data/banks/index.js): 10 Biết, 8 Hiểu, 7 Vận dụng. Mỗi đề đọc hiểu ba văn bản tự soạn, mỗi văn bản cùng thể loại với
     văn bản của một bài (đề 1: truyện đồng thoại kể theo ngôi thứ nhất, thơ năm chữ có yếu tố tự sự và miêu tả, truyện kể theo ngôi
     thứ ba; đề 2: truyện kể theo ngôi thứ nhất, thơ bốn chữ, truyện kể theo ngôi thứ ba), viết một lần ở passages; mỗi đoạn 4 câu
     mức 1-2-3-3, chủ đề là tên bài; câu nào cũng làm được khi chỉ rút riêng đoạn đó. Vài câu Vận dụng liên hệ với văn bản trong
     sách. 12 câu Tiếng Việt chỉ mức Biết, Hiểu, xếp mức như ghi ở đầu file. 1 câu Viết đoạn văn tự chấm (đề 1: cảm xúc về bài thơ
     ở phần đọc hiểu, đứng sau các câu của bài thơ; đề 2: kể lại một trải nghiệm); đoạn văn tham khảo không nêu đáp án câu đọc hiểu.
     Câu tự soạn. */
  "van6-gk1-de1": {
    note: "Giữa học kì I (Bài 1–3), sách Kết nối tri thức. 10 câu mức Biết, 8 câu mức Hiểu, 7 câu mức Vận dụng: đọc hiểu ba văn bản tự soạn (truyện đồng thoại, bài thơ, truyện), 12 câu tiếng Việt và một câu Viết đoạn văn tự chấm theo gợi ý. Có lời giải từng câu.",
    passages: {
      "kien-cang": {
        title: "Kiến Càng",
        text: "Tôi là Kiến Càng, con kiến khoẻ nhất tổ. Đôi càng của tôi to, chắc, tha được những hạt thóc nặng gấp mấy lần mình. Ai cũng khen, tôi lấy làm hãnh diện lắm, đi đâu cũng vênh râu lên.\nMột buổi sáng, cả đàn đi kiếm ăn. Bên bờ ruộng có một hạt ngô vàng óng, to hơn tôi đến mười lần. Kiến Nhỏ lon ton chạy lại:\n– Anh Càng ơi, để bọn em khiêng cùng anh nhé!\nTôi xua tay:\n– Tránh ra! Một mình tôi cũng thừa sức.\nTôi ghé vai đẩy. Hạt ngô lăn được mấy vòng thì trượt xuống con mương cạnh bờ ruộng. Tôi hốt hoảng níu lại nhưng không kịp: dòng nước cuốn hạt ngô trôi mất. Đứng trên bờ, tôi tiếc hùi hụi, chẳng dám nhìn mặt các bạn.\nHôm sau, gặp một con sâu khô to tướng, tôi vội gọi:\n– Các bạn ơi, mình cùng khiêng nhé!\nCả đàn xúm lại, mỗi bạn ghé một tay. Chẳng mấy chốc, con sâu đã nằm gọn trong kho của tổ. Nhìn các bạn reo hò, tôi hiểu ra: một đôi càng khoẻ không bằng nhiều đôi càng cùng góp sức."
      },
      "quat-nan": {
        title: "Quạt nan đêm hè",
        text: "Đêm hè trời oi quá,\nXóm nhỏ mất điện rồi.\nCon trở mình kêu nóng,\nBà cầm quạt ra ngồi.\n\nChiếc quạt nan phe phẩy\nĐưa gió mát đều tay.\nGió như từ đồng xa\nMang hương lúa về đây.\n\nBà kể chuyện ngày xưa:\nCô Tấm, quả thị thơm,\nChú Cuội ngồi gốc đa…\nGiọng bà ấm như rơm.\n\nNgoài sân, trăng lên cao,\nRắc vàng lên hàng cau.\nCon thiu thiu ngủ mất,\nTay bà vẫn chưa ngơi.\n\nSáng ra, con thức dậy,\nThấy bà ngồi bên hiên.\nMắt bà hằn quầng thâm\nMà môi vẫn cười hiền.\n\nCon ôm bà thật chặt,\nThương bà quá, bà ơi!\nƯớc con mau lớn lên,\nQuạt cho bà nghỉ ngơi."
      },
      "den-ong-sao": {
        title: "Chiếc đèn ông sao",
        text: "Còn ba ngày nữa là đến Tết Trung thu. Chiều nào, Hà và em trai là Tũn cũng ngồi trên hiên, ngắm chiếc đèn ông sao màu đỏ bố mua cho hai chị em.\nNhà bên cạnh có bé Tí lên sáu tuổi. Bố mẹ Tí đi làm ăn xa, Tí ở với bà nội. Mấy hôm nay, cứ thấy chị em Hà mang đèn ra, Tí lại đứng nép sau bờ rào, mắt không rời chiếc đèn.\nTối ấy, Hà thì thầm với em:\n– Tũn ơi, mình làm thêm một chiếc đèn tặng Tí nhé!\nTũn gật đầu ngay. Hai chị em xin bố mấy thanh tre, lục tìm giấy bóng kính còn thừa từ năm ngoái. Hà vót nan, Tũn quét hồ dán giấy. Có lúc nan tre cứa vào tay Hà rớm máu, Hà chỉ xuýt xoa một chút rồi lại làm tiếp. Gần mười giờ đêm, chiếc đèn ông sao màu vàng mới xong. Đèn hơi méo một cánh, nhưng hai chị em ngắm mãi không chán.\nĐêm rằm, Hà dắt Tũn sang nhà bà Tí. Vừa thấy chiếc đèn, Tí reo lên, ôm chặt lấy nó như sợ ai lấy mất. Bà Tí rưng rưng nắm tay hai chị em. Rồi ba đứa trẻ cùng nhau rước đèn quanh xóm. Hai ngôi sao, một đỏ, một vàng, lung linh dưới ánh trăng rằm."
      }
    },
    questions: [
      { topic: "Tôi và các bạn", type: "mc", q: "Theo văn bản, vì sao hạt ngô bị mất?", o: ["Kiến Càng đẩy một mình, hạt ngô lăn xuống mương, bị nước cuốn đi", "Kiến Nhỏ khiêng vụng về nên làm hạt ngô rơi xuống mương", "Một con chim sà xuống, tha hạt ngô bay đi mất hút", "Cả đàn tranh nhau khiêng nên hạt ngô bị vỡ làm đôi"], x: "Văn bản kể: Kiến Càng gạt Kiến Nhỏ ra, ghé vai đẩy một mình; hạt ngô “trượt xuống con mương cạnh bờ ruộng” rồi “dòng nước cuốn hạt ngô trôi mất”.", lv: 1, p: "kien-cang" },
      { topic: "Tôi và các bạn", type: "mc", q: "Lời nói «Tránh ra! Một mình tôi cũng thừa sức.» cho thấy lúc đầu Kiến Càng có tính cách thế nào?", o: ["Tự đắc, coi thường sự giúp đỡ của bạn", "Khiêm tốn, biết nhường việc cho bạn", "Nhút nhát, ngại nhờ người khác giúp", "Chu đáo, sợ các bạn khiêng nặng sẽ mệt"], x: "Kiến Càng quát “Tránh ra!” và cho rằng một mình cũng thừa sức, không cần ai. Cùng với chi tiết “đi đâu cũng vênh râu lên”, lời nói ấy cho thấy Kiến Càng tự đắc, coi thường bạn bè, chứ không phải vì lo cho các bạn.", lv: 2, p: "kien-cang" },
      { topic: "Tôi và các bạn", type: "mc", q: "Kiến Càng có điểm gì giống nhân vật Dế Mèn trong văn bản «Bài học đường đời đầu tiên» (Tô Hoài)?", o: ["Cậy mình khoẻ, coi thường người khác, gây chuyện đáng tiếc rồi mới nhận ra lỗi", "Bị chị Cốc mổ vì bày trò trêu chọc, rồi được các bạn trong tổ cứu thoát", "Sống lủi thủi một mình trong hang, chẳng bao giờ dám trò chuyện với ai", "Ngay từ đầu đã biết nhường nhịn, giúp đỡ những bạn yếu hơn mình"], x: "Dế Mèn cậy mình khoẻ, kiêu căng, xem thường Dế Choắt, bày trò trêu chị Cốc khiến Dế Choắt bị mổ chết, rồi ân hận và rút ra bài học đường đời đầu tiên. Kiến Càng cũng cậy khoẻ, gạt các bạn ra, làm mất hạt ngô, rồi mới hiểu ra phải biết cùng nhau góp sức. Người bị chị Cốc mổ là Dế Choắt.", lv: 3, p: "kien-cang" },
      { topic: "Tôi và các bạn", type: "tf4", q: "Huy khéo tay nhất lớp nên muốn tự làm hết phần trang trí lớp, không để các bạn phụ giúp. Học từ câu chuyện của Kiến Càng, mỗi lời khuyên sau dành cho Huy đúng hay sai?", o: ["Cậu khéo nhất lớp nên không cần ai giúp cả.", "Mình cùng làm nhé, mỗi người góp một tay sẽ nhanh và vui hơn.", "Cứ làm một mình đi, xong thì cả lớp chỉ khen mỗi cậu.", "Cậu có thể chỉ cho các bạn cách cắt, dán để cả lớp cùng làm."], a: [false, true, false, true], x: "a), c) Sai: đó chính là cách nghĩ tự đắc của Kiến Càng lúc đầu, khiến cả đàn mất hạt ngô. b), d) Đúng: như Kiến Càng hiểu ra ở cuối truyện, nhiều người cùng góp sức thì việc chung nhanh và tốt hơn; người khéo tay có thể giúp các bạn cùng làm.", lv: 3, p: "kien-cang" },
      { topic: "Gõ cửa trái tim", type: "mc", q: "Theo bài thơ «Quạt nan đêm hè», vì sao đêm ấy bà cầm quạt ra ngồi bên cháu?", o: ["Vì xóm mất điện, trời oi, cháu trở mình kêu nóng", "Vì quạt điện trong nhà bị hỏng từ hôm trước", "Vì bà thích dùng quạt nan hơn quạt điện", "Vì cháu đòi bà kể chuyện cổ tích mới chịu ngủ"], x: "Khổ thơ đầu kể: “Đêm hè trời oi quá, / Xóm nhỏ mất điện rồi. / Con trở mình kêu nóng, / Bà cầm quạt ra ngồi.”", lv: 1, p: "quat-nan" },
      { topic: "Gõ cửa trái tim", type: "mc", q: "Hai dòng thơ «Mắt bà hằn quầng thâm / Mà môi vẫn cười hiền» giúp bạn hiểu điều gì về người bà?", o: ["Bà thức quạt cho cháu gần hết đêm, mệt nhưng vẫn vui vì cháu ngủ ngon", "Bà bị ốm cả đêm nên sáng ra phải ngồi ngoài hiên cho mát", "Bà buồn vì cháu ngủ quên mất, chưa nghe hết câu chuyện", "Bà vừa đi chợ từ sáng sớm nên thấy mệt nhưng vẫn vui"], x: "Khổ thơ trước kể: cháu đã ngủ mà “Tay bà vẫn chưa ngơi”. Sáng ra, mắt bà “hằn quầng thâm” vì bà thức quạt cho cháu gần hết đêm, nhưng môi bà “vẫn cười hiền”: bà mệt mà vẫn vui vì cháu được ngủ ngon. Hai dòng thơ cho thấy tình thương bao la, sự hi sinh lặng lẽ của bà.", lv: 2, p: "quat-nan" },
      { topic: "Gõ cửa trái tim", type: "mc", q: "Hai dòng cuối «Ước con mau lớn lên, / Quạt cho bà nghỉ ngơi.» gợi cho bạn suy nghĩ gì về cách đáp lại tình thương của ông bà?", o: ["Biết ơn và chăm sóc lại ông bà bằng những việc làm vừa sức", "Chỉ khi lớn lên rồi mới cần quan tâm đến ông bà", "Ông bà chăm cháu là việc đương nhiên, không cần đáp lại", "Chỉ cần nói lời cảm ơn, không cần làm gì thêm"], x: "Người cháu thương bà, mong được lớn để quạt cho bà như bà đã quạt cho mình. Từ đó, ta hiểu: cần biết ơn ông bà và đáp lại tình thương ấy bằng việc làm ngay từ bây giờ, với những việc vừa sức như rót nước, quạt cho bà, đọc truyện cho ông nghe; không cần đợi lớn mới quan tâm đến ông bà.", lv: 3, p: "quat-nan" },
      { topic: "Gõ cửa trái tim", type: "mc", q: "Bạn muốn viết thêm vào bài thơ «Quạt nan đêm hè» một khổ kể việc người cháu làm cho bà vào ngày hôm sau. Khổ thơ nào dưới đây hợp với bài thơ nhất?", o: ["Trưa nay con nhặt rau, / Nấu bát canh mồng tơi. / Bà ăn, khen ngọt quá, / Con nghe vui cả người.", "Trưa nay con nấu nồi canh, / Mồng tơi xanh mướt, bà khen ngọt lành.", "Trưa nay con vào bếp nấu cho bà một bát canh mồng tơi thật ngon.", "Con thương bà nhiều lắm, / Thương bà mãi, bà ơi, / Thương bà như thương mẹ, / Thương mãi chẳng thể thôi."], x: "Bài thơ viết theo thể thơ năm chữ (mỗi dòng năm tiếng), chia khổ bốn dòng, vừa kể việc vừa tả hình ảnh. Khổ “Trưa nay con nhặt rau…” giữ đúng năm chữ, bốn dòng và kể được việc người cháu làm cho bà. Khổ “Trưa nay con nấu nồi canh…” viết theo thể lục bát; câu “Trưa nay con vào bếp…” là câu văn, không phải khổ thơ; khổ “Con thương bà nhiều lắm…” đúng năm chữ nhưng chỉ bày tỏ tình cảm, không kể việc gì.", lv: 3, p: "quat-nan" },
      { topic: "Viết", type: "essay", q: "Viết đoạn văn (khoảng 150–200 chữ) ghi lại cảm xúc của bạn về bài thơ «Quạt nan đêm hè».", rubric: [{ c: "Câu mở đoạn nêu được tên bài thơ và cảm xúc chung của bạn", p: 0.5 }, { c: "Nêu cảm xúc về câu chuyện được kể trong bài thơ (bà quạt, kể chuyện cho cháu ngủ trong đêm hè) và tình cảm bà cháu", p: 1 }, { c: "Nêu cảm xúc về ít nhất hai hình ảnh, chi tiết miêu tả hay trong bài (làn gió, ánh trăng, giọng bà, đôi mắt bà…), có dẫn câu thơ", p: 1.5 }, { c: "Câu kết khẳng định lại cảm xúc hoặc nêu điều bài thơ gợi cho bạn", p: 0.5 }, { c: "Đúng hình thức đoạn văn (khoảng 150–200 chữ); dùng từ đúng, viết đúng chính tả", p: 0.5 }], x: "Đoạn văn cần: câu mở đoạn giới thiệu bài thơ và cảm xúc chung; các câu tiếp theo nêu cảm xúc về câu chuyện trong bài thơ và về những hình ảnh, câu thơ hay (dẫn câu thơ); câu kết khẳng định lại cảm xúc.\nĐoạn văn tham khảo:\nĐọc bài thơ «Quạt nan đêm hè», em thấy lòng mình ấm áp như được trở về bên bà trong một đêm hè oi ả. Bài thơ kể một chuyện rất bình dị: bà ngồi bên giường, phe phẩy chiếc quạt nan và kể chuyện cho cháu ngủ. Em thích hai câu thơ “Gió như từ đồng xa / Mang hương lúa về đây”, vì chiếc quạt nhỏ trong tay bà như mang cả làn gió quê mát lành vào giấc ngủ của cháu. Bà kể chuyện cô Tấm, chú Cuội bằng giọng “ấm như rơm”, khiến em nhớ những buổi tối được nghe bà nội kể chuyện. Cảnh trăng “rắc vàng lên hàng cau” làm đêm hè thêm dịu dàng, yên ả. Em xúc động nhất ở khổ thơ thứ năm, khi người cháu thức dậy và nhìn thấy bà ngồi bên hiên. Câu thơ ấy khiến em nghẹn ngào thương bà. Bài thơ nhắc em luôn nhớ tình thương lặng lẽ, bao la mà ông bà dành cho con cháu.", lv: 3, p: "quat-nan" },
      { topic: "Yêu thương và chia sẻ", type: "fill", q: "Theo văn bản, chiếc đèn ông sao hai chị em tự làm để tặng Tí có màu ___.", ans: ["vàng", "màu vàng"], x: "Văn bản viết: “Gần mười giờ đêm, chiếc đèn ông sao màu vàng mới xong.” Chiếc đèn màu đỏ là đèn bố mua cho hai chị em.", lv: 1, p: "den-ong-sao" },
      { topic: "Yêu thương và chia sẻ", type: "mc", q: "Chi tiết Tí «đứng nép sau bờ rào, mắt không rời chiếc đèn» cho thấy điều gì?", o: ["Tí rất muốn có một chiếc đèn nhưng không có", "Tí sợ chị em Hà nên không dám sang chơi", "Tí đang chơi trốn tìm với các bạn trong xóm", "Tí không thích Tết Trung thu ồn ào"], x: "Ngày nào Tí cũng đứng nhìn chiếc đèn, “mắt không rời”: Tí thèm được cầm đèn như bao bạn nhỏ khác, nhưng bố mẹ đi làm ăn xa, Tí không có đèn. Hà hiểu điều đó nên mới rủ em làm đèn tặng Tí.", lv: 2, p: "den-ong-sao" },
      { topic: "Yêu thương và chia sẻ", type: "tf4", q: "Học theo chị em Hà, mỗi việc làm sau có phải là cách chia sẻ phù hợp không? Chọn đúng hoặc sai cho từng ý.", o: ["Tự tay làm một tấm thiệp tặng bạn đang phải nằm viện.", "Cho bạn mượn đồ chơi rồi kể với cả lớp là nhà bạn nghèo.", "Chỉ giúp đỡ người khác khi được thầy cô khen thưởng.", "Góp sách cũ còn tốt cho thư viện của một trường vùng khó khăn."], a: [true, false, false, true], x: "a), d) Đúng: như chị em Hà, đó là những việc làm xuất phát từ tấm lòng, giúp người khác vui hơn, đỡ thiếu thốn hơn. b) Sai: kể chuyện nhà bạn nghèo trước lớp làm bạn tủi thân; chia sẻ cần tế nhị. c) Sai: chị em Hà làm đèn tặng Tí vì thương Tí, không phải để được khen.", lv: 3, p: "den-ong-sao" },
      { topic: "Yêu thương và chia sẻ", type: "mc", q: "Nếu được kể tiếp câu chuyện, đoạn kết nào phù hợp nhất với các nhân vật?", o: ["Năm sau, Tí cùng chị em Hà làm đèn tặng các em nhỏ khác trong xóm", "Tí giữ khư khư chiếc đèn, không cho Hà và Tũn chạm vào", "Hà đòi lại chiếc đèn vàng vì thấy nó đẹp hơn đèn của mình", "Tũn giận chị vì phải thức khuya làm đèn cho Tí"], x: "Câu chuyện ca ngợi tấm lòng biết chia sẻ của hai chị em; cuối truyện, ba đứa trẻ cùng rước đèn vui vẻ. Đoạn kết Tí cùng chị em Hà làm đèn tặng các em nhỏ khác tiếp nối được tình yêu thương ấy. Các đoạn kết còn lại trái với tính cách nhân vật: Hà, Tũn làm đèn vì thương Tí, còn Tí đã cùng hai chị em rước đèn quanh xóm.", lv: 3, p: "den-ong-sao" },
      { topic: "Từ đơn và từ phức", type: "mc", q: "Từ nào dưới đây là từ ghép?", o: ["bàn học", "lấp ló", "thăm thẳm", "líu lo"], x: "“Bàn học” gồm hai tiếng đều có nghĩa, ghép lại để chỉ loại bàn dùng để học: từ ghép. “Lấp ló”, “thăm thẳm”, “líu lo” có các tiếng giống nhau về âm hoặc vần: từ láy.", lv: 1 },
      { topic: "Từ đơn và từ phức", type: "tf4", q: "Mỗi nhận xét sau về các từ trong câu «Mẹ em trồng mấy khóm hoa nhài thơm ngát.» đúng hay sai?", o: ["“khóm” là từ phức.", "“mẹ” là từ đơn.", "“hoa nhài” là từ ghép.", "“thơm ngát” là từ láy."], a: [false, true, true, false], x: "a) Sai: “khóm” chỉ có một tiếng, là từ đơn. b) Đúng: “mẹ” chỉ có một tiếng. c) Đúng: “hoa nhài” gồm hai tiếng đều có nghĩa, ghép lại chỉ một loài hoa. d) Sai: “ngát” cũng có nghĩa (thơm lan toả xa), hai tiếng “thơm”, “ngát” ghép với nhau về nghĩa, nên “thơm ngát” là từ ghép.", lv: 1 },
      { topic: "Từ đơn và từ phức", type: "mc", q: "Trong câu «Mấy chiếc lá vàng chao nghiêng rồi rơi lả tả xuống sân.», từ láy “lả tả” gợi tả điều gì?", o: ["Lá rơi rải rác, nhẹ nhàng, nối tiếp nhau", "Một chiếc lá rơi thật nhanh, thật mạnh xuống đất", "Tiếng gió thổi ào ào, rít mạnh qua sân", "Màu vàng tươi, rực rỡ của những chiếc lá"], x: "“Lả tả” gợi hình ảnh nhiều vật nhỏ, nhẹ (lá, hoa) rơi rải rác, chỗ này chỗ kia, nối tiếp nhau. Nhờ từ láy này, người đọc hình dung rõ cảnh lá vàng rơi nhẹ nhàng xuống sân.", lv: 2 },
      { topic: "Nghĩa của từ", type: "mc", q: "Từ “ân hận” trong câu «Lỡ làm vỡ chiếc bình của mẹ, Nam ân hận mãi.» có nghĩa là:", o: ["Day dứt, tiếc nuối vì đã làm điều không nên làm", "Vui mừng vì đã được mọi người tha thứ cho mình", "Sợ hãi, lo lắng vì biết mình sắp bị mắng", "Tức giận vì bị người khác đổ oan cho mình"], x: "“Ân hận” là day dứt, tự trách mình vì đã làm điều sai, điều không nên làm. Nam làm vỡ bình của mẹ nên ân hận mãi.", lv: 2 },
      { topic: "Nghĩa của từ", type: "match", q: "Yếu tố “hoá” đứng sau yếu tố khác có nghĩa là trở thành, làm cho trở thành. Nối mỗi từ với nghĩa của nó.", l: ["cảm hoá", "hiện đại hoá", "tự động hoá"], r: ["Dùng tình cảm, việc làm tốt khiến người khác thay đổi theo hướng tốt", "Làm cho trường học, nhà máy… có máy móc, cách làm mới, tiên tiến", "Làm cho máy móc tự vận hành, không cần người điều khiển trực tiếp", "Làm cho một vật to lớn hơn trước"], x: "Cảm hoá: dùng tình cảm, việc làm tốt khiến người khác thay đổi theo hướng tốt. Hiện đại hoá: làm cho trở nên hiện đại, có máy móc, cách làm tiên tiến. Tự động hoá: làm cho máy móc tự vận hành. Ô “Làm cho một vật to lớn hơn trước” không ứng với từ nào.", lv: 2 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Câu «Mặt trăng tròn vành vạnh như chiếc mâm bạc.» dùng biện pháp tu từ nào?", o: ["So sánh", "Nhân hoá", "Ẩn dụ", "Điệp ngữ"], x: "Câu văn đối chiếu mặt trăng với chiếc mâm bạc (cùng tròn, cùng sáng), có từ so sánh “như”: đó là biện pháp so sánh.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "tf", q: "Câu «Chị gió đi qua, khẽ lay tỉnh những bông hoa còn ngái ngủ.» dùng biện pháp nhân hoá.", a: true, x: "Đúng. Gió được gọi bằng “chị” như gọi người và có hoạt động như người (khẽ lay tỉnh); những bông hoa cũng “ngái ngủ” như người. Đó là biện pháp nhân hoá.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Trong câu «Sáng sớm, những hạt ngọc long lanh còn đọng trên lá cỏ.», “hạt ngọc” được dùng để chỉ những giọt sương. Đây là biện pháp tu từ nào?", o: ["Ẩn dụ", "So sánh", "Nhân hoá", "Điệp ngữ"], x: "Câu văn không nói thẳng “giọt sương” mà gọi giọt sương là “hạt ngọc”, dựa trên nét giống nhau (trong, long lanh, quý). Gọi tên sự vật này bằng tên sự vật khác có nét tương đồng là ẩn dụ. Câu không có từ so sánh như “như”, “là”.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Đoạn văn: «Em yêu ngôi trường này. Em yêu từng hàng ghế đá, từng gốc phượng già. Em yêu cả tiếng trống trường mỗi sáng.» Việc lặp lại cụm từ “Em yêu” có tác dụng gì?", o: ["Nhấn mạnh tình yêu, sự gắn bó của em với ngôi trường", "Kể lại các việc em làm ở trường theo thứ tự thời gian", "Giới thiệu tên và địa chỉ của ngôi trường cho người đọc", "Tả màu sắc của sân trường vào mỗi buổi sáng sớm"], x: "Cụm từ “Em yêu” được lặp lại ở đầu ba câu (điệp ngữ), nhấn mạnh tình yêu, sự gắn bó của em với từng cảnh vật của ngôi trường và làm cho đoạn văn có nhịp điệu, giàu cảm xúc.", lv: 2 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "mc", q: "Cụm từ nào dưới đây là cụm động từ?", o: ["đang tưới cây ngoài vườn", "những cây hoa hồng ngoài vườn", "vẫn còn rất tươi", "chiếc bình gốm cổ của bà"], x: "“Đang tưới cây ngoài vườn” có động từ “tưới” làm trung tâm: cụm động từ. “Những cây hoa hồng ngoài vườn”, “chiếc bình gốm cổ của bà” là cụm danh từ; “vẫn còn rất tươi” là cụm tính từ.", lv: 1 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "mc", q: "Trong cụm danh từ “những học sinh chăm ngoan của lớp em”, danh từ trung tâm là:", o: ["học sinh", "những", "chăm ngoan", "lớp em"], x: "Danh từ “học sinh” làm trung tâm; “những” đứng trước chỉ số lượng; “chăm ngoan”, “của lớp em” đứng sau, nói rõ đặc điểm và nơi của các bạn học sinh.", lv: 1 },
      { topic: "Dấu câu", type: "mc", q: "Dấu gạch ngang trong đoạn «Bà nhìn cháu, cười hiền: – Cháu bà ngoan quá!» dùng để làm gì?", o: ["Đánh dấu lời nói trực tiếp của nhân vật", "Đánh dấu phần giải thích, chú thích", "Nối các từ ngữ trong một liên danh", "Đánh dấu các ý được liệt kê"], x: "Dấu gạch ngang đứng trước “Cháu bà ngoan quá!”, là lời bà nói với cháu: dấu gạch ngang đánh dấu lời nói trực tiếp (lời đối thoại) của nhân vật. Trong truyện, lời nhân vật thường được viết xuống dòng, có dấu gạch ngang ở đầu.", lv: 2 }
    ]
  },
  "van6-gk1-de2": {
    note: "Giữa học kì I (Bài 1–3), sách Kết nối tri thức. 10 câu mức Biết, 8 câu mức Hiểu, 7 câu mức Vận dụng: đọc hiểu ba văn bản tự soạn (truyện, bài thơ, truyện), 12 câu tiếng Việt và một câu Viết đoạn văn tự chấm theo gợi ý. Có lời giải từng câu.",
    passages: {
      "ban-it-noi": {
        title: "Người bạn ít nói",
        text: "Đầu năm lớp 6, cô chủ nhiệm xếp tôi ngồi cạnh Quang. Quang ít nói lắm. Giờ ra chơi, cả lớp ùa ra sân, còn Quang ngồi lại trong lớp, cặm cụi gấp những con hạc giấy. Tôi rủ Quang đá cầu, cậu lắc đầu. Tôi hỏi chuyện, cậu chỉ đáp “ừ”, “không”. Tôi nghĩ bụng: “Chắc cậu ta kiêu lắm, chẳng thèm chơi với ai.”\nMột hôm, tôi để quên hộp bút ở nhà. Quang lặng lẽ đẩy sang tôi một cây bút chì đã gọt sẵn. Hôm khác, thấy tôi loay hoay mãi với một bài toán khó, Quang ở lại cuối giờ, giảng cho tôi từng bước. Từ đó, tôi bắt đầu để ý đến cậu nhiều hơn.\nTôi không rủ Quang ra sân nữa mà ngồi lại cùng cậu, nhờ cậu dạy gấp hạc. Ngày đầu, cậu chỉ cho tôi một nếp gấp. Ngày thứ hai, cậu kể rằng mẹ cậu bị ốm, phải nằm viện đã lâu, cậu muốn gấp thật nhiều hạc để tặng mẹ. Đến cuối tuần, hai đứa đã gấp được hơn hai trăm con.\nHôm mẹ Quang ra viện, Quang mang đến lớp tặng tôi một con hạc màu xanh. Trên cánh hạc có dòng chữ nhỏ: “Cảm ơn cậu.” Đến bây giờ, con hạc ấy vẫn đậu trên bàn học của tôi."
      },
      "me-ve": {
        title: "Chiều mưa mẹ về",
        text: "Chiều nay mưa to,\nMẹ chưa về tới.\nCon ra cửa đợi,\nMắt dõi ngõ xa.\n\nNgoài hiên mưa sa,\nLộp độp mái tôn.\nCây chuối ướt cả,\nRun run tàu lá.\n\nRồi xe mẹ về,\nÁo mưa sũng nước.\nMẹ cười, bước vội,\nTay ôm gói quà.\n\nQuyển truyện con thích,\nMẹ bọc kĩ càng,\nGiữ trong áo mưa,\nChẳng ướt trang nào.\n\nTóc mẹ ướt mèm,\nCon lau khăn mềm.\nMẹ ôm con khẽ:\n“Quà nhỏ thôi mà!”\n\nCon thương mẹ lắm,\nMưa gió đường xa.\nMột món quà nhỏ\nMà ấm cả nhà."
      },
      "ba-cu-nam": {
        title: "Bà cụ Năm học gọi điện",
        text: "Bà cụ Năm sống một mình trong căn nhà nhỏ cuối ngõ. Con trai bà làm việc ở một công trường xa, cả năm mới về được một lần. Tết vừa rồi, anh gửi về cho bà một chiếc điện thoại màn hình to, dặn bà gọi cho anh để hai mẹ con được nhìn thấy nhau. Nhưng mắt bà đã kém, tay lại run, bà cứ bấm nhầm mãi. Chiếc điện thoại nằm im trong tủ, phủ một lớp bụi mỏng.\nMột chiều, Ngân và em trai là Tuấn sang biếu bà ít ổi vườn nhà. Thấy chiếc điện thoại, Ngân hỏi chuyện. Bà cười buồn:\n– Bà già rồi, học không nổi đâu các cháu ạ.\nNgân không nói gì, lấy giấy bút ra, vẽ thật to từng bước: nút màu xanh để gọi, nút màu đỏ để tắt. Tuấn dán tờ giấy lên tường, ngay cạnh chỗ bà hay ngồi. Chiều nào hai chị em cũng sang, cầm tay bà bấm thử. Có hôm bà quên, phải tập lại từ đầu, Ngân vẫn kiên nhẫn chỉ cho bà từng nút một.\nĐến ngày thứ năm, bà tự gọi được cho con trai. Trên màn hình hiện ra gương mặt anh, đen sạm vì nắng gió. Bà ghé sát vào màn hình, vừa nói vừa cười, rồi lại đưa tay lên lau nước mắt. Ngân và Tuấn đứng ngoài hiên, nhìn nhau cười."
      }
    },
    questions: [
      { topic: "Tôi và các bạn", type: "mc", q: "Giờ ra chơi, Quang thường làm gì?", o: ["Ngồi lại trong lớp, gấp những con hạc giấy", "Chạy ra sân đá cầu cùng các bạn", "Lên thư viện đọc truyện một mình", "Ngồi giải trước bài tập Toán về nhà"], x: "Văn bản viết: “Giờ ra chơi, cả lớp ùa ra sân, còn Quang ngồi lại trong lớp, cặm cụi gấp những con hạc giấy.”", lv: 1, p: "ban-it-noi" },
      { topic: "Tôi và các bạn", type: "mc", q: "Câu chuyện «Người bạn ít nói» được kể bằng lời của ai?", o: ["Bạn ngồi cạnh Quang, xưng “tôi”, kể chuyện mình đã trải qua", "Quang, xưng “tôi”, tự kể về những con hạc của mình", "Cô giáo chủ nhiệm, kể lại chuyện của hai học trò", "Một người kể giấu mặt, không tham gia vào câu chuyện"], x: "Người kể xưng “tôi”, là bạn được cô xếp ngồi cạnh Quang, trực tiếp tham gia và kể lại câu chuyện của mình: truyện được kể theo ngôi thứ nhất. Quang được người kể gọi bằng tên hoặc “cậu”.", lv: 2, p: "ban-it-noi" },
      { topic: "Tôi và các bạn", type: "mc", q: "Lớp bạn có một bạn mới chuyển đến, rất ít nói, giờ ra chơi thường ngồi một mình. Học từ câu chuyện, bạn nên làm gì để kết bạn với bạn ấy?", o: ["Ngồi lại cùng bạn, hỏi han và cùng làm việc bạn ấy thích", "Nghĩ rằng bạn ấy kiêu nên thôi không chơi cùng", "Rủ cả nhóm vây quanh trêu cho bạn ấy nói nhiều hơn", "Chờ đến khi bạn ấy tự đến làm quen trước"], x: "Người kể chỉ thật sự hiểu Quang khi thôi kéo Quang ra sân, ngồi lại cùng cậu gấp hạc và lắng nghe cậu kể chuyện. Muốn kết bạn với một bạn ít nói, ta nên kiên nhẫn ở bên, quan tâm và cùng làm điều bạn ấy thích, không vội cho rằng bạn ấy kiêu.", lv: 3, p: "ban-it-noi" },
      { topic: "Tôi và các bạn", type: "mc", q: "Ngoài nhan đề «Người bạn ít nói», nhan đề nào dưới đây cũng phù hợp với câu chuyện?", o: ["Những con hạc giấy", "Giờ ra chơi trên sân trường", "Hộp bút bị bỏ quên", "Bài toán khó cuối giờ"], x: "Những con hạc giấy gắn với cả câu chuyện: Quang gấp hạc để tặng mẹ, hai bạn thân nhau khi cùng gấp hạc, và con hạc xanh là món quà kỉ niệm của tình bạn. Các nhan đề còn lại chỉ nói đến một chi tiết phụ.", lv: 3, p: "ban-it-noi" },
      { topic: "Gõ cửa trái tim", type: "fill", q: "Theo bài thơ «Chiều mưa mẹ về», món quà mẹ mang về cho con là một quyển ___.", ans: ["truyện", "truyện con thích", "quyển truyện"], x: "Bài thơ viết: “Quyển truyện con thích, / Mẹ bọc kĩ càng”.", lv: 1, p: "me-ve" },
      { topic: "Gõ cửa trái tim", type: "tf4", q: "Đọc lại bài thơ «Chiều mưa mẹ về». Mỗi ý sau đúng hay sai?", o: ["Mỗi dòng của bài thơ có năm tiếng.", "Bài thơ kể lại việc con ra cửa đợi và mẹ đội mưa về nhà.", "Người kể trong bài thơ là người mẹ.", "Các dòng «Lộp độp mái tôn / Cây chuối ướt cả / Run run tàu lá» tả cảnh trời mưa."], a: [false, true, false, true], x: "a) Sai: mỗi dòng có bốn tiếng, ví dụ: Chiều / nay / mưa / to; đây là thơ bốn chữ. b) Đúng: bài thơ kể việc (con đợi, mẹ đội mưa về, con lau tóc cho mẹ): đó là yếu tố tự sự. c) Sai: người kể xưng “con”, gọi “mẹ”, nên người kể là người con. d) Đúng: tiếng mưa “lộp độp”, cây chuối “ướt cả”, tàu lá “run run” là yếu tố miêu tả.", lv: 2, p: "me-ve" },
      { topic: "Gõ cửa trái tim", type: "mc", q: "Mẹ bọc kĩ quyển truyện trong áo mưa nên «Chẳng ướt trang nào», còn tóc mẹ thì «ướt mèm». Nếu là người con, bạn sẽ nói gì với mẹ cho phù hợp nhất?", o: ["Con cảm ơn mẹ! Mưa to thì mẹ cứ trú mưa, con đợi được ạ.", "Sao mẹ về muộn thế? Con đứng đợi ở cửa mãi rồi đấy!", "Lần sau mẹ nhớ mua cho con quyển truyện dày hơn nữa nhé!", "Mẹ tự lau tóc đi ạ, con phải đọc truyện ngay bây giờ đây."], x: "Mẹ lo cho món quà của con hơn cả cho bản thân mình. Lời nói phù hợp vừa cảm ơn mẹ, vừa thể hiện sự quan tâm đến mẹ. Các câu còn lại chỉ nghĩ đến mình, chưa biết thương mẹ vất vả.", lv: 3, p: "me-ve" },
      { topic: "Gõ cửa trái tim", type: "mc", q: "Bài thơ «Chiều mưa mẹ về» gợi cho bạn suy nghĩ gì về những món quà trong gia đình?", o: ["Món quà quý nhất là tấm lòng yêu thương, không phải giá tiền", "Quà càng đắt tiền thì tình cảm càng nhiều", "Chỉ những ngày lễ, Tết mới cần tặng quà cho nhau", "Quà phải được gói thật đẹp mới có ý nghĩa"], x: "Món quà chỉ là một quyển truyện nhỏ (“Quà nhỏ thôi mà!”), nhưng mẹ đã đội mưa, bọc kĩ để giữ cho con. Hai dòng cuối “Một món quà nhỏ / Mà ấm cả nhà” cho thấy: điều làm món quà quý là tấm lòng yêu thương của người tặng.", lv: 3, p: "me-ve" },
      { topic: "Yêu thương và chia sẻ", type: "mc", q: "Vì sao chiếc điện thoại con trai gửi về lại nằm im trong tủ?", o: ["Vì mắt bà kém, tay run, bà cứ bấm nhầm mãi", "Vì bà không thích nói chuyện qua điện thoại", "Vì chiếc điện thoại bị hỏng ngay từ đầu", "Vì con trai dặn bà chỉ dùng vào dịp Tết"], x: "Văn bản viết: “Nhưng mắt bà đã kém, tay lại run, bà cứ bấm nhầm mãi. Chiếc điện thoại nằm im trong tủ…”", lv: 1, p: "ba-cu-nam" },
      { topic: "Yêu thương và chia sẻ", type: "mc", q: "Việc Ngân «vẽ thật to từng bước: nút màu xanh để gọi, nút màu đỏ để tắt» cho thấy Ngân là người thế nào?", o: ["Tinh ý, biết nghĩ cách giúp bà dễ nhìn, dễ nhớ", "Thích vẽ tranh hơn là giúp đỡ người khác", "Nóng vội, chỉ muốn làm cho xong việc", "Thích khoe mình giỏi dùng điện thoại"], x: "Biết mắt bà kém, Ngân vẽ thật to, dùng màu xanh, màu đỏ cho dễ phân biệt, rồi dán ngay chỗ bà hay ngồi. Việc làm ấy cho thấy Ngân tinh ý, biết nghĩ cho bà.", lv: 2, p: "ba-cu-nam" },
      { topic: "Yêu thương và chia sẻ", type: "mc", q: "Nếu muốn giúp ông bà mình làm quen với một việc mới (dùng điện thoại, xem lịch trên mạng…), bạn học được gì từ cách làm của Ngân?", o: ["Chỉ từng bước đơn giản, dễ nhìn và kiên nhẫn khi ông bà quên", "Làm hộ luôn cho nhanh, không cần chỉ cho ông bà nữa", "Nói thật nhanh một lần thôi, ông bà phải tự nhớ lấy", "Chê ông bà chậm chạp để ông bà cố gắng nhiều hơn"], x: "Ngân vẽ to từng bước, dán ở chỗ bà hay ngồi, ngày nào cũng cầm tay bà tập và kiên nhẫn chỉ lại khi bà quên. Nhờ vậy bà tự gọi được cho con. Giúp ông bà làm quen với việc mới cũng cần chỉ đơn giản, từ từ và kiên nhẫn như thế.", lv: 3, p: "ba-cu-nam" },
      { topic: "Yêu thương và chia sẻ", type: "tf4", q: "Từ câu chuyện của chị em Ngân, một bạn rút ra bốn điều. Mỗi điều đúng hay sai?", o: ["Chỉ nên giúp đỡ người thân trong gia đình mình.", "Quan tâm đến người hàng xóm sống một mình là việc đáng làm.", "Một việc làm nhỏ cũng có thể mang lại niềm vui lớn cho người khác.", "Người già thì không thể học thêm điều gì mới."], a: [false, true, true, false], x: "a) Sai: bà cụ Năm là hàng xóm, không phải người thân, vậy mà hai chị em vẫn ngày ngày sang giúp. b) Đúng: bà cụ Năm sống một mình, sự quan tâm của hai chị em giúp bà bớt cô đơn. c) Đúng: nhờ hai chị em, bà được nhìn thấy con trai, vui đến rơi nước mắt. d) Sai: bà nói mình “học không nổi”, nhưng đến ngày thứ năm bà đã tự gọi được.", lv: 3, p: "ba-cu-nam" },
      { topic: "Từ đơn và từ phức", type: "mc", q: "Trong các từ sau, từ nào là từ láy?", o: ["róc rách", "sông núi", "bàn ghế", "cây cỏ"], x: "“Róc rách” có hai tiếng giống nhau ở âm đầu “r”, gợi tả tiếng nước chảy: từ láy. “Sông núi”, “bàn ghế”, “cây cỏ” là từ ghép.", lv: 1 },
      { topic: "Từ đơn và từ phức", type: "tf", q: "Từ phức là từ có từ hai tiếng trở lên.", a: true, x: "Đúng. Từ phức có từ hai tiếng trở lên, gồm từ ghép và từ láy; từ đơn chỉ có một tiếng.", lv: 1 },
      { topic: "Từ đơn và từ phức", type: "mc", q: "Trong câu «Bọn trẻ nói cười ríu rít trên đường đến trường.», từ láy “ríu rít” gợi tả điều gì?", o: ["Tiếng nói cười vui vẻ, nối tiếp, rộn ràng", "Dáng đi chậm chạp, mệt mỏi của bọn trẻ", "Con đường đến trường vừa dài vừa xa", "Sự im lặng, buồn bã của cả nhóm bạn"], x: "“Ríu rít” gợi tả những tiếng nói, tiếng cười trong trẻo, nối tiếp nhau không dứt. Từ láy giúp người đọc như nghe thấy không khí vui vẻ, rộn ràng của bọn trẻ trên đường đến trường.", lv: 2 },
      { topic: "Nghĩa của từ", type: "mc", q: "Từ “nhường nhịn” trong câu «Hai chị em luôn nhường nhịn nhau.» được giải thích đúng nhất là:", o: ["Chịu phần thiệt về mình, để người khác được hơn", "Nói to, tranh cãi để giành phần hơn", "Giữ kín chuyện riêng, không cho ai biết", "Đi chậm lại để chờ người khác"], x: "“Nhường nhịn” là chịu phần thiệt, phần kém về mình, không tranh giành, để người khác được hơn. Hai chị em nhường nhịn nhau nên sống hoà thuận.", lv: 2 },
      { topic: "Nghĩa của từ", type: "mc", q: "Đọc câu: «Thấy bạn bị ngã, Minh vội chạy đến đỡ dậy, ân cần hỏi han.» Dựa vào các từ ngữ xung quanh, “ân cần” có nghĩa là:", o: ["Chu đáo, đầy quan tâm", "Vội vàng, hấp tấp", "Lạnh nhạt, hờ hững", "Nghiêm khắc, khó tính"], x: "Minh chạy đến đỡ bạn dậy và hỏi han: đó là cách cư xử đầy quan tâm. Dựa vào những từ ngữ xung quanh, ta đoán được “ân cần” là chu đáo, quan tâm đến người khác.", lv: 2 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Câu nào dưới đây có sử dụng biện pháp so sánh?", o: ["Đôi má bé đỏ hồng như quả táo chín.", "Em bé đang ngủ say trong nôi.", "Mẹ đi chợ về mua cho em quả cam.", "Cả lớp chăm chú nghe cô giảng bài."], x: "Câu “Đôi má bé đỏ hồng như quả táo chín.” đối chiếu đôi má của bé với quả táo chín (cùng đỏ hồng), có từ so sánh “như”. Các câu còn lại chỉ kể việc, không đối chiếu sự vật này với sự vật khác.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Đoạn văn «Trên cành, chim hót líu lo. Trên sông, thuyền nối đuôi nhau. Trên đồng, lúa trổ bông vàng.» lặp lại từ “Trên” ở đầu mỗi câu. Đây là biện pháp tu từ nào?", o: ["Điệp ngữ", "So sánh", "Nhân hoá", "Ẩn dụ"], x: "Từ “Trên” được lặp lại ở đầu ba câu để nhấn mạnh và tạo nhịp, giúp người đọc thấy cảnh vật tươi vui ở khắp nơi: đó là điệp ngữ.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "tf", q: "Câu «Cây bàng già khoác lên mình tấm áo mới xanh non.» dùng biện pháp nhân hoá.", a: true, x: "Đúng. Cây bàng được tả bằng hoạt động của người (khoác lên mình tấm áo mới): đó là nhân hoá, gợi hình ảnh cây bàng ra lá non như người khoác áo mới.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Trong câu «Mỗi sáng, những búp măng non tung tăng đến trường.», “búp măng non” được dùng để chỉ các em học sinh nhỏ. Cách gọi ấy có tác dụng gì?", o: ["Gợi các em nhỏ tươi non, tràn đầy sức sống", "Cho biết các em học sinh rất thích ăn măng", "Cho biết ngôi trường nằm ở gần một rừng tre", "Kể lại thứ tự các em lần lượt đến trường"], x: "Gọi các em nhỏ là “búp măng non” là ẩn dụ, dựa trên nét tương đồng: măng non mới nhú, tươi non, lớn nhanh. Cách gọi ấy gợi hình ảnh các em tươi tắn, tràn đầy sức sống, đang lớn lên, làm câu văn giàu hình ảnh và tình cảm hơn.", lv: 2 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "mc", q: "Cụm từ nào dưới đây là cụm tính từ?", o: ["rất chăm chỉ", "đang chạy nhảy", "những quyển sách", "sẽ đi tham quan"], x: "“Rất chăm chỉ” có tính từ “chăm chỉ” làm trung tâm: cụm tính từ. “Đang chạy nhảy”, “sẽ đi tham quan” là cụm động từ; “những quyển sách” là cụm danh từ.", lv: 1 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "tf", q: "“đang say sưa đọc truyện” là cụm danh từ.", a: false, x: "Sai. Trung tâm của cụm là động từ “đọc”; “đang”, “say sưa”, “truyện” bổ sung ý cho “đọc”. Đây là cụm động từ.", lv: 1 },
      { topic: "Dấu câu", type: "mc", q: "Trong đoạn thơ «Tối qua, bé hỏi bố: / “Đom đóm thắp đèn chi?” / Bố cười, chỉ ra ngõ: / “Soi lối cho con đi.”», lời nói trực tiếp của bé và của bố được đánh dấu bằng dấu câu nào?", o: ["Dấu ngoặc kép", "Dấu ngoặc đơn", "Dấu chấm phẩy", "Dấu chấm lửng"], x: "Lời của bé và lời của bố là lời nói trực tiếp của nhân vật: đặt sau dấu hai chấm và được đánh dấu bằng dấu ngoặc kép, như các lời nói trực tiếp trong bài thơ «Mây và sóng».", lv: 2 },
      { topic: "Viết", type: "essay", q: "Viết đoạn văn (khoảng 150–200 chữ) kể lại một lần bạn được người khác giúp đỡ khi gặp khó khăn (ví dụ: khi bị ốm, khi bị lạc, khi gặp bài khó…).", rubric: [{ c: "Câu mở đoạn giới thiệu được trải nghiệm: chuyện gì, xảy ra khi nào, ai đã giúp bạn", p: 0.5 }, { c: "Kể các sự việc chính theo trình tự hợp lí, có chi tiết cụ thể (lời nói, việc làm của người giúp đỡ)", p: 1.5 }, { c: "Người kể xưng “tôi” hoặc “em”, kể chuyện của chính mình; nêu được cảm xúc của bạn khi được giúp đỡ", p: 1 }, { c: "Câu kết nêu điều bạn rút ra hoặc mong muốn của bạn sau trải nghiệm", p: 0.5 }, { c: "Đúng hình thức đoạn văn (khoảng 150–200 chữ); dùng từ đúng, viết đúng chính tả", p: 0.5 }], x: "Đoạn văn cần: câu mở đoạn giới thiệu trải nghiệm; các câu tiếp theo kể lần lượt các sự việc, có lời nói, việc làm cụ thể của người giúp đỡ; câu kết nêu cảm xúc và điều rút ra.\nĐoạn văn tham khảo:\nHồi lớp 5, em bị sốt phải nghỉ học gần hai tuần, và em không bao giờ quên sự giúp đỡ của Mai, cô bạn ngồi cùng bàn. Những ngày nằm nhà, em lo lắm vì sắp thi giữa kì mà mình bỏ lỡ bao nhiêu bài. Chiều nào, Mai cũng ghé qua, mang theo cuốn vở ghi chép cẩn thận để em chép lại. Có hôm trời mưa, Mai vẫn đội áo mưa sang, tóc ướt lấm tấm. Bài nào em chưa hiểu, Mai lại giảng lại thật chậm. Mai còn mang đến mấy tấm thiệp các bạn trong lớp viết lời chúc em mau khỏi bệnh. Cầm những tấm thiệp, em thấy sống mũi cay cay. Khi đi học lại, em theo kịp các bạn và làm bài thi khá tốt. Em nắm tay Mai, nói lời cảm ơn mà vẫn thấy chưa đủ. Trải nghiệm ấy giúp em hiểu rằng một người bạn tốt là người ở bên mình những lúc khó khăn nhất, và em cũng muốn trở thành một người bạn như thế.", lv: 3 }
    ]
  },

  /* ---------- Ngữ văn 6 · Đề ngẫu nhiên giữa học kì I: câu riêng của ngân hàng (Phiên N24b) ----------
     Kho câu của đề ngẫu nhiên = 25 câu dưới đây + 50 câu của hai đề cố định ở trên (mọi câu có lv). Ma trận trong
     data/banks/index.js: mỗi lần rút 25 câu, 10 Biết, 8 Hiểu, 7 Vận dụng: mỗi bài (Bài 1–3) một đoạn đọc 4 câu, 12 câu Tiếng Việt,
     1 câu Viết (đoạn văn tự chấm).
     Đọc hiểu: thêm một văn bản tự soạn cho mỗi bài (truyện đồng thoại kể theo ngôi thứ nhất; thơ năm chữ có yếu tố tự sự và miêu tả;
     truyện kể theo ngôi thứ ba), 4 câu mức 1-2-3-3, để "Làm đề khác" ra đoạn khác. Tiếng Việt: thêm câu cho mọi ô.
     Viết: 3 câu đoạn văn khoảng 150–200 chữ (cảm xúc về bài thơ ở phần đọc hiểu, có p nên tự đủ; kể lại một trải nghiệm trong những
     ngày đầu vào lớp 6; kể lại một lần mắc lỗi với người thân và biết nhận lỗi), thang tự chấm 4 điểm, đoạn văn tham khảo. Câu tự
     soạn. */
  "van6-gk1-ngau-nhien": {
    note: "Giữa học kì I (Bài 1–3), sách Kết nối tri thức. Mỗi đề có 10 câu mức Biết, 8 câu mức Hiểu, 7 câu mức Vận dụng, trong đó có một câu Viết đoạn văn tự chấm theo gợi ý. Đoạn văn, bài thơ tự soạn. Có lời giải từng câu.",
    passages: {
      "cun-vang": {
        title: "Cún Vàng làm quen",
        text: "Tôi là Cún Vàng, sống ở nhà bác Tư đã được hai năm. Một sáng, bác Tư ôm về một chú mèo con lông đen tuyền, đặt tên là Mun. Vừa thấy tôi, Mun đã dựng hết lông lên, chui tọt vào gầm tủ.\nTôi muốn làm bạn với Mun lắm. Tôi chạy đến bên gầm tủ, sủa thật to:\n– Gâu! Gâu! Ra đây chơi với tớ đi!\nMun càng nép sát vào góc tối, đôi mắt tròn xoe nhìn tôi sợ hãi.\nChị Gà Mái đứng ngoài sân thấy vậy, cục tác bảo tôi:\n– Em sủa ầm lên thế, bạn ấy sợ là phải. Muốn làm bạn thì phải từ từ thôi. Em cứ lặng lẽ nằm gần đó, để bạn ấy quen dần với em đã.\nTôi làm theo lời chị. Ngày đầu, tôi nằm ở góc nhà, lim dim như đang ngủ. Mấy hôm sau, tôi dịch lại gần hơn, đẩy chiếc khăn bông mềm của mình về phía gầm tủ. Đến ngày thứ năm, Mun rón rén bước ra, khẽ hít hít cái mũi ướt của tôi.\nBây giờ, chiều nào chúng tôi cũng nằm sưởi nắng bên nhau. Mun còn hay rúc vào bộ lông vàng của tôi mà ngủ. Nhìn bạn ngủ ngon lành, tôi lại nhớ lời chị Gà Mái: tình bạn cần được vun đắp từng chút một bằng sự kiên nhẫn."
      },
      "be-tap-di": {
        title: "Bé Bông tập đi",
        text: "Nhà có bé Bông nhỏ,\nMới tròn một tuổi thôi.\nBé vịn vào thành ghế,\nLẫm chẫm tập đi rồi.\n\nAnh ngồi ở cuối phòng,\nDang tay gọi: “Bông ơi!”\nBé chập chững từng bước,\nLạch bạch như vịt con.\n\nĐược ba bước thì ngã,\nBé mếu máo, rưng rưng.\nAnh chạy tới đỡ dậy,\nThổi phù đầu gối hồng.\n\nBé lại đứng lên đi,\nMột bước rồi hai bước.\nĐôi bàn chân bé xíu\nCứ dò dẫm về trước.\n\nRồi bé ôm chầm anh,\nCười khanh khách vang nhà.\nMẹ đứng nhìn hai đứa,\nMắt mẹ cười hiền hoà.\n\nAnh thầm mong bé lớn,\nMai bé đi học rồi,\nAnh sẽ là người bạn\nNắm tay bé suốt đời."
      },
      "tang-mot": {
        title: "Lớp học tầng một",
        text: "Đôi chân của Lâm yếu từ nhỏ, cậu phải đi lại bằng xe lăn. Năm nay lên lớp 6, lớp của Lâm lại học ở tầng ba. Sáng nào, mẹ Lâm cũng cõng con lên từng bậc cầu thang, mồ hôi ướt đẫm lưng áo.\nMột buổi sáng, lớp trưởng Hằng thấy mẹ Lâm dừng lại thở dốc ở chiếu nghỉ. Giờ sinh hoạt lớp hôm ấy, Hằng đứng lên:\n– Thưa cô, chúng em muốn xin nhà trường cho lớp mình chuyển xuống phòng học ở tầng một, để bạn Lâm đi lại dễ hơn ạ.\nCả lớp đồng thanh: “Chúng em đồng ý!” Cô chủ nhiệm mỉm cười gật đầu. Các bạn cùng nhau viết một lá đơn, ai cũng kí tên. Ba hôm sau, nhà trường đồng ý. Phòng học mới nhỏ hơn, lại gần nhà xe nên giờ ra chơi hơi ồn, nhưng chẳng ai phàn nàn.\nTừ đó, mỗi ngày có hai bạn thay nhau đẩy xe cho Lâm ra sân tập thể dục, ra thư viện. Lâm học giỏi Toán, cậu xin cô mở một “góc hỏi bài” cuối mỗi giờ ra chơi. Bạn nào chưa hiểu bài lại đến bên bàn Lâm, cùng nhau giải.\nCuối học kì, lớp được nhà trường khen là “Tập thể đoàn kết”. Lâm cười, đôi mắt sáng lên:\n– Tớ cảm ơn các cậu. Ở lớp mình, tớ chưa bao giờ thấy mình khác các bạn."
      }
    },
    questions: [
      { topic: "Tôi và các bạn", type: "mc", q: "Khi vừa thấy Cún Vàng, Mun đã làm gì?", o: ["Dựng hết lông lên, chui tọt vào gầm tủ", "Chạy lại hít hít cái mũi ướt của Cún", "Nhảy lên bàn kêu meo meo đòi ăn", "Nằm sưởi nắng ngoài hiên cùng Cún"], x: "Văn bản viết: “Vừa thấy tôi, Mun đã dựng hết lông lên, chui tọt vào gầm tủ.” Phải đến ngày thứ năm, Mun mới rón rén bước ra làm quen với Cún.", lv: 1, p: "cun-vang" },
      { topic: "Tôi và các bạn", type: "mc", q: "Trong truyện đồng thoại, nhân vật loài vật vừa giữ đặc điểm của loài, vừa có suy nghĩ, tình cảm như người. Chi tiết nào cho thấy rõ cả hai điều đó ở Cún Vàng?", o: ["Cún sủa “Gâu! Gâu!” rồi rủ “Ra đây chơi với tớ đi!”", "Cún sống ở nhà bác Tư đã được hai năm", "Cún có bộ lông vàng để Mun rúc vào ngủ", "Cún được bác Tư nuôi cùng một chú mèo con"], x: "“Gâu! Gâu!” là tiếng sủa của loài chó; còn lời rủ “Ra đây chơi với tớ đi!” cho thấy Cún biết nói, mong có bạn như con người. Các chi tiết còn lại chỉ kể nơi ở, bộ lông của Cún hoặc việc bác Tư nuôi thêm mèo.", lv: 2, p: "cun-vang" },
      { topic: "Tôi và các bạn", type: "mc", q: "Bài học của Cún Vàng gần với điều mà văn bản «Nếu cậu muốn có một người bạn» (trích «Hoàng tử bé» của Ê-xu-pe-ri) muốn nói. Đó là điều gì?", o: ["Muốn có tình bạn thật sự cần kiên nhẫn, dành thời gian cho nhau", "Bạn bè càng đông thì càng vui, không cần chọn bạn", "Chỉ nên kết bạn với những ai có sở thích giống hệt mình", "Muốn có bạn thì phải tặng cho bạn thật nhiều quà đẹp"], x: "Trong «Nếu cậu muốn có một người bạn», con cáo nói với hoàng tử bé rằng muốn có bạn thì phải rất kiên nhẫn, phải dành thời gian cho nhau. Cún Vàng cũng chỉ làm bạn được với Mun khi biết kiên nhẫn, làm quen từng chút một.", lv: 3, p: "cun-vang" },
      { topic: "Tôi và các bạn", type: "tf4", q: "Từ câu chuyện của Cún Vàng, mỗi ý sau đúng hay sai?", o: ["Muốn làm bạn với ai, cần để ý xem bạn ấy đang sợ hay ngại điều gì.", "Cứ ồn ào, nhiệt tình thật nhiều thì ai cũng muốn chơi với mình.", "Bạn nào nhút nhát thì không nên làm quen.", "Biết nghe lời khuyên đúng của người khác giúp mình cư xử tốt hơn."], a: [true, false, false, true], x: "a) Đúng: Mun sợ tiếng sủa ầm ĩ; Cún phải nhẹ nhàng, từ từ thì Mun mới dám ra. b) Sai: Cún sủa thật to, Mun càng sợ, nép sát vào góc tối. c) Sai: Mun nhút nhát nhưng nay đã thành bạn thân của Cún. d) Đúng: nghe lời chị Gà Mái, Cún đã làm bạn được với Mun.", lv: 3, p: "cun-vang" },
      { topic: "Gõ cửa trái tim", type: "mc", q: "Theo bài thơ «Bé Bông tập đi», khi bé Bông bị ngã, người anh đã làm gì?", o: ["Chạy tới đỡ bé dậy, thổi phù vào đầu gối bé", "Gọi mẹ ra bế bé đi chỗ khác chơi", "Ngồi yên một chỗ, bảo bé tự đứng dậy", "Bật cười thật to vì thấy bé ngã oạch"], x: "Khổ thơ thứ ba kể: “Anh chạy tới đỡ dậy, / Thổi phù đầu gối hồng.”", lv: 1, p: "be-tap-di" },
      { topic: "Gõ cửa trái tim", type: "mc", q: "Dòng thơ «Lạch bạch như vịt con» dùng biện pháp tu từ nào và giúp người đọc hình dung điều gì?", o: ["So sánh; dáng đi chập chững, đáng yêu của bé", "Nhân hoá; chú vịt con biết đi như người", "Điệp ngữ; tiếng kêu của đàn vịt con", "Ẩn dụ; bé Bông được gọi tên là vịt con"], x: "Dòng thơ đối chiếu dáng đi của bé với dáng đi của vịt con, có từ so sánh “như”: đó là biện pháp so sánh. Từ láy “lạch bạch” cùng hình ảnh vịt con giúp ta hình dung bé đi chưa vững, lắc lư, rất ngộ nghĩnh, đáng yêu.", lv: 2, p: "be-tap-di" },
      { topic: "Gõ cửa trái tim", type: "mc", q: "Khổ thơ cuối cho thấy tình cảm của người anh dành cho em. Việc làm nào của bạn ở nhà thể hiện tình cảm giống như vậy với em nhỏ?", o: ["Kiên nhẫn chỉ em tập viết, chơi cùng em khi bố mẹ bận", "Giành lấy những món đồ chơi đẹp nhất về phần mình", "Mắng em thật to mỗi khi em lỡ làm đổ đồ", "Mặc kệ em, chỉ lo chơi và làm việc riêng của mình"], x: "Người anh mong em lớn, hứa sẽ làm người bạn “Nắm tay bé suốt đời”: đó là tình thương, sự che chở của anh chị với em nhỏ. Ở nhà, ta thể hiện tình cảm ấy bằng việc làm cụ thể: kiên nhẫn chỉ bảo em, chơi cùng em, nhường nhịn em.", lv: 3, p: "be-tap-di" },
      { topic: "Gõ cửa trái tim", type: "order", q: "Bạn viết đoạn văn ghi lại cảm xúc về bài thơ «Bé Bông tập đi», các ý ở thân đoạn đi theo trình tự của bài thơ. Sắp xếp các ý theo đúng thứ tự.", o: ["Giới thiệu bài thơ và cảm xúc chung của bạn", "Cảm xúc về hình ảnh bé vịn ghế, lẫm chẫm tập đi", "Cảm xúc về lúc bé ngã, được anh đỡ dậy rồi lại đi tiếp", "Cảm xúc về mong ước của người anh ở khổ thơ cuối", "Khẳng định lại cảm xúc, nêu điều bài thơ gợi cho bạn"], x: "Đoạn văn mở bằng câu giới thiệu bài thơ và cảm xúc chung; các câu tiếp theo nêu cảm xúc về từng hình ảnh, chi tiết theo trình tự bài thơ (bé tập đi, bé ngã và được anh đỡ dậy, mong ước của người anh ở khổ cuối); câu kết khẳng định lại cảm xúc.", lv: 3, p: "be-tap-di" },
      { topic: "Viết", type: "essay", q: "Viết đoạn văn (khoảng 150–200 chữ) ghi lại cảm xúc của bạn về bài thơ «Bé Bông tập đi».", rubric: [{ c: "Câu mở đoạn nêu được tên bài thơ và cảm xúc chung của bạn", p: 0.5 }, { c: "Nêu cảm xúc về câu chuyện được kể trong bài thơ (bé tập đi, bị ngã rồi lại đứng lên) và tình cảm anh em", p: 1 }, { c: "Nêu cảm xúc về ít nhất hai hình ảnh, từ ngữ hay trong bài (dáng đi của bé, tiếng cười của bé, ánh mắt của mẹ…), có dẫn câu thơ", p: 1.5 }, { c: "Câu kết khẳng định lại cảm xúc hoặc nêu điều bài thơ gợi cho bạn", p: 0.5 }, { c: "Đúng hình thức đoạn văn (khoảng 150–200 chữ); dùng từ đúng, viết đúng chính tả", p: 0.5 }], x: "Đoạn văn cần: câu mở đoạn giới thiệu bài thơ và cảm xúc chung; các câu tiếp theo nêu cảm xúc về câu chuyện trong bài thơ và về những hình ảnh, câu thơ hay (dẫn câu thơ); câu kết khẳng định lại cảm xúc.\nĐoạn văn tham khảo:\nBài thơ «Bé Bông tập đi» mang đến cho em một cảm giác thật trong trẻo và ấm áp. Bài thơ kể lại những bước đi đầu tiên của bé Bông mới tròn một tuổi. Em bật cười khi hình dung bé vịn ghế “lẫm chẫm”, rồi “lạch bạch” bước về phía anh. Đến khi bé ngã, “mếu máo, rưng rưng”, em cũng thấy thương bé như thương em gái mình. Em cảm động vì người anh lúc nào cũng ở bên, dang tay gọi em, nâng em dậy để em lại tự tin bước tiếp. Tiếng cười “khanh khách vang nhà” của bé và đôi mắt mẹ “cười hiền hoà” làm cả bài thơ sáng bừng niềm vui. Em thích nhất mong ước của người anh: được làm người bạn “Nắm tay bé suốt đời”. Đọc bài thơ, em càng thấy quý những phút giây bên em nhỏ ở nhà và tự nhủ sẽ luôn yêu thương em mình.", lv: 3, p: "be-tap-di" },
      { topic: "Yêu thương và chia sẻ", type: "fill", q: "Theo văn bản, cuối học kì, lớp của Lâm được nhà trường khen là “Tập thể ___”.", ans: ["đoàn kết"], x: "Đoạn cuối văn bản kể: lớp được nhà trường khen là “Tập thể đoàn kết”, vì cả lớp đã cùng nhau giúp đỡ Lâm.", lv: 1, p: "tang-mot" },
      { topic: "Yêu thương và chia sẻ", type: "mc", q: "Văn bản «Lớp học tầng một» được kể theo ngôi thứ mấy? Dựa vào đâu?", o: ["Ngôi thứ ba: người kể giấu mình, gọi nhân vật bằng tên như Lâm, Hằng", "Ngôi thứ nhất: Lâm xưng “tôi”, kể lại chuyện của chính mình", "Ngôi thứ nhất: Hằng xưng “tôi”, kể lại chuyện của cả lớp", "Ngôi thứ nhất: cô chủ nhiệm xưng “tôi”, kể về học trò của mình"], x: "Người kể không xưng “tôi”, đứng ngoài câu chuyện và gọi các nhân vật bằng tên (Lâm, Hằng, mẹ Lâm, cô chủ nhiệm): truyện được kể theo ngôi thứ ba. Lâm, Hằng chỉ xưng “tớ”, “chúng em” trong lời của nhân vật.", lv: 2, p: "tang-mot" },
      { topic: "Yêu thương và chia sẻ", type: "mc", q: "Câu chuyện về lớp của Lâm và truyện «Gió lạnh đầu mùa» (Thạch Lam) giống nhau ở điểm nào?", o: ["Đều ca ngợi tấm lòng biết nghĩ đến người khó khăn, sẵn lòng giúp đỡ", "Đều kể về một em bé nghèo đi bán diêm trong đêm giao thừa giá rét", "Đều kể chuyện một gia đình chuyển đến sống ở một làng quê mới", "Đều kết thúc bằng cảnh các nhân vật phải chia tay nhau mãi mãi"], x: "Trong «Gió lạnh đầu mùa», chị em Sơn, Lan đem chiếc áo bông cũ cho bé Hiên nghèo đang rét. Lớp của Lâm cùng nhau xin đổi phòng học, thay nhau đẩy xe cho bạn. Hai câu chuyện cùng ca ngợi tấm lòng biết nghĩ đến người gặp khó khăn, sẵn lòng giúp đỡ. Em bé bán diêm trong đêm giao thừa là nhân vật của truyện «Cô bé bán diêm».", lv: 3, p: "tang-mot" },
      { topic: "Yêu thương và chia sẻ", type: "mc", q: "Một bạn nói: «Lớp chuyển xuống tầng một thì phòng nhỏ, lại ồn, các bạn chịu thiệt quá.» Câu trả lời nào phù hợp nhất với tinh thần của câu chuyện?", o: ["Chịu chút bất tiện để bạn được đi học dễ dàng là điều đáng làm.", "Đúng vậy, cả lớp không nên đổi phòng chỉ vì một bạn.", "Lâm nên tự xin chuyển sang học ở một trường khác cho xong.", "Cả lớp nên xin một phòng học khác, to hơn, ở tầng ba."], x: "Các bạn lớp Lâm biết phòng mới nhỏ, ồn “nhưng chẳng ai phàn nàn”, vì ai cũng nghĩ đến bạn mình trước. Sống vì nhau đôi khi là chấp nhận một chút thiệt thòi để người khác bớt khó khăn.", lv: 3, p: "tang-mot" },
      { topic: "Từ đơn và từ phức", type: "mc", q: "Từ láy nào dưới đây gợi tả âm thanh?", o: ["lách cách", "xinh xắn", "nhỏ nhắn", "lấp lánh"], x: "“Lách cách” mô phỏng tiếng các vật cứng va vào nhau: từ láy gợi tả âm thanh. “Xinh xắn”, “nhỏ nhắn” gợi tả dáng vẻ; “lấp lánh” gợi tả ánh sáng.", lv: 1 },
      { topic: "Từ đơn và từ phức", type: "mc", q: "Vì sao “tươi tốt” là từ ghép chứ không phải từ láy?", o: ["Vì “tươi”, “tốt” đều có nghĩa và ghép với nhau về nghĩa", "Vì hai tiếng “tươi”, “tốt” có cùng âm đầu “t”", "Vì từ này có hai tiếng, mà từ hai tiếng đều là từ ghép", "Vì từ này thường được dùng để tả cây cối"], x: "“Tươi” và “tốt” đều có nghĩa riêng; ghép lại, “tươi tốt” chỉ cây cối xanh tươi, phát triển tốt. Hai tiếng giống nhau ở âm đầu chỉ là tình cờ, không phải láy âm: “tươi tốt” là từ ghép.", lv: 2 },
      { topic: "Nghĩa của từ", type: "mc", q: "Trong từ “nhân hậu”, yếu tố “nhân” có nghĩa là “lòng thương người”. Từ nào dưới đây có yếu tố “nhân” cũng mang nghĩa ấy?", o: ["nhân ái", "nhân dân", "nhân tạo", "nguyên nhân"], x: "“Nhân ái” là lòng yêu thương con người: “nhân” mang nghĩa “lòng thương người”. Trong “nhân dân”, “nhân tạo”, “nhân” nghĩa là người; trong “nguyên nhân”, “nhân” nghĩa là cái gây ra một việc.", lv: 2 },
      { topic: "Nghĩa của từ", type: "mc", q: "Từ “rụt rè” trong câu «Ngày đầu đến lớp, Na rụt rè, chẳng dám bắt chuyện với ai.» có nghĩa là:", o: ["Thiếu mạnh dạn, e ngại khi giao tiếp", "Mạnh dạn, tự tin trước mọi người", "Hay cáu gắt, khó gần", "Tò mò, thích khám phá điều mới"], x: "“Rụt rè” là thiếu mạnh dạn, e ngại, không dám nói hay làm điều gì. Chi tiết “chẳng dám bắt chuyện với ai” giúp ta hiểu nghĩa của từ.", lv: 2 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Trong câu «Bác xe lu ì ạch lăn qua lăn lại trên mặt đường mới.», từ nào cho thấy xe lu được nhân hoá?", o: ["Bác", "lăn", "mặt đường", "mới"], x: "Xe lu được gọi bằng “bác”, từ vốn dùng để gọi người: đó là nhân hoá, làm cho chiếc xe lu trở nên gần gũi như một người lao động cần mẫn.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Câu nào dưới đây dùng biện pháp ẩn dụ?", o: ["Ngoài vườn, những chiếc đèn lồng đỏ treo đầy cành vải.", "Những chùm vải chín đỏ như những chiếc đèn lồng nhỏ.", "Cây vải trĩu quả, đung đưa cành lá vẫy chào khách.", "Vải chín rồi, vải chín đỏ cả một góc vườn rồi."], x: "Câu “Ngoài vườn, những chiếc đèn lồng đỏ treo đầy cành vải.” gọi những chùm vải chín là “đèn lồng đỏ” (giống nhau ở màu đỏ, treo lủng lẳng) mà không nêu tên quả vải: đó là ẩn dụ. Câu có “như” là so sánh; câu “đung đưa cành lá vẫy chào khách” là nhân hoá; câu lặp lại “vải chín” là điệp ngữ.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Câu «Tiếng chim hót trong trẻo như tiếng sáo.» giúp người đọc cảm nhận điều gì về tiếng chim?", o: ["Tiếng chim trong, vang, ngân nga, nghe rất hay", "Con chim đang bay đi rất xa", "Con chim thuộc một loài chim quý hiếm", "Tiếng chim to, chói tai, khó chịu"], x: "Câu văn dùng biện pháp so sánh: đối chiếu tiếng chim với tiếng sáo quen thuộc, giúp người đọc như nghe thấy tiếng chim trong trẻo, ngân vang; câu văn giàu hình ảnh, âm thanh và gợi cảm hơn.", lv: 2 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "mc", q: "Cụm từ nào dưới đây KHÔNG phải là cụm danh từ?", o: ["đang nấu cơm", "những ngôi sao", "một chiếc áo len", "cả khu vườn"], x: "“Đang nấu cơm” có động từ “nấu” làm trung tâm: cụm động từ. “Những ngôi sao”, “một chiếc áo len”, “cả khu vườn” đều có danh từ làm trung tâm: cụm danh từ.", lv: 1 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "mc", q: "Trong cụm động từ “đang tập đàn trong phòng”, động từ trung tâm là:", o: ["tập", "đang", "đàn", "trong phòng"], x: "Động từ “tập” làm trung tâm; “đang” đứng trước chỉ thời gian; “đàn” cho biết tập cái gì, “trong phòng” cho biết tập ở đâu.", lv: 1 },
      { topic: "Dấu câu", type: "mc", q: "Dấu hai chấm trong câu sau dùng để làm gì? Cô giáo dặn cả lớp: “Ngày mai các em nhớ mang theo áo mưa nhé!”", o: ["Báo hiệu phía sau là lời nói trực tiếp", "Báo hiệu câu đã kết thúc", "Ngăn cách các từ cùng loại trong câu", "Đánh dấu tên riêng của người"], x: "Sau dấu hai chấm là nguyên văn lời cô giáo dặn (đặt trong dấu ngoặc kép): dấu hai chấm báo hiệu phía sau là lời nói trực tiếp.", lv: 2 },
      { topic: "Viết", type: "essay", q: "Viết đoạn văn (khoảng 150–200 chữ) kể lại một trải nghiệm đáng nhớ của bạn trong những ngày đầu vào lớp 6.", rubric: [{ c: "Câu mở đoạn giới thiệu được trải nghiệm: chuyện gì, xảy ra khi nào, ở đâu", p: 0.5 }, { c: "Kể các sự việc chính theo trình tự hợp lí, có chi tiết cụ thể (lời nói, việc làm của bạn và những người liên quan)", p: 1.5 }, { c: "Người kể xưng “tôi” hoặc “em”, kể chuyện của chính mình; nêu được cảm xúc của bạn trong trải nghiệm", p: 1 }, { c: "Câu kết nêu điều bạn rút ra hoặc ý nghĩa của trải nghiệm", p: 0.5 }, { c: "Đúng hình thức đoạn văn (khoảng 150–200 chữ); dùng từ đúng, viết đúng chính tả", p: 0.5 }], x: "Đoạn văn cần: câu mở đoạn giới thiệu trải nghiệm; các câu tiếp theo kể lần lượt các sự việc, có lời nói, việc làm cụ thể; câu kết nêu cảm xúc và điều rút ra.\nĐoạn văn tham khảo:\nNgày đầu tiên bước vào trường trung học cơ sở là một trải nghiệm em nhớ mãi. Sáng hôm ấy, em dậy thật sớm, mặc bộ đồng phục mới tinh, lòng vừa háo hức vừa hồi hộp. Ngôi trường mới rộng gấp mấy lần trường tiểu học cũ, các dãy nhà trông giống nhau đến mức em đi lạc, không tìm thấy lớp 6A của mình. Đứng giữa sân, em lúng túng muốn khóc. Đúng lúc ấy, một bạn nữ tóc buộc đuôi gà chạy lại hỏi: “Cậu tìm lớp nào thế? Tớ cũng học 6A này!” Bạn ấy tên là Thảo. Thảo nắm tay em, dẫn lên tầng hai, còn giới thiệu em với mấy bạn ngồi bàn trên. Cả buổi học hôm ấy, em không còn thấy bỡ ngỡ nữa. Từ đó, Thảo trở thành người bạn thân đầu tiên của em ở trường mới. Mỗi lần đi qua góc sân hôm ấy, em lại mỉm cười. Trải nghiệm ấy cho em hiểu rằng một cử chỉ thân thiện đúng lúc có thể giúp người khác bớt lo lắng, và em cũng muốn làm điều đó cho các bạn mới.", lv: 3 },
      { topic: "Viết", type: "essay", q: "Viết đoạn văn (khoảng 150–200 chữ) kể lại một lần bạn mắc lỗi với người thân trong gia đình và đã biết nhận lỗi.", rubric: [{ c: "Câu mở đoạn giới thiệu được trải nghiệm: lỗi gì, với ai, xảy ra khi nào", p: 0.5 }, { c: "Kể các sự việc chính theo trình tự hợp lí: chuyện xảy ra, bạn đã nghĩ gì, đã nhận lỗi thế nào, người thân đáp lại ra sao", p: 1.5 }, { c: "Người kể xưng “tôi” hoặc “em”, kể chuyện của chính mình; nêu được cảm xúc của bạn (lo lắng, xấu hổ, nhẹ nhõm…)", p: 1 }, { c: "Câu kết nêu bài học bạn rút ra", p: 0.5 }, { c: "Đúng hình thức đoạn văn (khoảng 150–200 chữ); dùng từ đúng, viết đúng chính tả", p: 0.5 }], x: "Đoạn văn cần: câu mở đoạn giới thiệu trải nghiệm; các câu tiếp theo kể lần lượt chuyện đã xảy ra, suy nghĩ của bạn, lúc bạn nhận lỗi và người thân đáp lại; câu kết nêu bài học.\nĐoạn văn tham khảo:\nEm vẫn nhớ mãi lần làm vỡ cặp kính của ông nội hồi hè năm ngoái. Hôm ấy, ông đi vắng, em tò mò đeo thử cặp kính để trên bàn rồi chạy ra sân làm trò. Không may, cặp kính rơi xuống nền gạch, một bên mắt kính vỡ toác. Em sợ quá, vội nhặt lên, giấu vào ngăn kéo. Tối đến, ông lục tìm mãi không thấy kính để đọc báo. Nhìn ông nheo mắt, lần tay trên bàn, em thấy lòng rối bời. Cuối cùng, em lấy hết can đảm, mang cặp kính vỡ đến trước mặt ông, lí nhí: “Ông ơi, cháu xin lỗi ông. Cháu làm vỡ kính của ông rồi.” Em cứ nghĩ ông sẽ mắng, nhưng ông chỉ xoa đầu em, bảo: “Biết nhận lỗi là ngoan rồi. Mai hai ông cháu đi sửa kính nhé.” Em ôm chầm lấy ông, lòng nhẹ nhõm hẳn. Từ lần ấy, em hiểu rằng mắc lỗi thì phải dũng cảm nhận lỗi, vì giấu giếm chỉ khiến người thân thêm lo và lòng mình thêm nặng nề.", lv: 3 }
    ]
  },
  /* ---------- Ngữ văn 6 · Kiểm tra giữa học kì II (Kết nối tri thức, Bài 6–7) (Phiên N9) ----------
     Phạm vi như lịch gk2-l6: Bài 6 Chuyện kể về những người anh hùng (truyền thuyết «Thánh Gióng», «Sơn Tinh, Thuỷ Tinh»; văn bản
     thông tin «Ai ơi mồng 9 tháng 4», Anh Thư) và Bài 7 Thế giới cổ tích («Thạch Sanh», «Cây khế», «Vua chích choè»); phần Thực hành
     tiếng Việt của hai bài theo bản PDF Ngữ văn 6 tập hai (sách in năm 2026, mã G1HH6V002h26): nghĩa của từ ngữ (yếu tố Hán Việt
     «giả», «thuỷ», «gia»; suy đoán nghĩa từ ngữ cảnh; thành ngữ), từ ghép và từ láy, cụm động từ và cụm tính từ, biện pháp so sánh,
     điệp ngữ (tr. 9–10, 13, 30–31, 35); dấu chấm phẩy (tr. 5, 13). Tri thức ngữ văn: tr. 5 (truyền thuyết, văn bản thông tin thuật
     lại một sự kiện), tr. 25 (truyện cổ tích). Kiểu bài Viết: thuyết minh thuật lại một sự kiện (tr. 16), đóng vai nhân vật kể lại
     một truyện cổ tích (tr. 41–42; bài tham khảo của sách đóng vai Thạch Sanh, hội chợ xuân ở trường: đề không dùng lại).
     Hai đề cố định cùng các câu riêng của "van6-gk2-ngau-nhien" bên dưới là kho của đề ngẫu nhiên; đề nào cũng đúng ma trận của đề
     ngẫu nhiên (data/banks/index.js): 10 Biết, 8 Hiểu, 7 Vận dụng. Mỗi bài 7 câu đọc hiểu: một đoạn đọc ngoài sách viết ở passages
     (truyền thuyết, truyện cổ tích Việt Nam và thế giới kể lại bằng lời người soạn; văn bản thông tin thuật lại một hội làng tự viết),
     4 câu mức 1-2-3-3, câu nào cũng làm được khi chỉ rút riêng đoạn đó; và 3 câu lẻ mức 1-2-3 về đặc điểm thể loại, văn bản trong
     sách. 10 câu Tiếng Việt chỉ mức Biết, Hiểu (xếp mức như ghi ở đầu file: nhận ra từ láy, cụm từ, yếu tố Hán Việt, biện pháp tu từ
     là Biết; nghĩa của từ theo ngữ cảnh, thành ngữ, tác dụng của biện pháp tu từ, công dụng dấu chấm phẩy là Hiểu). 1 câu Viết tự
     chấm theo kiểu bài của Bài 6, 7. Câu tự soạn. */
  "van6-gk2-de1": {
    note: "Giữa học kì II (Bài 6–7), sách Kết nối tri thức. 10 câu mức Biết, 8 câu mức Hiểu, 7 câu mức Vận dụng: đọc hiểu một truyền thuyết và một truyện cổ tích kể lại ngoài sách, câu hỏi về thể loại và văn bản đã học, 10 câu tiếng Việt và một câu Viết tự chấm theo gợi ý. Có lời giải từng câu.",
    passages: {
      "ho-guom": {
        title: "Sự tích Hồ Gươm (truyền thuyết, kể lại)",
        text: "Thuở giặc Minh sang xâm chiếm nước ta, chúng tàn bạo vô cùng, khiến muôn dân lầm than. Ở đất Lam Sơn, Lê Lợi dựng cờ khởi nghĩa, nhưng buổi đầu lực lượng còn mỏng, nghĩa quân nhiều phen thất bại. Thấy vậy, đức Long Quân quyết định cho nghĩa quân mượn thanh gươm thần.\nBấy giờ ở vùng Thanh Hoá có người đánh cá tên là Lê Thận. Một đêm, Thận thả lưới ở khúc sông vắng, ba lần kéo lên đều chỉ được một thanh sắt. Nhìn kĩ dưới ánh lửa, Thận nhận ra đó là một lưỡi gươm, bèn đem về cất trong góc nhà. Ít lâu sau, Thận gia nhập nghĩa quân. Một hôm Lê Lợi ghé nhà Thận, lưỡi gươm trong góc tối bỗng sáng rực lên, để lộ hai chữ “Thuận Thiên”. Rồi một lần bị giặc đuổi, Lê Lợi chạy vào rừng, thấy trên ngọn cây đa có ánh sáng lạ. Ông trèo lên, lấy được một chiếc chuôi gươm nạm ngọc. Nhớ tới lưỡi gươm ở nhà Thận, ông đem chuôi tra vào thì vừa như in.\nTừ đó, gươm thần trong tay Lê Lợi tung hoành khắp các trận địa. Nghĩa quân càng đánh càng mạnh, giặc Minh thua chạy tan tác, đất nước sạch bóng quân thù.\nMột năm sau, Lê Lợi đã lên ngôi vua, cưỡi thuyền rồng dạo trên hồ Tả Vọng. Bỗng một con rùa vàng rất lớn nổi lên mặt nước, cất tiếng: “Xin bệ hạ hoàn gươm lại cho Long Quân!”. Nhà vua hiểu ý, nâng gươm hướng về phía rùa. Rùa há miệng đớp lấy thanh gươm rồi lặn xuống đáy hồ. Từ đấy, hồ Tả Vọng mang tên Hồ Gươm, còn gọi là hồ Hoàn Kiếm."
      },
      "cay-tre": {
        title: "Cây tre trăm đốt (truyện cổ tích, kể lại)",
        text: "Ngày xửa ngày xưa, có anh nông dân nghèo tên là Khoai đi ở cho một nhà phú ông. Anh hiền lành, thật thà, làm lụng quần quật từ sáng đến tối. Phú ông muốn lợi dụng sức anh nên dỗ ngọt: “Mày chịu khó làm cho tao ba năm, tao sẽ gả con gái cho.” Khoai tin lời, càng ra sức cày cuốc.\nHết ba năm, phú ông lại ngấm ngầm hứa gả con gái cho một nhà giàu trong làng. Sợ Khoai biết, lão bảo anh: “Mày vào rừng chặt cho tao một cây tre trăm đốt về làm đũa cưới, tao sẽ gả con cho.” Khoai vác dao vào rừng, tìm mãi mà chẳng cây tre nào đủ trăm đốt. Anh ngồi xuống gốc cây, ôm mặt khóc. Bỗng một ông lão râu tóc bạc phơ hiện ra, bảo anh cứ chặt đủ một trăm đốt tre, rồi dạy anh hai câu thần chú. Khoai hô: “Khắc nhập! Khắc nhập!”, trăm đốt tre liền dính vào nhau thành một cây dài. Anh hô: “Khắc xuất! Khắc xuất!”, cây tre lại rời ra từng đốt.\nKhoai gánh tre về thì nhà phú ông đang mở tiệc cưới linh đình. Hiểu ra mình bị lừa, anh đọc “Khắc nhập!”, trăm đốt tre dính liền thành cây. Phú ông tò mò chạy ra sờ, lập tức bị dính chặt vào cây tre; nhà trai xúm vào gỡ cũng dính luôn theo. Cả bọn khóc lóc van xin. Phú ông đành hứa gả con gái cho Khoai. Bấy giờ anh mới đọc “Khắc xuất!” cho mọi người rời ra. Từ đó, Khoai và cô con gái phú ông sống với nhau êm ấm, hạnh phúc."
      }
    },
    questions: [
      { topic: "Chuyện kể về những người anh hùng", type: "mc", q: "Theo văn bản, Lê Thận tìm thấy lưỡi gươm ở đâu?", o: ["Trong lưới đánh cá, khi thả lưới ở khúc sông vắng", "Trên ngọn cây đa trong rừng", "Trong kho vũ khí của nghĩa quân Lam Sơn", "Do rùa vàng mang đến tận nhà"], x: "Văn bản kể: Lê Thận thả lưới ở khúc sông vắng, ba lần kéo lên đều được một thanh sắt, nhìn kĩ thì ra là một lưỡi gươm. Chuôi gươm mới là thứ Lê Lợi tìm thấy trên ngọn cây đa.", lv: 1, p: "ho-guom" },
      { topic: "Chuyện kể về những người anh hùng", type: "mc", q: "Lưỡi gươm tìm thấy dưới sông, chuôi gươm tìm thấy trên rừng, vậy mà tra vào nhau lại “vừa như in”. Chi tiết ấy có ý nghĩa gì?", o: ["Nhân dân khắp nơi, miền sông nước và miền rừng núi, cùng đồng lòng góp sức cho cuộc khởi nghĩa", "Lê Thận là người thợ rèn khéo tay nên lưỡi và chuôi khớp nhau", "Lê Lợi đã mang chuôi gươm đi tìm lưỡi gươm từ nhiều năm trước", "Thanh gươm vốn là của giặc Minh đánh rơi khi tháo chạy"], x: "Lưỡi gươm từ người đánh cá ở miền sông nước, chuôi gươm từ rừng núi, hai bộ phận ở hai nơi hợp thành một thanh gươm hoàn chỉnh: tác giả dân gian muốn nói nhân dân khắp miền ngược, miền xuôi đều một lòng ủng hộ Lê Lợi đánh giặc. Văn bản không nói Thận là thợ rèn, cũng không nói gươm là của giặc.", lv: 2, p: "ho-guom" },
      { topic: "Chuyện kể về những người anh hùng", type: "tf4", q: "Dựa vào đặc điểm của truyền thuyết, mỗi nhận xét sau về văn bản «Sự tích Hồ Gươm» đúng hay sai?", o: ["Văn bản kể về nhân vật và sự kiện có liên quan đến lịch sử: Lê Lợi và cuộc khởi nghĩa chống giặc Minh.", "Lưỡi gươm tự sáng rực, rùa vàng nổi lên nói tiếng người là những yếu tố kì ảo.", "Truyện giải thích nguồn gốc tên gọi Hồ Gươm (hồ Hoàn Kiếm).", "Truyện được kể theo ngôi thứ nhất, người kể là Lê Thận."], a: [true, true, true, false], x: "a) Đúng: Lê Lợi, giặc Minh, khởi nghĩa Lam Sơn là nhân vật, sự kiện có thật trong lịch sử. b) Đúng: đó là những chi tiết lạ, không có thật, làm cho câu chuyện kì ảo. c) Đúng: đoạn cuối kể vì sao hồ Tả Vọng mang tên Hồ Gươm. d) Sai: người kể giấu mình, gọi nhân vật là “Thận”, “Lê Lợi”, “nhà vua”, tức là kể theo ngôi thứ ba.", lv: 3, p: "ho-guom" },
      { topic: "Chuyện kể về những người anh hùng", type: "mc", q: "Theo bạn, vì sao Long Quân chỉ cho mượn gươm, rồi khi đã thắng giặc lại sai rùa vàng đòi gươm về?", o: ["Gươm thần chỉ dùng để đánh giặc giữ nước; đất nước đã thanh bình thì trả gươm, thể hiện mong ước hoà bình của nhân dân", "Long Quân sợ nhà vua dùng gươm để đi xâm chiếm các nước láng giềng", "Rùa vàng muốn giữ thanh gươm làm của riêng dưới đáy hồ", "Thanh gươm đã cùn sau nhiều trận đánh, không còn dùng được nữa"], x: "Gươm được cho mượn khi nghĩa quân cần sức mạnh để đánh giặc. Giặc tan, đất nước yên bình, gươm không còn cần nữa nên được trả lại: nhân dân ta chỉ cầm gươm khi phải chống giặc, luôn mong sống trong hoà bình. Các ý còn lại không có căn cứ trong văn bản.", lv: 3, p: "ho-guom" },
      { topic: "Chuyện kể về những người anh hùng", type: "mc", q: "Theo Tri thức ngữ văn (Bài 6), truyền thuyết là loại truyện dân gian kể về:", o: ["Các sự kiện và nhân vật ít nhiều có liên quan đến lịch sử, thông qua sự tưởng tượng, hư cấu", "Cuộc đời của những loài vật, đồ vật được nhân hoá như con người", "Những chuyến đi có thật mà người viết tận mắt chứng kiến", "Những hiện tượng thời tiết được ghi chép chính xác từng ngày"], x: "Truyền thuyết kể về sự kiện và nhân vật ít nhiều liên quan đến lịch sử, qua tưởng tượng, hư cấu, như Thánh Gióng đánh giặc Ân, Sơn Tinh, Thuỷ Tinh thời Hùng Vương. Truyện về loài vật nhân hoá là truyện đồng thoại; ghi chép chuyến đi có thật là du kí.", lv: 1 },
      { topic: "Chuyện kể về những người anh hùng", type: "mc", q: "Trong truyện «Thánh Gióng», chi tiết bà con hàng xóm vui lòng gom góp gạo thóc nuôi chú bé có ý nghĩa gì?", o: ["Người anh hùng lớn lên nhờ sức mạnh và sự chung tay của cả cộng đồng", "Gia đình chú bé quá nghèo nên phải đi xin ăn khắp làng", "Dân làng góp gạo để được nhà vua ban thưởng", "Chú bé ăn khoẻ khác thường nên ai cũng sợ hãi"], x: "Chú bé ăn bao nhiêu cũng không no, cả làng cùng góp gạo nuôi: Gióng lớn lên bằng cơm gạo của nhân dân, sức mạnh của người anh hùng chính là sức mạnh của cả cộng đồng. Chi tiết không nói về nghèo đói, ban thưởng hay sợ hãi.", lv: 2 },
      { topic: "Chuyện kể về những người anh hùng", type: "tf4", q: "Mỗi nhận xét sau về văn bản «Ai ơi mồng 9 tháng 4» (Anh Thư) đúng hay sai?", o: ["Văn bản thuật lại lễ hội Gióng ở làng Phù Đổng theo trình tự thời gian, từ những ngày chuẩn bị đến ngày kết thúc hội.", "Văn bản có nhiều yếu tố kì ảo như ngựa sắt phun lửa, tráng sĩ bay về trời.", "Hội trận trong lễ hội mô phỏng lại cảnh Thánh Gióng đánh giặc.", "Đây là một truyền thuyết do tác giả Anh Thư sáng tác."], a: [true, false, true, false], x: "a) Đúng: bài viết kể lần lượt việc chuẩn bị, rồi mồng 6, mồng 8, mồng 9 (chính hội), mồng 10, 11, 12. b) Sai: ngựa sắt phun lửa, bay về trời là chi tiết của truyền thuyết «Thánh Gióng»; văn bản thông tin chỉ thuật lại những gì diễn ra thật trong lễ hội. c) Đúng: hội trận là hội tổ chức theo hình thức chiến trận để ca ngợi chiến công của Thánh Gióng. d) Sai: đây là văn bản thông tin thuật lại một sự kiện, không phải truyền thuyết.", lv: 3 },
      { topic: "Thế giới cổ tích", type: "mc", q: "Theo văn bản, lúc đầu phú ông hứa gả con gái cho Khoai với điều kiện gì?", o: ["Khoai phải chịu khó làm cho lão ba năm", "Khoai phải tìm được một cây tre trăm đốt", "Khoai phải học được câu thần chú của ông lão", "Khoai phải làm cỗ cưới linh đình cho cả làng"], x: "Đoạn đầu kể: phú ông dỗ ngọt “Mày chịu khó làm cho tao ba năm, tao sẽ gả con gái cho.” Việc tìm cây tre trăm đốt chỉ được lão đặt ra sau khi hết ba năm, để lừa anh.", lv: 1, p: "cay-tre" },
      { topic: "Thế giới cổ tích", type: "order", q: "Sắp xếp các sự việc theo đúng trình tự trong văn bản «Cây tre trăm đốt».", o: ["Khoai làm lụng cho phú ông suốt ba năm", "Phú ông bắt Khoai vào rừng tìm cây tre trăm đốt", "Ông lão dạy Khoai hai câu thần chú", "Phú ông và nhà trai bị dính chặt vào cây tre", "Phú ông chịu gả con gái cho Khoai"], x: "Truyện kể theo trật tự thời gian: Khoai làm ba năm → phú ông sai tìm tre trăm đốt để lừa anh → ông lão hiện ra dạy thần chú → Khoai về, đọc “Khắc nhập”, phú ông và nhà trai bị dính vào cây tre → phú ông phải hứa gả con gái.", lv: 2, p: "cay-tre" },
      { topic: "Thế giới cổ tích", type: "tf4", q: "Dựa vào đặc điểm của truyện cổ tích, mỗi nhận xét sau về văn bản «Cây tre trăm đốt» đúng hay sai?", o: ["Khoai là nhân vật chính diện, phú ông là nhân vật phản diện.", "Ông lão hiện ra dạy thần chú và trăm đốt tre tự dính vào nhau là chi tiết hoang đường, kì ảo.", "Phú ông sai Khoai tìm cây tre trăm đốt vì thật lòng muốn có đũa cưới đẹp.", "Truyện mở đầu bằng “Ngày xửa ngày xưa”, chỉ thời gian không xác định, như nhiều truyện cổ tích khác."], a: [true, true, false, true], x: "a) Đúng: Khoai hiền lành, chăm chỉ (tốt, thiện); phú ông lừa lọc, tham lam (xấu, ác). b) Đúng: đó là những chi tiết không có thật, thường gặp trong truyện cổ tích. c) Sai: lão biết không có cây tre nào trăm đốt, cố ý bày việc không thể làm được để Khoai không về kịp đám cưới. d) Đúng: lời kể trong truyện cổ tích thường mở đầu bằng những từ ngữ chỉ không gian, thời gian không xác định.", lv: 3, p: "cay-tre" },
      { topic: "Thế giới cổ tích", type: "mc", q: "Kết thúc truyện, Khoai lấy được con gái phú ông, còn phú ông và nhà trai bị một phen hú vía. Cách kết thúc ấy thể hiện ước mơ gì của người lao động xưa?", o: ["Người hiền lành, thật thà được hưởng hạnh phúc, kẻ tham lam, lừa lọc bị trừng trị", "Người nghèo nên nhẫn nhịn, chịu thiệt thì sẽ được người giàu thương", "Ai biết nhiều câu thần chú thì sẽ trở nên giàu có", "Người giàu luôn đúng, người nghèo phải nghe lời"], x: "Khoai nghèo nhưng hiền lành, thật thà, cuối cùng được hạnh phúc; phú ông tham lam, lừa lọc bị trừng phạt và phải giữ lời hứa. Truyện cổ tích thể hiện ước mơ về lẽ công bằng: ở hiền gặp lành, ác giả ác báo.", lv: 3, p: "cay-tre" },
      { topic: "Thế giới cổ tích", type: "mc", q: "Theo Tri thức ngữ văn (Bài 7), truyện cổ tích là loại truyện dân gian kể về:", o: ["Số phận và cuộc đời của các nhân vật trong những mối quan hệ xã hội, có nhiều yếu tố hư cấu, kì ảo", "Những chuyến đi có thật mà người viết tận mắt chứng kiến", "Loài vật, đồ vật được nhân hoá, biết nói năng như người", "Những lễ hội có thật được thuật lại theo trình tự thời gian"], x: "Truyện cổ tích kể về số phận, cuộc đời của các nhân vật (người mồ côi, người em út, người nghèo khổ…) trong các mối quan hệ gia đình, xã hội, có nhiều yếu tố hư cấu, kì ảo, thể hiện ước mơ về lẽ công bằng và cuộc sống tốt đẹp. Chuyến đi có thật là du kí; loài vật nhân hoá là truyện đồng thoại; lễ hội thuật lại là văn bản thông tin.", lv: 1 },
      { topic: "Thế giới cổ tích", type: "mc", q: "Trong truyện «Thạch Sanh», niêu cơm thần ăn mãi không hết khiến quân mười tám nước chư hầu phải cúi đầu rút về. Chi tiết ấy thể hiện điều gì?", o: ["Ước mơ về sức mạnh kì diệu của lòng nhân ái và khát vọng hoà bình của nhân dân", "Thạch Sanh là người nấu cơm giỏi nhất trong nước", "Quân chư hầu quá đói nên không còn sức đánh nhau", "Nhà vua rất giàu có, kho lương thực không bao giờ cạn"], x: "Thạch Sanh không dùng gươm giáo mà dùng tiếng đàn và niêu cơm để quân giặc tự lui: niêu cơm thần tượng trưng cho tấm lòng nhân hậu, rộng lượng và ước mơ về một cuộc sống no đủ, hoà bình. Chi tiết không nói về tài nấu ăn hay sự giàu có của nhà vua.", lv: 2 },
      { topic: "Thế giới cổ tích", type: "tf4", q: "Từ kết cục của người anh và người em trong truyện «Cây khế», mỗi nhận xét sau đúng hay sai?", o: ["Người em hiền lành, thật thà, làm đúng lời chim dặn nên được đền ơn xứng đáng.", "Người anh gặp nạn trên đường về vì chim thần không giữ lời hứa.", "Truyện gửi gắm bài học: tham lam sẽ phải trả giá.", "Truyện khuyên mọi người không nên trồng cây khế trong vườn."], a: [true, false, true, false], x: "a) Đúng: người em may túi ba gang đúng lời chim, lấy vừa đủ vàng nên trở nên sung túc. b) Sai: chim vẫn chở người anh ra đảo như đã hứa; người anh tham lam, may túi quá to và lấy quá nhiều vàng nên mới gặp nạn. c) Đúng: đó là bài học chính của truyện. d) Sai: cây khế chỉ là chi tiết của câu chuyện, truyện không khuyên điều đó.", lv: 3 },
      { topic: "Nghĩa của từ", type: "mc", q: "Yếu tố «giả» trong «sứ giả» có nghĩa là người, kẻ. Từ nào dưới đây có yếu tố «giả» mang nghĩa ấy?", o: ["thính giả", "giả vờ", "giả dối", "hàng giả"], x: "“Thính giả” là người nghe (thính: nghe, giả: người), như thính giả của đài phát thanh. Trong “giả vờ”, “giả dối”, “hàng giả”, “giả” có nghĩa là không thật.", lv: 1 },
      { topic: "Nghĩa của từ", type: "mc", q: "Đọc câu: «Nghe tin giặc đã tràn đến đầu làng, dân làng ai nấy hoảng hốt, kẻ chạy ngược, người chạy xuôi.» Dựa vào các từ ngữ xung quanh, có thể suy đoán «hoảng hốt» nghĩa là:", o: ["Sợ hãi, cuống quýt, mất bình tĩnh", "Vui mừng, hớn hở, phấn khởi", "Bình thản, không quan tâm đến việc gì", "Mệt mỏi, uể oải vì làm việc nhiều"], x: "Dân làng nghe tin giặc đến, “kẻ chạy ngược, người chạy xuôi”: những từ ngữ xung quanh cho thấy họ sợ hãi, cuống quýt. Đó là nghĩa của “hoảng hốt”.", lv: 2 },
      { topic: "Nghĩa của từ", type: "mc", q: "Thành ngữ «hô mưa gọi gió» có các từ sắp xếp đan xen (hô – gọi, mưa – gió). Thành ngữ nào dưới đây cũng được tạo nên theo cách ấy?", o: ["lên thác xuống ghềnh", "chậm như rùa", "nước chảy đá mòn", "có công mài sắt, có ngày nên kim"], x: "“Lên thác xuống ghềnh” có hai động từ “lên – xuống” và hai danh từ “thác – ghềnh” đan xen nhau, giống kiểu “hô mưa gọi gió”, “oán nặng thù sâu”. Ba thành ngữ, tục ngữ còn lại là cách nói ví von hoặc hai vế nối tiếp, không đan xen như vậy.", lv: 2 },
      { topic: "Từ đơn và từ phức", type: "tf4", q: "Mỗi nhận xét sau về các từ trong câu «Nghe tiếng trống trận, dân làng nô nức kéo nhau ra bãi.» đúng hay sai?", o: ["“nô nức” là từ láy.", "“dân làng” là từ ghép.", "“trống trận” là từ láy.", "“kéo” là từ phức."], a: [true, true, false, false], x: "a) Đúng: hai tiếng “nô”, “nức” lặp lại âm đầu “n”, tiếng “nô” không có nghĩa riêng: từ láy. b) Đúng: “dân” và “làng” đều có nghĩa, ghép lại chỉ người dân trong làng. c) Sai: “trống” và “trận” đều có nghĩa, là từ ghép. d) Sai: “kéo” chỉ có một tiếng, là từ đơn.", lv: 1 },
      { topic: "Từ đơn và từ phức", type: "mc", q: "Trong bốn từ sau, từ nào là từ ghép (các tiếng đều có nghĩa và quan hệ với nhau về nghĩa)?", o: ["núi non", "lác đác", "rì rào", "lấp lánh"], x: "“Núi non” gồm hai tiếng “núi”, “non” đều có nghĩa (non cũng là núi), ghép lại chỉ núi nói chung: từ ghép. “Lác đác”, “rì rào”, “lấp lánh” có các tiếng giống nhau về âm đầu hoặc vần, tiếng “lác”, “rì”, “lấp” không có nghĩa riêng: từ láy.", lv: 1 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "mc", q: "Cụm từ nào dưới đây có tính từ làm trung tâm?", o: ["đẹp như tranh vẽ", "đang gặt lúa ngoài đồng", "những con thuyền nhỏ", "đã về tới đầu làng"], x: "“Đẹp như tranh vẽ” có tính từ “đẹp” làm trung tâm, “như tranh vẽ” đứng sau bổ sung ý nghĩa cho tính từ: cụm tính từ. “Đang gặt lúa ngoài đồng”, “đã về tới đầu làng” là cụm động từ; “những con thuyền nhỏ” là cụm danh từ.", lv: 1 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "mc", q: "Trong cụm tính từ «vẫn còn rất xanh tốt», từ nào là tính từ trung tâm?", o: ["xanh tốt", "vẫn", "còn", "rất"], x: "“Xanh tốt” là tính từ chỉ đặc điểm, làm trung tâm của cụm; “vẫn”, “còn”, “rất” đứng trước, bổ sung ý tiếp diễn và mức độ.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Câu «Quân giặc kéo sang đông như kiến cỏ.» dùng biện pháp tu từ nào?", o: ["So sánh", "Nhân hoá", "Ẩn dụ", "Điệp ngữ"], x: "Câu đối chiếu số lượng quân giặc với kiến cỏ (rất nhiều), có từ so sánh “như”: đó là biện pháp so sánh.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Cách nói «vàng óng như được nhuộm nắng» trong câu «Bụi tre đằng ngà vàng óng như được nhuộm nắng.» giúp người đọc hình dung điều gì?", o: ["Màu vàng óng ánh, đẹp lạ của bụi tre, như có ánh nắng nhuộm vào", "Bụi tre mọc rất cao, vượt hẳn những cây xung quanh", "Bụi tre đã bị cháy khô vì nắng gắt", "Người ta đã sơn màu vàng lên thân tre"], x: "Đối chiếu màu vàng của tre với màu nắng (“như được nhuộm nắng”) làm người đọc hình dung sắc vàng óng ánh, tươi sáng, đẹp lạ của bụi tre. Câu không nói tre cao, cháy khô hay được sơn.", lv: 2 },
      { topic: "Dấu câu", type: "mc", q: "Đọc câu: «Hội làng có nhiều trò vui: trẻ con chơi ô ăn quan, bịt mắt bắt dê; người lớn thi đấu vật, kéo co; các cụ già đánh cờ dưới gốc đa.» Dấu chấm phẩy trong câu dùng để làm gì?", o: ["Đánh dấu ranh giới giữa các bộ phận trong một chuỗi liệt kê phức tạp (mỗi bộ phận đã có dấu phẩy bên trong)", "Kết thúc một câu kể", "Đánh dấu lời nói trực tiếp của nhân vật", "Ngăn cách các từ cùng loại trong một bộ phận"], x: "Câu liệt kê ba nhóm trò vui (trẻ con, người lớn, các cụ già); trong mỗi nhóm lại có các trò ngăn bằng dấu phẩy. Dấu chấm phẩy đánh dấu ranh giới giữa ba bộ phận ấy để người đọc không nhầm nhóm này với nhóm kia.", lv: 2 },
      { topic: "Viết", type: "essay", q: "Viết phần mở bài và lập dàn ý phần thân bài (tổng cộng khoảng 150–200 chữ) cho bài văn thuyết minh thuật lại một lễ hội hoặc một ngày hội ở trường mà bạn đã tham gia hoặc chứng kiến.", rubric: [{ c: "Mở bài giới thiệu được sự kiện: tên sự kiện, thời gian, địa điểm; cho biết bạn tham gia hay chứng kiến", p: 1 }, { c: "Dàn ý thân bài nêu các hoạt động chính theo trình tự thời gian (mở đầu, diễn biến, kết thúc), mỗi ý một dòng", p: 1.5 }, { c: "Có ít nhất một chi tiết tiêu biểu, hấp dẫn ở mỗi phần (âm thanh, màu sắc, hoạt động nổi bật)", p: 0.5 }, { c: "Dùng ngôi tường thuật phù hợp và nhất quán (“tôi” hoặc “chúng tôi”); có ý nêu cảm nghĩ của người viết về sự kiện", p: 0.5 }, { c: "Đúng độ dài (khoảng 150–200 chữ); dùng từ đúng, viết đúng chính tả", p: 0.5 }], x: "Mở bài viết thành đoạn văn hoàn chỉnh; dàn ý thân bài ghi từng ý, theo trật tự thời gian; nêu rõ người tường thuật (“tôi”, “chúng tôi”).\nBài tham khảo:\nMở bài: Sáng thứ Sáu tuần trước, sân trường tôi rộn ràng khác hẳn mọi ngày: Ngày hội đọc sách của trường Trung học cơ sở Bình Minh được tổ chức. Là thành viên đội tuyên truyền của lớp 6A, tôi vừa được tham gia vừa được chứng kiến từ đầu đến cuối ngày hội ấy.\nDàn ý thân bài:\n– 7 giờ 30: học sinh tập trung, các lớp dựng gian trưng bày sách, treo áp phích tự vẽ; tiếng loa, tiếng cười nói khắp sân.\n– 8 giờ: lễ khai mạc; cô hiệu trưởng phát biểu về ý nghĩa của việc đọc sách; đội văn nghệ biểu diễn tiết mục kể chuyện theo sách.\n– 8 giờ 30: các lớp thi giới thiệu cuốn sách yêu thích; lớp tôi giới thiệu «Dế Mèn phiêu lưu kí», bạn Hà đóng vai Dế Mèn khiến cả sân trường vỗ tay.\n– 9 giờ 30: hội chợ đổi sách cũ; gian hàng lớp 6C đông nhất vì có nhiều truyện tranh.\n– 10 giờ 30: trao giải, chụp ảnh lưu niệm; học sinh dọn gian hàng, sân trường trở lại yên tĩnh.\n– Cảm nghĩ: ngày hội giúp chúng tôi thêm yêu sách và hiểu bạn bè hơn.", lv: 3 }
    ]
  },
  "van6-gk2-de2": {
    note: "Giữa học kì II (Bài 6–7), sách Kết nối tri thức. 10 câu mức Biết, 8 câu mức Hiểu, 7 câu mức Vận dụng: đọc hiểu một văn bản thông tin thuật lại hội làng và một truyện cổ tích thế giới kể lại, câu hỏi về thể loại và văn bản đã học, 10 câu tiếng Việt và một câu Viết tự chấm theo gợi ý. Có lời giải từng câu.",
    passages: {
      "hoi-lang": {
        title: "Hội làng tôi (bài viết của một học sinh)",
        text: "Năm nào cũng vậy, cứ đến mồng 10 tháng Giêng là làng tôi mở hội ở đình làng, nơi thờ Thành hoàng là một vị tướng có công đánh giặc giữ làng thuở xưa. Năm nay, lần đầu tiên tôi được bố mẹ cho đi xem hội từ sáng đến tối.\nTừ bảy giờ sáng, đường làng đã rợp cờ. Lễ rước kiệu bắt đầu từ đình ra miếu ngoài đồng rồi quay về. Đi đầu là đội cờ, đội trống, tiếp đến là chiếc kiệu sơn son do tám thanh niên khiêng, theo sau là các cụ cao niên trong bộ áo the, khăn xếp. Tiếng trống hội thùng thùng khiến ai cũng rảo bước theo đám rước.\nChín giờ, lễ dâng hương diễn ra trong đình. Ông trưởng làng đọc văn tế, nhắc lại công lao của Thành hoàng và cầu cho một năm mưa thuận gió hoà. Mọi người đứng im phăng phắc, chỉ nghe tiếng chuông ngân.\nBuổi trưa, sân đình biến thành bãi hội. Bên này thi đấu vật, bên kia kéo co; trẻ con chúng tôi xúm quanh sới chọi gà và trò bịt mắt bắt dê. Tiếng hò reo không lúc nào dứt. Chiều tối, dưới gốc đa, phường chèo trong làng diễn tích «Thạch Sanh», tiếng đàn, tiếng hát vang đến khuya.\nRa về, tôi thấy hội làng không chỉ là những trò vui. Đó là dịp cả làng cùng nhớ ơn người đã giữ làng, giữ nước, và là dịp để những người đi xa trở về gặp lại nhau."
      },
      "lo-lem": {
        title: "Cô bé Lọ Lem (truyện cổ tích, kể lại)",
        text: "Ngày xưa, ở một vương quốc nọ, có một cô gái hiền hậu sống với mẹ kế và hai cô chị cùng cha khác mẹ. Mẹ kế và hai chị bắt cô làm lụng suốt ngày: gánh nước, nấu ăn, giặt giũ, quét dọn. Đêm xuống, cô chỉ được nằm cạnh bếp tro, quần áo lúc nào cũng lấm lem, nên mọi người gọi cô là Lọ Lem.\nMột hôm, nhà vua mở hội kén vợ cho hoàng tử. Hai cô chị diện váy áo lộng lẫy đi dự hội, còn Lọ Lem phải ở nhà. Cô ngồi khóc bên bếp. Bỗng một bà tiên hiện ra. Bà vung đũa thần: quả bí ngô biến thành cỗ xe vàng, bốn chú chuột thành bốn con ngựa trắng, bộ quần áo rách thành chiếc váy dạ hội lấp lánh và đôi giày thuỷ tinh xinh xắn. Bà dặn: “Con phải về trước mười hai giờ đêm, nếu không mọi phép màu sẽ tan biến.”\nỞ hội, hoàng tử chỉ khiêu vũ với Lọ Lem. Mải vui, đến khi chuông điểm mười hai tiếng, cô mới hốt hoảng chạy về, đánh rơi một chiếc giày thuỷ tinh trên bậc thềm. Hoàng tử nhặt chiếc giày, sai người đi khắp vương quốc tìm cô gái đi vừa chiếc giày ấy. Hai cô chị cố nhét chân vào mà không được. Đến lượt Lọ Lem, chiếc giày vừa khít. Hoàng tử nhận ra cô, đón cô về cung và hai người sống hạnh phúc bên nhau."
      }
    },
    questions: [
      { topic: "Chuyện kể về những người anh hùng", type: "mc", q: "Theo văn bản, hội làng được mở vào thời gian nào và ở đâu?", o: ["Mồng 10 tháng Giêng, ở đình làng", "Mồng 9 tháng Tư, ở đền Thượng", "Rằm tháng Tám, ở sân trường", "Mồng 10 tháng Giêng, ở miếu ngoài đồng"], x: "Câu mở đầu cho biết: “cứ đến mồng 10 tháng Giêng là làng tôi mở hội ở đình làng”. Miếu ngoài đồng chỉ là nơi đám rước đi tới rồi quay về đình.", lv: 1, p: "hoi-lang" },
      { topic: "Chuyện kể về những người anh hùng", type: "mc", q: "Bài viết thuật lại các hoạt động của hội làng theo trình tự nào?", o: ["Theo thời gian trong ngày: từ sáng, buổi trưa đến chiều tối", "Từ trò chơi quan trọng nhất đến trò chơi ít quan trọng hơn", "Theo thứ tự từ ngoài đồng vào trong đình", "Theo tuổi của người tham gia: trẻ con, thanh niên, các cụ già"], x: "Các đoạn lần lượt kể: bảy giờ sáng rước kiệu, chín giờ dâng hương, buổi trưa trò chơi, chiều tối diễn chèo. Văn bản thông tin thuật lại một sự kiện thường trình bày diễn biến theo trật tự thời gian như vậy.", lv: 2, p: "hoi-lang" },
      { topic: "Chuyện kể về những người anh hùng", type: "tf4", q: "Mỗi nhận xét sau về bài viết «Hội làng tôi» đúng hay sai?", o: ["Đây là văn bản thông tin thuật lại một sự kiện, người viết là người tham gia, chứng kiến và xưng “tôi”.", "Bài viết có yếu tố kì ảo: vị Thành hoàng hiện về cùng dự hội với dân làng.", "Câu «Bên này thi đấu vật, bên kia kéo co; trẻ con chúng tôi xúm quanh sới chọi gà và trò bịt mắt bắt dê.» dùng dấu chấm phẩy để tách các bộ phận trong một chuỗi liệt kê.", "Đoạn cuối nêu cảm nghĩ, cách hiểu của người viết về ý nghĩa của hội làng."], a: [true, false, true, true], x: "a) Đúng: người viết kể lại điều mình thấy, xưng “tôi”, cung cấp thông tin về thời gian, địa điểm, diễn biến. b) Sai: văn bản chỉ thuật lại những gì diễn ra thật, không có chi tiết hoang đường. c) Đúng: câu liệt kê các trò chơi ở từng góc sân, dấu chấm phẩy đánh dấu ranh giới giữa các bộ phận ấy. d) Đúng: đoạn cuối nói hội làng là dịp nhớ ơn người giữ làng và gặp lại người đi xa.", lv: 3, p: "hoi-lang" },
      { topic: "Chuyện kể về những người anh hùng", type: "mc", q: "Nếu viết bài thuyết minh thuật lại ngày hội thể thao của trường theo cách viết của bài «Hội làng tôi», bạn nên làm gì?", o: ["Nêu rõ thời gian, địa điểm, rồi kể các hoạt động theo trật tự thời gian, chọn vài chi tiết nổi bật và nêu cảm nghĩ của mình", "Tưởng tượng thêm nhiều chi tiết kì ảo để ngày hội thêm hấp dẫn", "Chỉ liệt kê tên các môn thi đấu, không cần nói diễn ra lúc nào, ở đâu", "Kể lại một truyền thuyết về người anh hùng thay cho ngày hội"], x: "Bài «Hội làng tôi» giới thiệu thời gian, địa điểm, thuật lại diễn biến theo thời gian với các chi tiết tiêu biểu (đám rước, tiếng trống, trò chơi) và kết bằng cảm nghĩ. Văn bản thông tin không thêm chi tiết hư cấu và phải nêu rõ bối cảnh của sự kiện.", lv: 3, p: "hoi-lang" },
      { topic: "Chuyện kể về những người anh hùng", type: "mc", q: "Trong truyện «Sơn Tinh, Thuỷ Tinh», vua Hùng chọn người cưới Mị Nương bằng cách nào?", o: ["Ai mang sính lễ đến trước thì được cưới Mị Nương", "Ai thắng trong cuộc thi bơi qua sông thì được cưới", "Ai dâng nước lên cao hơn thì được cưới", "Mị Nương tự chọn người mình yêu"], x: "Vua Hùng không biết chọn ai, bèn đặt ra lễ vật và hẹn: ngày mai, ai đem sính lễ đến trước sẽ được rước Mị Nương về. Sơn Tinh đến trước nên cưới được Mị Nương.", lv: 1 },
      { topic: "Chuyện kể về những người anh hùng", type: "mc", q: "Theo truyện «Sơn Tinh, Thuỷ Tinh», vì sao hằng năm Thuỷ Tinh lại dâng nước đánh Sơn Tinh? Qua đó, truyện giải thích hiện tượng tự nhiên nào?", o: ["Thuỷ Tinh oán giận vì thua cuộc, không cưới được Mị Nương; truyện giải thích hiện tượng lũ lụt hằng năm", "Thuỷ Tinh muốn thử lại tài năng của mình; truyện giải thích hiện tượng mưa phùn mùa xuân", "Thuỷ Tinh muốn giúp Sơn Tinh có thêm nước tưới; truyện giải thích hiện tượng hạn hán", "Thuỷ Tinh bị vua Hùng ra lệnh; truyện giải thích hiện tượng thuỷ triều"], x: "Thuỷ Tinh không cưới được Mị Nương nên nổi giận, hằng năm dâng nước đánh Sơn Tinh nhưng lần nào cũng thua. Người xưa mượn câu chuyện để giải thích nạn lũ lụt hằng năm và thể hiện ước mơ chế ngự thiên tai.", lv: 2 },
      { topic: "Chuyện kể về những người anh hùng", type: "mc", q: "Trong truyện «Thánh Gióng», đánh giặc xong, tráng sĩ cởi áo giáp sắt bỏ lại rồi cùng ngựa bay về trời. Theo bạn, chi tiết này có ý nghĩa gì?", o: ["Người anh hùng đánh giặc vì dân, không màng công danh, phú quý; Gióng trở thành hình tượng bất tử trong lòng nhân dân", "Gióng sợ bị nhà vua bắt tội vì đã làm gãy roi sắt", "Gióng chán cảnh dưới trần gian nên bỏ về trời", "Giặc Ân vẫn còn ở trên trời nên Gióng phải lên đánh tiếp"], x: "Gióng không ở lại nhận ban thưởng mà bay về trời: người anh hùng ra đời để cứu nước, xong việc thì thanh thản ra đi, không màng danh lợi. Vì thế, Gióng sống mãi trong tâm trí nhân dân, được lập đền thờ, mở hội hằng năm.", lv: 3 },
      { topic: "Thế giới cổ tích", type: "mc", q: "Theo văn bản, bà tiên dặn Lọ Lem điều gì trước khi đi dự hội?", o: ["Phải về trước mười hai giờ đêm, nếu không phép màu sẽ tan biến", "Không được khiêu vũ với hoàng tử", "Phải mang theo quả bí ngô để làm quà cho nhà vua", "Không được để hai cô chị nhìn thấy mình"], x: "Bà tiên dặn: “Con phải về trước mười hai giờ đêm, nếu không mọi phép màu sẽ tan biến.” Vì vậy khi chuông điểm mười hai tiếng, Lọ Lem mới hốt hoảng chạy về.", lv: 1, p: "lo-lem" },
      { topic: "Thế giới cổ tích", type: "mc", q: "Vì sao cô gái trong truyện được gọi là Lọ Lem?", o: ["Vì cô phải làm lụng vất vả, ngủ cạnh bếp tro, quần áo lúc nào cũng lấm lem", "Vì cô thích nghịch tro bếp từ khi còn nhỏ", "Vì mẹ cô đặt tên như vậy từ lúc mới sinh", "Vì cô làm nghề bán than trong vương quốc"], x: "Đoạn đầu kể: mẹ kế và hai chị bắt cô làm mọi việc, đêm cô chỉ được nằm cạnh bếp tro, “quần áo lúc nào cũng lấm lem, nên mọi người gọi cô là Lọ Lem”. Cái tên gắn với cảnh sống cực nhọc, bị đối xử bất công của cô.", lv: 2, p: "lo-lem" },
      { topic: "Thế giới cổ tích", type: "tf4", q: "Dựa vào đặc điểm của truyện cổ tích, mỗi nhận xét sau về văn bản «Cô bé Lọ Lem» đúng hay sai?", o: ["Quả bí ngô biến thành cỗ xe, chuột biến thành ngựa là chi tiết hoang đường, kì ảo.", "Lọ Lem thuộc tuyến nhân vật chính diện; mẹ kế và hai cô chị thuộc tuyến phản diện.", "Truyện được kể theo ngôi thứ nhất, người kể là Lọ Lem.", "Truyện kết thúc có hậu: người hiền lành, chịu nhiều thiệt thòi được hưởng hạnh phúc."], a: [true, true, false, true], x: "a) Đúng: đó là những phép màu không có thật. b) Đúng: Lọ Lem hiền hậu, chăm chỉ; mẹ kế và hai chị đối xử tàn nhẫn với cô. c) Sai: người kể giấu mình, gọi nhân vật là “cô”, “Lọ Lem”, “hoàng tử”: ngôi thứ ba. d) Đúng: Lọ Lem được hoàng tử đón về cung, sống hạnh phúc; kết thúc có hậu là đặc điểm thường gặp của truyện cổ tích.", lv: 3, p: "lo-lem" },
      { topic: "Thế giới cổ tích", type: "mc", q: "Nhân vật Lọ Lem có điểm gì giống nhân vật Thạch Sanh trong truyện cổ tích Việt Nam?", o: ["Đều hiền lành, chịu nhiều thiệt thòi, được lực lượng thần kì giúp đỡ và cuối cùng được hưởng hạnh phúc", "Đều sống trong cung vua từ nhỏ và được nhà vua yêu quý", "Đều dùng tiếng đàn kì diệu để cảm hoá kẻ ác", "Đều tự mình trả thù những kẻ đã hãm hại mình"], x: "Lọ Lem bị mẹ kế bắt làm lụng, được bà tiên giúp; Thạch Sanh mồ côi, bị Lý Thông lừa hại, được thiên thần dạy võ nghệ và có cây đàn thần. Cả hai đều hiền lành, chịu thiệt thòi, được lực lượng thần kì giúp và kết thúc hạnh phúc. Lọ Lem không có tiếng đàn, cả hai đều không trả thù.", lv: 3, p: "lo-lem" },
      { topic: "Thế giới cổ tích", type: "match", q: "Nối mỗi nhân vật với kết cục của nhân vật đó trong truyện cổ tích đã học.", l: ["Thạch Sanh", "Mẹ con Lý Thông", "Người anh trong «Cây khế»"], r: ["Được nhà vua gả công chúa và nhường ngôi", "Bị sét đánh chết, hoá kiếp thành bọ hung", "Rơi xuống biển vì túi vàng quá nặng", "Trở thành người hát rong đi khắp nơi"], x: "Thạch Sanh được vua gả công chúa và nhường ngôi; mẹ con Lý Thông trên đường về quê bị sét đánh chết, hoá thành bọ hung; người anh trong «Cây khế» tham lam lấy quá nhiều vàng, chim chở không nổi nên rơi xuống biển. Ô “Trở thành người hát rong” không phải kết cục của nhân vật nào trong ba truyện này.", lv: 1 },
      { topic: "Thế giới cổ tích", type: "mc", q: "Trong truyện «Vua chích choè», vì sao nhà vua gả công chúa cho một người hát rong?", o: ["Vì công chúa kiêu ngạo, chế giễu tất cả những người đến cầu hôn, nhà vua tức giận nên muốn trừng phạt", "Vì người hát rong hát hay đến mức nhà vua cảm động", "Vì nhà vua quá nghèo, không có của hồi môn cho con", "Vì công chúa đã yêu người hát rong từ trước"], x: "Trong bữa tiệc kén phò mã, công chúa giễu cợt mọi người, gọi một vị vua là “Vua chích choè”. Nhà vua nổi giận, thề gả nàng cho người ăn xin đầu tiên đến trước cửa, và người đó là một người hát rong. Về sau, người hát rong chính là Vua chích choè cải trang để uốn nắn tính kiêu ngạo của nàng.", lv: 2 },
      { topic: "Thế giới cổ tích", type: "tf4", q: "Mỗi nhận xét sau về hai nhân vật Thạch Sanh và Lý Thông trong truyện «Thạch Sanh» đúng hay sai?", o: ["Thạch Sanh thật thà, dũng cảm; Lý Thông gian xảo, hèn nhát: hai nhân vật đối lập nhau về hành động.", "Lý Thông nhiều lần cướp công Thạch Sanh nhưng cuối cùng vẫn được hưởng vinh hoa.", "Qua số phận hai nhân vật, truyện thể hiện niềm tin: ở hiền gặp lành, kẻ ác bị trừng trị.", "Thạch Sanh tha cho mẹ con Lý Thông vì sợ bị trả thù."], a: [true, false, true, false], x: "a) Đúng: Thạch Sanh tin người, xả thân giết chằn tinh, cứu công chúa; Lý Thông lừa Thạch Sanh đi nộp mạng, cướp công, lấp cửa hang. b) Sai: cuối truyện, mẹ con Lý Thông bị trừng phạt đích đáng, không được hưởng gì. c) Đúng: đó là quan niệm về lẽ công bằng của truyện cổ tích. d) Sai: Thạch Sanh tha cho mẹ con Lý Thông vì rộng lượng, nhân hậu.", lv: 3 },
      { topic: "Nghĩa của từ", type: "mc", q: "Yếu tố «thuỷ» trong «Thuỷ Tinh» có nghĩa là nước. Từ nào dưới đây có yếu tố «thuỷ» KHÔNG mang nghĩa ấy?", o: ["thuỷ chung", "thuỷ triều", "tàu thuỷ", "thuỷ sản"], x: "“Thuỷ triều” (nước lên xuống theo ngày), “tàu thuỷ” (tàu đi trên nước), “thuỷ sản” (sản vật dưới nước) đều có “thuỷ” là nước. Trong “thuỷ chung”, “thuỷ” có nghĩa là đầu, trước sau như một.", lv: 1 },
      { topic: "Nghĩa của từ", type: "mc", q: "Biết «quốc» là nước, «kì» là cờ, có thể suy đoán «quốc kì» có nghĩa là:", o: ["Lá cờ tượng trưng cho một nước", "Bài hát truyền thống của một vùng", "Ngày lễ lớn của một nước", "Người đứng đầu một nước"], x: "Ghép nghĩa hai yếu tố “quốc” (nước) và “kì” (cờ) được nghĩa của từ: quốc kì là lá cờ tượng trưng cho một nước.", lv: 2 },
      { topic: "Nghĩa của từ", type: "mc", q: "Đọc câu: «Từ sáng sớm, cả làng đã tất bật: người quét dọn sân đình, người kê bàn ghế, người treo cờ.» Dựa vào các từ ngữ xung quanh, «tất bật» có nghĩa là:", o: ["Bận rộn, vội vã, luôn tay luôn chân", "Buồn bã, không muốn làm gì", "Vui vẻ, thong thả ngồi trò chuyện", "Giận dữ, cãi nhau ầm ĩ"], x: "Các từ ngữ xung quanh (“từ sáng sớm”, “người quét dọn, người kê bàn ghế, người treo cờ”) cho thấy ai cũng đang bận rộn làm việc. Đó là nghĩa của “tất bật”.", lv: 2 },
      { topic: "Từ đơn và từ phức", type: "mc", q: "Từ láy nào dưới đây gợi tả dáng người?", o: ["lom khom", "ào ào", "xanh xanh", "chót vót"], x: "“Lom khom” gợi dáng người cúi thấp, cong lưng. “Ào ào” gợi âm thanh, “xanh xanh” gợi màu sắc, “chót vót” gợi độ cao của sự vật.", lv: 1 },
      { topic: "Từ đơn và từ phức", type: "tf", q: "Từ «cuống quýt» là từ láy.", a: true, x: "Đúng. Hai tiếng “cuống”, “quýt” có cùng phụ âm đầu (viết là c và qu), tiếng “quýt” không có nghĩa riêng trong từ này: “cuống quýt” là từ láy, chỉ trạng thái vội vàng, luống cuống.", lv: 1 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "mc", q: "Cụm từ «đã dâng nước lên cao» là:", o: ["Cụm động từ", "Cụm tính từ", "Cụm danh từ", "Một từ ghép"], x: "Động từ “dâng” làm trung tâm; “đã” đứng trước bổ sung ý thời gian, “nước lên cao” đứng sau bổ sung ý đối tượng và kết quả: đây là cụm động từ.", lv: 1 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "tf4", q: "Mỗi nhận xét sau về các cụm từ đúng hay sai?", o: ["“rất hiền lành” là cụm tính từ.", "“đang gánh tre về làng” là cụm động từ.", "“mấy đốt tre già” là cụm động từ.", "Trong cụm “đang gánh tre về làng”, động từ trung tâm là “về”."], a: [true, true, false, false], x: "a) Đúng: tính từ “hiền lành” làm trung tâm, “rất” chỉ mức độ. b) Đúng: động từ “gánh” làm trung tâm. c) Sai: danh từ “đốt” (đốt tre) làm trung tâm, “mấy” chỉ số lượng, “già” nêu đặc điểm: cụm danh từ. d) Sai: trung tâm là “gánh”; “về làng” chỉ bổ sung ý hướng đi.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Đọc đoạn: «Mưa vẫn rơi. Mưa rơi trên mái đình. Mưa rơi ướt cả đám rước.» Việc lặp lại cụm từ “mưa rơi” là biện pháp tu từ nào?", o: ["Điệp ngữ", "So sánh", "Nhân hoá", "Ẩn dụ"], x: "“Mưa rơi” được lặp lại ở ba câu liên tiếp để nhấn mạnh cơn mưa kéo dài, không dứt: đó là biện pháp điệp ngữ.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Cách nói «giục giã như thúc vào lòng người» trong câu «Tiếng trống hội giục giã như thúc vào lòng người.» nhằm làm nổi bật điều gì?", o: ["Không khí náo nức, rộn ràng mà tiếng trống đem lại cho người dự hội", "Tiếng trống quá to khiến mọi người khó chịu", "Người đánh trống rất khoẻ và đánh rất nhanh", "Chiếc trống hội được làm từ loại gỗ rất tốt"], x: "Đối chiếu tiếng trống với tiếng “thúc vào lòng người” gợi tả tiếng trống làm mọi người náo nức, muốn hoà ngay vào ngày hội. Câu không nói trống quá to, người đánh trống hay chất liệu trống.", lv: 2 },
      { topic: "Dấu câu", type: "mc", q: "Câu nào dưới đây dùng dấu chấm phẩy đúng?", o: ["Buổi sáng, đoàn rước đi từ đình ra miếu; buổi trưa, dân làng thi đấu vật, kéo co; buổi tối, sân đình sáng đèn hát chèo.", "Buổi sáng; đoàn rước đi từ đình ra miếu.", "Em rất thích; đọc truyện cổ tích vào buổi tối.", "Mẹ mua cam; quýt; bưởi để bày mâm ngũ quả."], x: "Câu đầu liệt kê ba bộ phận (sáng, trưa, tối), mỗi bộ phận đã có dấu phẩy bên trong, nên dùng dấu chấm phẩy để tách các bộ phận. Ba câu còn lại đặt dấu chấm phẩy chen vào giữa các từ trong cùng một bộ phận, hoặc dùng cho các từ đơn giản chỉ cần dấu phẩy.", lv: 2 },
      { topic: "Viết", type: "essay", q: "Đóng vai người em trong truyện «Cây khế», viết một đoạn văn (khoảng 150–200 chữ) kể lại việc bạn được chim thần đưa ra đảo lấy vàng.", rubric: [{ c: "Kể theo ngôi thứ nhất, người kể xưng “tôi” và nhập vai người em từ đầu đến cuối đoạn", p: 1 }, { c: "Kể đúng các sự việc chính của truyện gốc: chim ăn khế và hứa trả vàng, may túi ba gang, được chim chở ra đảo, lấy vàng rồi trở về", p: 1.5 }, { c: "Có sáng tạo thêm chi tiết tưởng tượng, miêu tả (cảnh đảo, cảm giác khi bay, suy nghĩ của người em) nhưng không làm sai cốt truyện", p: 0.5 }, { c: "Nêu được cảm xúc, suy nghĩ của nhân vật về việc xảy ra", p: 0.5 }, { c: "Đúng hình thức đoạn văn (khoảng 150–200 chữ); dùng từ đúng, viết đúng chính tả", p: 0.5 }], x: "Đoạn văn cần: xưng “tôi” (người em), kể lần lượt chim ăn khế, lời hứa “ăn một quả, trả cục vàng, may túi ba gang, mang đi mà đựng”, chuyến bay ra đảo, việc lấy vàng vừa đủ và trở về; thêm vài chi tiết tả cảnh, tả cảm xúc; không đổi kết cục.\nĐoạn văn tham khảo:\nTôi là người em trong câu chuyện «Cây khế». Sau khi cha mẹ mất, anh tôi lấy hết ruộng vườn, chỉ để lại cho vợ chồng tôi túp lều và cây khế ngọt ở góc vườn. Mùa khế chín năm ấy, một con chim lạ ngày nào cũng bay đến ăn. Tôi tiếc của, than thở, không ngờ chim cất tiếng: “Ăn một quả, trả cục vàng, may túi ba gang, mang đi mà đựng.” Nửa tin nửa ngờ, tôi vẫn may đúng chiếc túi ba gang. Sáng hôm sau, chim sà xuống, bảo tôi ngồi lên lưng. Gió thổi ù ù bên tai, dưới cánh chim là biển xanh mênh mông. Đến một hòn đảo đầy vàng bạc lấp lánh, tôi hoa cả mắt, nhưng nhớ lời chim, chỉ nhặt vừa đầy túi rồi leo lên lưng chim bay về. Từ đó, nhà tôi đủ ăn đủ mặc, lại có thể giúp đỡ bà con nghèo quanh xóm. Tôi hiểu rằng sống thật thà, biết đủ thì điều may mắn sẽ đến.", lv: 3 }
    ]
  },
  /* ---------- Ngữ văn 6 · Đề ngẫu nhiên giữa học kì II: câu riêng của ngân hàng (Phiên N9) ----------
     Kho câu của đề ngẫu nhiên = 31 câu dưới đây + 50 câu của hai đề cố định ở trên (mọi câu có lv). Ma trận trong
     data/banks/index.js: mỗi lần rút 25 câu, 10 Biết, 8 Hiểu, 7 Vận dụng: mỗi bài (Bài 6, 7) 7 câu đọc hiểu [2, 2, 3] rút theo đoạn
     (không quá 3 đoạn), 10 câu Tiếng Việt, 1 câu Viết.
     Đọc hiểu: mỗi bài thêm hai đoạn ngoài sách (Bài 6: truyền thuyết «Yết Kiêu» kể lại, 4 câu mức 1-2-3-3; văn bản thông tin thuật lại
     hội đua thuyền tự viết, 3 câu mức 1-2-3; Bài 7: truyện cổ tích «Cây bút thần» kể lại, 4 câu; «Bông hoa cúc trắng» kể lại, 3 câu).
     Các đoạn của kho đều 4 câu 1-2-3-3 hoặc 3 câu 1-2-3, nên lần rút nào cũng lấy hai đoạn, đúng mức, không ghi chú; câu lẻ về văn bản
     trong sách (ở hai đề cố định) được rút khi đã làm hết các đoạn. Tiếng Việt: thêm câu cho mọi ô ma trận. Viết: 3 câu (thuật lại lễ
     khai giảng theo trình tự thời gian; đóng vai công chúa trong «Vua chích choè»; mở bài đóng vai nhân vật một truyện cổ tích tự chọn),
     thang tự chấm 4 điểm, bài tham khảo. Câu tự soạn. */
  "van6-gk2-ngau-nhien": {
    note: "Giữa học kì II (Bài 6–7), sách Kết nối tri thức. Mỗi đề có 10 câu mức Biết, 8 câu mức Hiểu, 7 câu mức Vận dụng, trong đó có một câu Viết tự chấm theo gợi ý. Đoạn đọc ngoài sách, kể lại bằng lời người soạn. Có lời giải từng câu.",
    passages: {
      "yet-kieu": {
        title: "Yết Kiêu (truyền thuyết, kể lại)",
        text: "Thời nhà Trần, ở làng Hạ Bì ven biển có chàng trai tên là Yết Kiêu, nhà nghèo, sống bằng nghề chài lưới và bơi lặn rất giỏi. Một đêm trăng, chàng ra bãi biển thì thấy hai con trâu trắng đang húc nhau dữ dội. Chàng cầm đòn gánh xông vào can. Hai con trâu bỏ chạy xuống biển, mất hút, chỉ để lại trên đòn gánh mấy sợi lông trắng. Yết Kiêu đoán là trâu thần, bèn nuốt mấy sợi lông ấy. Từ đó, chàng lặn dưới nước lâu bao nhiêu cũng được, đi lại dưới đáy sông như đi trên đất.\nÍt lâu sau, giặc Nguyên kéo sang xâm lược, thuyền chiến đậu kín cả khúc sông. Yết Kiêu xin vua một chiếc dùi sắt và một chiếc búa, rồi đêm đêm lặn xuống sông, lặng lẽ đục thủng đáy thuyền giặc. Thuyền chìm hết chiếc này đến chiếc khác mà giặc không hiểu vì sao. Chúng hoảng sợ, giăng lưới khắp sông, cuối cùng bắt được chàng. Tướng giặc hỏi: “Nước Nam có bao nhiêu kẻ lặn giỏi như ngươi?”. Yết Kiêu đáp: “Nhiều lắm, ta chỉ là kẻ kém nhất.” Giặc dụ chàng chỉ chỗ những người ấy, chàng giả vờ nhận lời. Khi thuyền giặc ra giữa sông, chàng nhảy ùm xuống nước, biến mất.\nGiặc tan, nhà vua ban thưởng cho Yết Kiêu rất hậu. Về sau, dân làng Hạ Bì lập đền thờ chàng và kể mãi câu chuyện về người anh hùng lặn giỏi nhất nước Nam."
      },
      "dua-thuyen": {
        title: "Hội đua thuyền trên sông quê (bài viết của một học sinh)",
        text: "Sáng mồng 4 Tết, tôi theo ông nội ra bến sông đầu làng xem hội đua thuyền. Hội được tổ chức hằng năm để cầu một năm mưa thuận gió hoà, sông nước hiền hoà với người làm nghề chài lưới.\nMới bảy giờ, hai bờ sông đã chật kín người. Sáu chiếc thuyền của sáu xóm, mỗi thuyền mười hai tay chèo áo đỏ, áo xanh, xếp hàng ngang trước vạch xuất phát. Đúng tám giờ, một hồi trống nổi lên, cờ lệnh phất xuống. Sáu chiếc thuyền lao vút đi như những mũi tên. Người cầm lái gõ nhịp, các tay chèo cúi rạp xuống, mái chèo khua nước trắng xoá. Trên bờ, người xem hò reo, gõ thùng, gõ chậu cổ vũ cho xóm mình.\nThuyền phải đi hai vòng sông, dài gần bốn cây số. Đến vòng cuối, thuyền xóm Đông và xóm Bắc kèm nhau từng sải chèo. Gần tới đích, xóm Đông vượt lên, cán đích trước chỉ một mũi thuyền. Chín giờ rưỡi, ban tổ chức trao giải ngay trên bến: xóm thắng được một lá cờ đỏ và một con lợn quay.\nÔng tôi bảo, thắng thua không quan trọng; năm nào cả làng cũng mong đến hội để thấy sông quê vui như vậy."
      },
      "but-than": {
        title: "Cây bút thần (truyện cổ tích, kể lại)",
        text: "Ngày xưa, ở một làng nọ bên Trung Quốc, có cậu bé Mã Lương mồ côi cha mẹ, sống bằng nghề kiếm củi, cắt cỏ. Cậu rất thích vẽ nhưng nghèo đến nỗi không có nổi một cây bút. Cậu lấy que củi vẽ xuống đất, lấy ngón tay nhúng nước vẽ lên đá, ngày nào cũng tập. Một đêm, trong giấc mơ, một cụ già râu tóc bạc phơ trao cho cậu một cây bút sáng lấp lánh và nói: “Đây là cây bút thần. Hãy dùng nó để giúp người nghèo.” Tỉnh dậy, Mã Lương thấy cây bút trong tay thật. Cậu vẽ con chim, chim bay lên; vẽ con cá, cá quẫy xuống nước.\nTừ đó, Mã Lương vẽ cho dân làng cày, cuốc, đèn, thùng nước, vẽ gì có nấy. Tin đồn đến tai một tên địa chủ tham lam. Hắn bắt cậu về, bắt vẽ vàng bạc cho hắn. Mã Lương không chịu, bị nhốt vào chuồng ngựa. Cậu vẽ một cái thang trèo ra, vẽ một con ngựa phóng đi. Rồi chuyện đến tai nhà vua. Vua bắt cậu vẽ núi vàng, cậu vẽ núi đá; bắt vẽ thỏi vàng, cậu vẽ con mãng xà. Vua tức giận cướp bút, nhưng bút trong tay vua chỉ ra toàn đống đá. Vua đành dỗ ngọt, hứa thưởng nhiều vàng bạc. Mã Lương giả vờ nhận lời. Cậu vẽ biển, vẽ thuyền, nhà vua và quan lại kéo nhau xuống thuyền đi dạo. Mã Lương vẽ thêm gió. Gió mỗi lúc một to, sóng mỗi lúc một lớn, con thuyền chở vua lật nhào giữa biển.\nSau đó, không ai biết Mã Lương đi đâu. Có người bảo cậu về quê, lại có người bảo cậu đi khắp nơi, dùng cây bút thần để vẽ cho những người nghèo khổ."
      },
      "cuc-trang": {
        title: "Bông hoa cúc trắng (truyện cổ tích, kể lại)",
        text: "Ngày xưa, có hai mẹ con nhà nọ sống trong một túp lều nhỏ. Người mẹ bị bệnh nặng, cô bé ngày đêm chăm sóc mẹ. Một hôm, có ông cụ đi ngang qua, nhìn người mẹ rồi bảo cô bé: “Cháu hãy lên núi, tìm bông hoa trắng ở phía mặt trời lặn. Bông hoa có bao nhiêu cánh thì mẹ cháu sống thêm được bấy nhiêu ngày.”\nCô bé lập tức lên đường. Trèo qua bao dốc đá, cô mới tìm được bông hoa trắng nhỏ xíu mọc trong khe đá. Cô đếm: bông hoa chỉ có bốn cánh. Nghĩ đến mẹ chỉ còn sống được bốn ngày, cô bật khóc. Rồi cô ngồi xuống, nhẹ nhàng xé mỗi cánh hoa thành nhiều sợi nhỏ. Mỗi sợi nhỏ lại thành một cánh hoa. Bông hoa giờ có vô số cánh, nhiều đến nỗi không đếm xuể.\nCô bé mang bông hoa về. Lạ thay, mẹ cô khoẻ lại và sống bên cô rất lâu. Từ đó, người ta gọi loài hoa trắng nhiều cánh ấy là hoa cúc trắng, xem nó như biểu tượng của lòng hiếu thảo."
      }
    },
    questions: [
      { topic: "Chuyện kể về những người anh hùng", type: "mc", q: "Theo văn bản, Yết Kiêu đánh giặc Nguyên bằng cách nào?", o: ["Đêm đêm lặn xuống sông, đục thủng đáy thuyền giặc", "Chỉ huy đoàn thuyền chiến của triều đình xông vào trận", "Dùng cung tên bắn từ trên bờ xuống thuyền giặc", "Cưỡi trâu thần húc đổ thuyền giặc"], x: "Văn bản kể: Yết Kiêu xin vua một chiếc dùi sắt và một chiếc búa, “rồi đêm đêm lặn xuống sông, lặng lẽ đục thủng đáy thuyền giặc”. Hai con trâu thần chỉ để lại mấy sợi lông, không ra trận cùng chàng.", lv: 1, p: "yet-kieu" },
      { topic: "Chuyện kể về những người anh hùng", type: "mc", q: "Khi bị bắt, Yết Kiêu trả lời tướng giặc: «Nhiều lắm, ta chỉ là kẻ kém nhất.» Câu trả lời ấy cho thấy điều gì ở nhân vật?", o: ["Mưu trí và khí phách: vừa khiến giặc hoang mang, khiếp sợ, vừa tìm cơ hội thoát thân", "Khiêm tốn thật thà, vì chàng lặn kém nhiều người khác trong làng", "Sợ hãi, muốn đổ trách nhiệm cho những người lặn giỏi khác", "Kiêu ngạo, muốn khoe nước Nam có nhiều người tài"], x: "Yết Kiêu là người lặn giỏi nhất, nhưng cố ý nói mình “kém nhất” để giặc tin nước Nam còn vô số người như thế mà hoảng sợ, đồng thời giả vờ nhận lời dẫn đường để được đưa ra sông rồi trốn thoát. Đó là sự mưu trí, gan dạ chứ không phải khiêm tốn hay sợ hãi.", lv: 2, p: "yet-kieu" },
      { topic: "Chuyện kể về những người anh hùng", type: "tf4", q: "Dựa vào đặc điểm của truyền thuyết, mỗi nhận xét sau về văn bản «Yết Kiêu» đúng hay sai?", o: ["Nhân vật và sự kiện trong truyện gắn với lịch sử: cuộc kháng chiến chống quân Nguyên thời nhà Trần.", "Chi tiết nuốt lông trâu thần rồi đi lại dưới nước như trên cạn là yếu tố kì ảo.", "Truyện gồm ba phần gắn với cuộc đời nhân vật: hoàn cảnh xuất thân, chiến công, kết cục được tôn vinh.", "Truyện được kể theo ngôi thứ nhất, người kể là Yết Kiêu."], a: [true, true, true, false], x: "a) Đúng: nhà Trần, giặc Nguyên là những yếu tố lịch sử. b) Đúng: đó là chi tiết không có thật, tô đậm tài năng phi thường của người anh hùng. c) Đúng: đoạn 1 kể xuất thân và việc gặp trâu thần, đoạn 2 kể chiến công đục thuyền giặc, đoạn 3 kể việc được ban thưởng, lập đền thờ. d) Sai: người kể giấu mình, gọi nhân vật là “chàng”, “Yết Kiêu”: ngôi thứ ba.", lv: 3, p: "yet-kieu" },
      { topic: "Chuyện kể về những người anh hùng", type: "mc", q: "Yết Kiêu và Thánh Gióng có điểm gì giống nhau với tư cách là nhân vật của truyền thuyết?", o: ["Đều có sức mạnh phi thường nhờ yếu tố kì ảo và lập chiến công đánh giặc vì cộng đồng", "Đều ra đời một cách kì lạ và lên ba tuổi vẫn chưa biết nói", "Đều cưỡi ngựa sắt và bay về trời sau khi thắng giặc", "Đều là vua, trực tiếp chỉ huy quân đội đánh giặc"], x: "Yết Kiêu nuốt lông trâu thần nên lặn được dưới nước, Thánh Gióng vươn vai thành tráng sĩ: cả hai đều có sức mạnh phi thường nhờ yếu tố kì ảo và dùng sức mạnh ấy để đánh giặc cứu nước, được nhân dân lập đền thờ. Chi tiết ra đời kì lạ, ngựa sắt, bay về trời chỉ có ở Thánh Gióng; cả hai đều không phải là vua.", lv: 3, p: "yet-kieu" },
      { topic: "Chuyện kể về những người anh hùng", type: "mc", q: "Theo bài viết, hội đua thuyền được tổ chức vào thời gian nào?", o: ["Sáng mồng 4 Tết, trên sông đầu làng", "Chiều mồng 10 tháng Giêng, trên biển", "Sáng rằm tháng Tám, trên hồ", "Chiều mồng 4 Tết, trên sông đầu làng"], x: "Câu mở đầu: “Sáng mồng 4 Tết, tôi theo ông nội ra bến sông đầu làng xem hội đua thuyền.” Cuộc đua bắt đầu lúc tám giờ và trao giải lúc chín giờ rưỡi sáng.", lv: 1, p: "dua-thuyen" },
      { topic: "Chuyện kể về những người anh hùng", type: "mc", q: "Chi tiết nào trong bài viết cho thấy rõ nhất không khí sôi nổi của cuộc đua?", o: ["Người xem hò reo, gõ thùng, gõ chậu cổ vũ; hai thuyền kèm nhau từng sải chèo đến gần đích", "Hội được tổ chức để cầu mưa thuận gió hoà", "Mỗi thuyền có mười hai tay chèo", "Xóm thắng được một lá cờ đỏ và một con lợn quay"], x: "Cảnh người xem hò reo, gõ thùng, gõ chậu và cuộc rượt đuổi sát nút giữa xóm Đông và xóm Bắc làm nổi bật không khí sôi nổi, hồi hộp. Các chi tiết còn lại chỉ là thông tin về mục đích, số tay chèo và giải thưởng.", lv: 2, p: "dua-thuyen" },
      { topic: "Chuyện kể về những người anh hùng", type: "tf4", q: "Mỗi nhận xét sau về bài viết «Hội đua thuyền trên sông quê» đúng hay sai?", o: ["Bài viết thuật lại sự kiện theo trình tự thời gian, có nêu rõ giờ (bảy giờ, tám giờ, chín giờ rưỡi).", "Người viết là người chứng kiến, xưng “tôi” khi tường thuật.", "Chi tiết sáu chiếc thuyền “lao vút đi như những mũi tên” là yếu tố kì ảo của văn bản.", "Đoạn cuối nêu cảm nghĩ về ý nghĩa của hội đua thuyền qua lời của ông nội."], a: [true, true, false, true], x: "a) Đúng: các mốc giờ được nêu theo thứ tự diễn ra. b) Đúng: người viết đi xem hội cùng ông nội và kể lại bằng ngôi thứ nhất. c) Sai: đó chỉ là cách nói để tả tốc độ của thuyền, không phải chi tiết hoang đường. d) Đúng: lời ông nội ở đoạn cuối nói lên ý nghĩa của hội với cả làng.", lv: 3, p: "dua-thuyen" },
      { topic: "Thế giới cổ tích", type: "mc", q: "Theo văn bản, Mã Lương có cây bút thần từ đâu?", o: ["Do một cụ già trao cho trong giấc mơ, tỉnh dậy thấy bút thật trong tay", "Do tên địa chủ thưởng vì cậu vẽ đẹp", "Do cậu tự làm từ que củi và lông chim", "Do nhà vua ban cho để vẽ núi vàng"], x: "Văn bản kể: trong giấc mơ, một cụ già râu tóc bạc phơ trao cho cậu cây bút sáng lấp lánh và dặn dùng nó giúp người nghèo; “Tỉnh dậy, Mã Lương thấy cây bút trong tay thật.”", lv: 1, p: "but-than" },
      { topic: "Thế giới cổ tích", type: "mc", q: "Vì sao Mã Lương vẽ cày, cuốc, đèn, thùng nước cho dân làng mà không chịu vẽ vàng bạc cho địa chủ và nhà vua?", o: ["Vì cậu dùng bút thần để giúp người nghèo như lời cụ già dặn, không tiếp tay cho kẻ tham lam", "Vì cây bút thần chỉ vẽ được đồ dùng, không vẽ được vàng bạc", "Vì cậu sợ vẽ vàng bạc sẽ bị cụ già đòi lại cây bút", "Vì dân làng trả công cho cậu nhiều hơn địa chủ và nhà vua"], x: "Cụ già dặn “Hãy dùng nó để giúp người nghèo.” Mã Lương làm đúng lời ấy: vẽ đồ dùng cho dân làng, còn với địa chủ và vua tham lam thì vẽ núi đá, mãng xà và cuối cùng vẽ biển, vẽ gió để trừng trị. Bút thần vẽ gì có nấy, nên không phải vì bút không vẽ được vàng.", lv: 2, p: "but-than" },
      { topic: "Thế giới cổ tích", type: "tf4", q: "Dựa vào đặc điểm của truyện cổ tích, mỗi nhận xét sau về văn bản «Cây bút thần» đúng hay sai?", o: ["Mã Lương là nhân vật chính diện; tên địa chủ và nhà vua là nhân vật phản diện.", "Vẽ chim thì chim bay lên, vẽ gió thì gió nổi lên là những chi tiết hoang đường, kì ảo.", "Truyện kể về một sự kiện lịch sử có thật của nước Trung Quốc.", "Kết thúc truyện, kẻ tham lam bị trừng trị, còn Mã Lương tiếp tục dùng bút giúp người nghèo."], a: [true, true, false, true], x: "a) Đúng: Mã Lương chăm chỉ, nhân hậu; địa chủ và vua tham lam, độc ác. b) Đúng: đó là những phép màu không có thật. c) Sai: truyện cổ tích kể về số phận nhân vật qua tưởng tượng, không gắn với sự kiện lịch sử như truyền thuyết. d) Đúng: thuyền của vua bị lật, Mã Lương đi vẽ cho người nghèo khắp nơi.", lv: 3, p: "but-than" },
      { topic: "Thế giới cổ tích", type: "mc", q: "Qua hình ảnh cây bút thần chỉ phát huy phép màu trong tay Mã Lương, còn trong tay nhà vua “chỉ ra toàn đống đá”, tác giả dân gian muốn gửi gắm điều gì?", o: ["Tài năng và phép màu chỉ phục vụ người lương thiện, không thuộc về kẻ tham lam", "Nhà vua chưa học vẽ nên không dùng được bút", "Cây bút chỉ hoạt động vào ban đêm", "Người nghèo thì vẽ đẹp hơn người giàu"], x: "Bút thần được trao cho Mã Lương để giúp người nghèo; vua cướp bút nhưng không dùng được. Chi tiết thể hiện quan niệm: tài năng, điều kì diệu phải đi cùng tấm lòng lương thiện, kẻ tham lam dù chiếm đoạt cũng không có được.", lv: 3, p: "but-than" },
      { topic: "Thế giới cổ tích", type: "mc", q: "Theo văn bản, khi thấy bông hoa chỉ có bốn cánh, cô bé đã làm gì?", o: ["Xé mỗi cánh hoa thành nhiều sợi nhỏ để bông hoa có vô số cánh", "Đi tìm một bông hoa khác có nhiều cánh hơn", "Mang bông hoa về nhà và khóc suốt bốn ngày", "Nhờ ông cụ làm phép cho bông hoa thêm cánh"], x: "Văn bản kể: cô bé “nhẹ nhàng xé mỗi cánh hoa thành nhiều sợi nhỏ. Mỗi sợi nhỏ lại thành một cánh hoa”, nhờ đó bông hoa có nhiều cánh không đếm xuể.", lv: 1, p: "cuc-trang" },
      { topic: "Thế giới cổ tích", type: "mc", q: "Việc cô bé xé cánh hoa thành nhiều sợi nhỏ cho thấy điều gì ở nhân vật?", o: ["Lòng hiếu thảo và mong ước mẹ được sống lâu", "Sự nghịch ngợm, thích phá hỏng bông hoa", "Tính tham lam, muốn có nhiều hoa hơn người khác", "Sự vụng về, không biết giữ gìn bông hoa quý"], x: "Mỗi cánh hoa là một ngày mẹ sống thêm, nên cô bé xé cánh hoa thành nhiều sợi để mẹ sống lâu hơn. Hành động ấy xuất phát từ tình yêu thương và lòng hiếu thảo với mẹ.", lv: 2, p: "cuc-trang" },
      { topic: "Thế giới cổ tích", type: "tf4", q: "Mỗi nhận xét sau về văn bản «Bông hoa cúc trắng» đúng hay sai?", o: ["Ông cụ biết trước số ngày người mẹ còn sống và mỗi sợi hoa xé ra lại thành một cánh là chi tiết kì ảo.", "Truyện giải thích nguồn gốc của hoa cúc trắng và gắn loài hoa với lòng hiếu thảo.", "Truyện được kể theo ngôi thứ nhất, cô bé xưng “tôi”.", "Kết thúc truyện có hậu: người mẹ khoẻ lại và sống lâu bên con."], a: [true, true, false, true], x: "a) Đúng: đó là những chi tiết không có thật. b) Đúng: câu cuối nói từ đó người ta gọi loài hoa ấy là hoa cúc trắng, biểu tượng của lòng hiếu thảo. c) Sai: người kể giấu mình, gọi nhân vật là “cô bé”, “người mẹ”: ngôi thứ ba. d) Đúng: tấm lòng của cô bé được đền đáp.", lv: 3, p: "cuc-trang" },
      { topic: "Nghĩa của từ", type: "mc", q: "Yếu tố «sơn» trong «Sơn Tinh» có nghĩa là núi. Từ nào dưới đây có yếu tố «sơn» mang nghĩa ấy?", o: ["giang sơn", "sơn mài", "nước sơn", "thợ sơn"], x: "“Giang sơn” (sông núi, chỉ đất nước) có “sơn” là núi. Trong “sơn mài”, “nước sơn”, “thợ sơn”, “sơn” là chất liệu quét lên bề mặt đồ vật cho đẹp, bền.", lv: 1 },
      { topic: "Nghĩa của từ", type: "match", q: "Nối mỗi từ Hán Việt với nghĩa của nó.", l: ["độc giả", "thuỷ quân", "quốc ca"], r: ["Người đọc sách, báo", "Quân đội chiến đấu trên sông, biển", "Bài hát chính thức của một nước", "Người xem biểu diễn"], x: "Độc giả: độc là đọc, giả là người → người đọc. Thuỷ quân: thuỷ là nước, quân là quân đội → quân chiến đấu trên sông, biển. Quốc ca: quốc là nước, ca là bài hát → bài hát chính thức của một nước. Người xem biểu diễn là khán giả, không nối với từ nào.", lv: 2 },
      { topic: "Nghĩa của từ", type: "mc", q: "Đọc câu: «Dù mọi người hết lời can ngăn, cậu vẫn khăng khăng giữ ý mình.» Dựa vào các từ ngữ xung quanh, «khăng khăng» có nghĩa là:", o: ["Nhất định giữ ý kiến của mình, không chịu thay đổi", "Vui vẻ nghe theo lời khuyên của mọi người", "Băn khoăn, chưa biết nên quyết định thế nào", "Nói to để mọi người cùng nghe"], x: "“Dù mọi người hết lời can ngăn” mà cậu “vẫn … giữ ý mình”: ngữ cảnh cho thấy cậu nhất định không đổi ý. Đó là nghĩa của “khăng khăng”.", lv: 2 },
      { topic: "Từ đơn và từ phức", type: "mc", q: "Dòng nào dưới đây gồm toàn từ ghép?", o: ["xóm làng, ruộng đồng, cày cấy", "lao xao, ruộng đồng, cày cấy", "xóm làng, lao xao, rì rầm", "rì rầm, lao xao, thì thầm"], x: "“Xóm làng”, “ruộng đồng”, “cày cấy” đều gồm hai tiếng có nghĩa ghép lại: từ ghép. “Lao xao”, “rì rầm”, “thì thầm” là từ láy (các tiếng giống nhau về âm đầu hoặc vần).", lv: 1 },
      { topic: "Từ đơn và từ phức", type: "tf4", q: "Mỗi nhận xét sau về các từ trong câu «Những tráng sĩ cưỡi ngựa phi vun vút qua cánh đồng.» đúng hay sai?", o: ["“vun vút” là từ láy.", "“tráng sĩ” là từ ghép.", "“cánh đồng” là từ láy.", "“cưỡi” là từ phức."], a: [true, true, false, false], x: "a) Đúng: hai tiếng lặp lại âm đầu “v”, tiếng “vun” không có nghĩa riêng ở đây: từ láy. b) Đúng: “tráng” (khoẻ mạnh) và “sĩ” (người) đều có nghĩa, ghép lại chỉ người khoẻ mạnh, dũng cảm. c) Sai: “cánh”, “đồng” đều có nghĩa, là từ ghép. d) Sai: “cưỡi” chỉ có một tiếng, là từ đơn.", lv: 1 },
      { topic: "Từ đơn và từ phức", type: "mc", q: "Từ «thênh thang» trong câu «Con đường làng thênh thang trong nắng.» là:", o: ["Từ láy", "Từ ghép", "Từ đơn", "Cụm danh từ"], x: "“Thênh thang” có hai tiếng giống nhau ở âm đầu “th”, tiếng “thênh” không có nghĩa riêng: từ láy, gợi tả không gian rộng rãi, thoáng đãng.", lv: 1 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "mc", q: "Dòng nào dưới đây là cụm động từ?", o: ["vừa đánh tan quân giặc", "những người lính trẻ", "rất đông và rất vui", "hai chiếc thuyền lớn"], x: "“Vừa đánh tan quân giặc” có động từ “đánh” làm trung tâm, “vừa” chỉ thời gian, “tan quân giặc” chỉ kết quả, đối tượng: cụm động từ. “Những người lính trẻ”, “hai chiếc thuyền lớn” là cụm danh từ; “rất đông và rất vui” là hai cụm tính từ.", lv: 1 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "mc", q: "Trong câu «Dân làng vui mừng khôn xiết khi thấy đoàn quân trở về.», cụm từ “vui mừng khôn xiết” là:", o: ["Cụm tính từ", "Cụm động từ", "Cụm danh từ", "Một từ láy"], x: "Tính từ “vui mừng” làm trung tâm, “khôn xiết” đứng sau chỉ mức độ (không kể xiết): đó là cụm tính từ.", lv: 1 },
      { topic: "Cụm danh từ, cụm động từ, cụm tính từ", type: "tf", q: "«Hai con trâu trắng» là một cụm danh từ.", a: true, x: "Đúng. Danh từ “trâu” làm trung tâm; “hai con” đứng trước chỉ số lượng, “trắng” đứng sau nêu đặc điểm.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Câu «Nắng nhảy nhót trên những lá cờ hội.» dùng biện pháp tu từ nào?", o: ["Nhân hoá", "So sánh", "Điệp ngữ", "Hoán dụ"], x: "Nắng được gán hoạt động của người, của trẻ con (“nhảy nhót”): đó là biện pháp nhân hoá, làm cảnh ngày hội thêm vui tươi.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "tf", q: "Câu «Lá cờ đỏ phấp phới như một ngọn lửa trên đỉnh cột.» dùng biện pháp so sánh.", a: true, x: "Đúng. Câu đối chiếu lá cờ đỏ đang bay với ngọn lửa (cùng màu đỏ, cùng chuyển động), có từ so sánh “như”.", lv: 1 },
      { topic: "Biện pháp tu từ", type: "mc", q: "Đọc đoạn: «Giặc đến! Giặc đốt nhà. Giặc cướp của. Giặc bắt người.» Việc lặp lại từ “giặc” ở đầu các câu có tác dụng gì?", o: ["Nhấn mạnh tội ác chồng chất của giặc và nỗi căm giận của nhân dân", "Giới thiệu tên gọi của quân giặc cho người đọc", "Làm cho đoạn văn dài hơn để đủ số chữ", "Tả quân giặc đi nhanh như gió"], x: "Từ “giặc” lặp lại bốn lần ở đầu câu, mỗi lần gắn với một tội ác, làm tội ác của giặc hiện lên dồn dập, chồng chất và tăng nỗi căm giận trong lòng người đọc.", lv: 2 },
      { topic: "Dấu câu", type: "tf4", q: "Đọc câu: «Đồ lễ gồm: xôi gấc, gà luộc; hoa quả, bánh kẹo; trầu cau, rượu nếp.» Mỗi nhận xét sau đúng hay sai?", o: ["Câu liệt kê ba nhóm đồ lễ, các nhóm được ngăn bằng dấu chấm phẩy.", "Có thể thay cả hai dấu chấm phẩy bằng dấu phẩy mà vẫn thấy rõ ranh giới các nhóm.", "Dấu hai chấm báo hiệu phần liệt kê phía sau.", "Dấu chấm phẩy ở đây dùng để đánh dấu lời nói trực tiếp."], a: [true, false, true, false], x: "a) Đúng: ba nhóm (xôi gấc, gà luộc / hoa quả, bánh kẹo / trầu cau, rượu nếp) ngăn bằng dấu chấm phẩy. b) Sai: nếu dùng toàn dấu phẩy, người đọc không phân biệt được món nào thuộc nhóm nào. c) Đúng: dấu hai chấm đứng trước phần liệt kê. d) Sai: câu không có lời nhân vật; dấu chấm phẩy chỉ tách các bộ phận của chuỗi liệt kê.", lv: 2 },
      { topic: "Dấu câu", type: "mc", q: "Chọn dấu câu thích hợp cho vị trí (1) và (2) trong câu: «Buổi sáng, chúng tôi dọn vệ sinh lớp học, lau bàn ghế (1) buổi chiều, chúng tôi trồng cây, tưới hoa ở vườn trường (2) buổi tối, mỗi người viết một đoạn cảm nghĩ.»", o: ["(1) dấu chấm phẩy, (2) dấu chấm phẩy", "(1) dấu phẩy, (2) dấu phẩy", "(1) dấu hai chấm, (2) dấu hai chấm", "(1) dấu chấm phẩy, (2) dấu hai chấm"], x: "Câu liệt kê ba buổi, mỗi buổi đã có dấu phẩy bên trong, nên ranh giới giữa các buổi cần dấu chấm phẩy ở cả hai vị trí. Dùng dấu phẩy sẽ lẫn các bộ phận với nhau; dấu hai chấm không dùng để tách các bộ phận liệt kê.", lv: 2 },
      { topic: "Viết", type: "essay", q: "Viết một đoạn thân bài (khoảng 150–200 chữ) cho bài văn thuyết minh thuật lại lễ khai giảng năm học ở trường bạn, trình bày các hoạt động theo trình tự thời gian.", rubric: [{ c: "Thuật lại được các hoạt động chính của buổi lễ theo trình tự thời gian (đón học sinh, chào cờ, đọc thư, đánh trống khai trường, văn nghệ…), có mốc thời gian hoặc từ ngữ nối (“đúng 7 giờ 30”, “sau đó”, “cuối cùng”)", p: 1.5 }, { c: "Nêu được bối cảnh: thời gian, địa điểm, người tham dự", p: 0.5 }, { c: "Có ít nhất hai chi tiết tiêu biểu, cụ thể (âm thanh, màu sắc, hành động, lời nói)", p: 1 }, { c: "Dùng ngôi tường thuật phù hợp và nhất quán (“tôi”, “chúng tôi”); giọng kể rõ ràng, khách quan, không hư cấu", p: 0.5 }, { c: "Đúng hình thức đoạn văn (khoảng 150–200 chữ); dùng từ đúng, viết đúng chính tả", p: 0.5 }], x: "Đoạn văn cần: nêu bối cảnh, rồi kể lần lượt các hoạt động theo thời gian, mỗi hoạt động có một chi tiết cụ thể; không thêm chi tiết tưởng tượng.\nĐoạn văn tham khảo:\nĐúng bảy giờ ba mươi sáng ngày 5 tháng 9, toàn trường tôi đã xếp hàng ngay ngắn trên sân, học sinh khối 6 chúng tôi ngồi ở hàng đầu. Mở đầu buổi lễ, các anh chị lớp 9 cầm cờ hoa đi dọc sân đón các em lớp 6, cả sân trường vỗ tay vang dội. Tiếp theo là lễ chào cờ; tiếng Quốc ca cất lên, ai cũng đứng nghiêm, mắt hướng về lá cờ đỏ đang từ từ được kéo lên. Sau đó, cô hiệu trưởng đọc thư chúc mừng năm học mới và tuyên bố khai giảng. Khoảnh khắc được chờ đợi nhất là lúc cô cầm dùi nện ba hồi trống dài; tiếng trống trầm ấm vang khắp sân, báo hiệu năm học mới bắt đầu. Cuối cùng là phần văn nghệ: tiết mục múa quạt của lớp 7A và bài hát về mái trường do đội văn nghệ biểu diễn. Gần chín giờ, buổi lễ kết thúc, chúng tôi theo cô chủ nhiệm về lớp nhận thời khoá biểu, lòng háo hức bước vào năm học đầu tiên ở trường mới.", lv: 3 },
      { topic: "Viết", type: "essay", q: "Đóng vai công chúa trong truyện «Vua chích choè», viết một đoạn văn (khoảng 150–200 chữ) kể lại những ngày bạn phải sống nghèo khổ sau khi bị vua cha gả cho người hát rong.", rubric: [{ c: "Kể theo ngôi thứ nhất, người kể xưng “tôi” hoặc “ta” và nhập vai công chúa từ đầu đến cuối đoạn", p: 1 }, { c: "Kể đúng các sự việc chính của truyện gốc: theo người hát rong về túp lều nghèo, phải tự nấu ăn, đan sọt, kéo sợi, đi bán sành sứ ở chợ, làm việc trong bếp của hoàng cung", p: 1.5 }, { c: "Có sáng tạo thêm chi tiết tưởng tượng, miêu tả (cảnh túp lều, nỗi vất vả, lời nói của người hát rong) nhưng không làm sai cốt truyện", p: 0.5 }, { c: "Nêu được cảm xúc, suy nghĩ của nhân vật: hối hận về tính kiêu ngạo, nhận ra giá trị của lao động", p: 0.5 }, { c: "Đúng hình thức đoạn văn (khoảng 150–200 chữ); dùng từ đúng, viết đúng chính tả", p: 0.5 }], x: "Đoạn văn cần: xưng “tôi” (công chúa), kể lần lượt các việc phải làm trong những ngày nghèo khổ theo đúng truyện, thêm vài chi tiết tả cảnh, tả cảm xúc; nêu sự thay đổi trong suy nghĩ của công chúa; không đổi cốt truyện (chưa cần kể đến đoạn nhận ra Vua chích choè).\nĐoạn văn tham khảo:\nTôi là công chúa trong câu chuyện «Vua chích choè». Chỉ vì thói kiêu ngạo, hay giễu cợt người khác, tôi bị vua cha gả cho một người hát rong và phải rời cung điện ngay trong đêm. Túp lều mà chồng tôi dẫn về chỉ có một chiếc giường ọp ẹp, không có lấy một người hầu. Tôi lóng ngóng nhóm lửa, nấu một nồi cháo khê. Anh bảo tôi đan sọt, những thanh tre cứa vào tay tôi rớm máu; bảo tôi kéo sợi, sợi cứ đứt mãi. Rồi tôi phải mang sành sứ ra chợ bán. Hôm ấy, một người lính say rượu phi ngựa qua, dẫm nát cả gánh hàng của tôi. Tôi ngồi khóc giữa chợ, nhớ những bữa tiệc trong cung. Cuối cùng, tôi xin làm phụ bếp ở hoàng cung, ngày ngày rửa bát, nhặt rau, tối giấu thức ăn thừa trong túi mang về. Những ngày ấy, tôi mới hiểu một bát cơm phải đổi bằng bao nhiêu mồ hôi, và những người tôi từng chế giễu đã sống vất vả thế nào. Tôi thấy hối hận vô cùng.", lv: 3 },
      { topic: "Viết", type: "essay", q: "Chọn một truyện cổ tích bạn đã đọc («Thạch Sanh», «Cây khế», «Sọ Dừa», «Tấm Cám»…) và một nhân vật trong truyện đó. Viết phần mở bài (khoảng 5–7 câu, 80–120 chữ) cho bài văn đóng vai nhân vật ấy kể lại câu chuyện.", rubric: [{ c: "Người kể xưng “tôi” hoặc “ta”, nhập đúng vai một nhân vật có trong truyện đã chọn", p: 1 }, { c: "Giới thiệu được bản thân nhân vật (tên, hoàn cảnh hoặc thân phận) phù hợp với truyện gốc", p: 1 }, { c: "Dẫn dắt vào câu chuyện sắp kể, gợi được sự tò mò cho người đọc (một lời mời, một câu hỏi, một kỉ niệm)", p: 1 }, { c: "Có thể thêm chi tiết tưởng tượng, biểu cảm nhưng không làm sai các yếu tố cơ bản của truyện gốc", p: 0.5 }, { c: "Đúng độ dài (5–7 câu); dùng từ đúng, viết đúng chính tả", p: 0.5 }], x: "Mở bài cần: xưng “tôi”, giới thiệu mình là ai trong truyện, rồi mời người đọc nghe câu chuyện; chưa kể vào diễn biến chính.\nMở bài tham khảo (đóng vai cô Tấm):\nCác bạn có biết tôi là ai không? Tôi là Tấm, cô gái mồ côi mẹ từ nhỏ, sống với dì ghẻ và cô em cùng cha khác mẹ tên là Cám. Ngày ngày tôi chăn trâu, cắt cỏ, mò cua bắt ốc, còn Cám chỉ việc rong chơi. Nhiều người đã kể chuyện đời tôi theo cách của họ, nhưng chưa ai nghe chính tôi kể. Hôm nay, tôi muốn kể lại những ngày gian khổ ấy và cả những phép màu mà ông Bụt đã dành cho tôi. Các bạn hãy lắng nghe nhé!", lv: 3 }
    ]
  }
});
